import type { LocalizedString } from '~/lib/domain'
import { L } from '../../locale'

/** Generated TOPIK 4 usage-note shard 2/5. */
export const USAGE_NOTES: Record<string, LocalizedString> = {
  '-은/는 물론이고': L(
      'Means "of course X, and also Y" — you state something so obvious it goes without saying, then add a second (often more surprising) item on top. It attaches to a NOUN: bare-final-vowel nouns take -는 물론이고 (외국어는 물론이고 "foreign languages of course, and..."), and 받침 nouns take -은 물론이고 (한국말은 물론이고 "Korean of course, and..."). So 그 가게는 커피는 물론이고 디저트도 유명해요 "That shop is famous for its coffee of course, and its desserts too." The added item very often carries -도 ("also"), e.g. 주말은 물론이고 평일에도 바빠요 "I\'m busy on the weekend of course, and on weekdays too" → naturally 주말은 물론이고 평일에도 손님이 많아요. You\'ll also hear the shorter 은/는 물론 with the 이고 dropped.\n\nThe closest neighbor to watch is -뿐만 아니라 ("not only... but also"). Both add a second item, but 물론이고 frames the first item as utterly taken for granted, while 뿐만 아니라 just neutrally says "not only A": 그는 영어는 물론이고 중국어도 잘해요 vs. 그는 영어뿐만 아니라 중국어도 잘해요 — the first nuance is "English? obviously — and Chinese too," the second is plain "not only English but Chinese." Register is neutral-to-formal and very common in writing and presentations. The most common learner mistake is attaching it to a verb (X 가는 물론이고); for verbs you must nominalize first (가는 것은 물론이고) or switch to -을 뿐만 아니라. Also don\'t drop the -도 on the second item — 물론이고 strongly expects that paired "also."',
      'Significa "claro que X, y además Y": decís algo tan obvio que ni hace falta mencionarlo y luego le sumás un segundo elemento (a menudo más sorprendente) por encima. Se adjunta a un SUSTANTIVO: los sustantivos terminados en vocal toman -는 물론이고 (외국어는 물론이고 "los idiomas extranjeros por supuesto, y..."), y los sustantivos con 받침 toman -은 물론이고 (한국말은 물론이고 "el coreano por supuesto, y..."). Así, 그 가게는 커피는 물론이고 디저트도 유명해요 "esa tienda es famosa por su café por supuesto, y también por sus postres". El elemento añadido muy a menudo lleva -도 ("también"), p. ej. 주말은 물론이고 평일에도 바빠요 "estoy ocupado el fin de semana por supuesto, y también entre semana" → naturalmente 주말은 물론이고 평일에도 손님이 많아요. También vas a escuchar la forma más corta 은/는 물론 con el 이고 omitido.\n\nEl vecino más cercano que tenés que vigilar es -뿐만 아니라 ("no solo... sino también"). Ambos suman un segundo elemento, pero 물론이고 enmarca el primero como algo totalmente dado por sentado, mientras que 뿐만 아니라 solo dice de forma neutra "no solo A": 그는 영어는 물론이고 중국어도 잘해요 vs. 그는 영어뿐만 아니라 중국어도 잘해요 — el primer matiz es "¿inglés? obviamente, y chino también", el segundo es simplemente "no solo inglés sino chino". El registro es neutro-a-formal y muy común en la escritura y en presentaciones. El error más común del estudiante es adjuntarlo a un verbo (X 가는 물론이고); para los verbos tenés que nominalizar primero (가는 것은 물론이고) o cambiar a -을 뿐만 아니라. Tampoco omitas el -도 en el segundo elemento: 물론이고 espera con fuerza ese "también" emparejado.',
      'Signifie "bien sûr X, et aussi Y" : tu énonces quelque chose de tellement évident que cela va sans dire, puis tu ajoutes un second élément (souvent plus surprenant) par-dessus. Cela s\'attache à un NOM : les noms se terminant par une voyelle prennent -는 물론이고 (외국어는 물론이고 "les langues étrangères bien sûr, et..."), et les noms avec 받침 prennent -은 물론이고 (한국말은 물론이고 "le coréen bien sûr, et..."). Ainsi 그 가게는 커피는 물론이고 디저트도 유명해요 "cette boutique est réputée pour son café bien sûr, et aussi pour ses desserts". L\'élément ajouté porte très souvent -도 ("aussi"), par ex. 주말은 물론이고 평일에도 바빠요 "je suis occupé le week-end bien sûr, et aussi en semaine" → naturellement 주말은 물론이고 평일에도 손님이 많아요. Tu entendras aussi la forme plus courte 은/는 물론 avec le 이고 supprimé.\n\nLe voisin le plus proche à surveiller est -뿐만 아니라 ("non seulement... mais aussi"). Les deux ajoutent un second élément, mais 물론이고 présente le premier comme totalement allant de soi, tandis que 뿐만 아니라 dit simplement de façon neutre "non seulement A" : 그는 영어는 물론이고 중국어도 잘해요 vs. 그는 영어뿐만 아니라 중국어도 잘해요 — la première nuance est "l\'anglais ? évidemment, et le chinois aussi", la seconde est simplement "non seulement l\'anglais mais le chinois". Le registre est neutre-à-formel et très courant à l\'écrit et dans les présentations. L\'erreur la plus fréquente des apprenants est de l\'attacher à un verbe (X 가는 물론이고) ; pour les verbes tu dois d\'abord nominaliser (가는 것은 물론이고) ou passer à -을 뿐만 아니라. Et ne supprime pas le -도 sur le second élément : 물론이고 attend fortement ce "aussi" associé.',
      'Significa "claro que X, e também Y": você afirma algo tão óbvio que nem precisa ser dito e depois acrescenta um segundo item (muitas vezes mais surpreendente) por cima. Anexa-se a um SUBSTANTIVO: substantivos terminados em vogal levam -는 물론이고 (외국어는 물론이고 "línguas estrangeiras é claro, e..."), e substantivos com 받침 levam -은 물론이고 (한국말은 물론이고 "coreano é claro, e..."). Assim, 그 가게는 커피는 물론이고 디저트도 유명해요 "essa loja é famosa pelo café, é claro, e também pelas sobremesas". O item acrescentado muito frequentemente carrega -도 ("também"), por ex. 주말은 물론이고 평일에도 바빠요 "estou ocupado no fim de semana, é claro, e também nos dias de semana" → naturalmente 주말은 물론이고 평일에도 손님이 많아요. Você também vai ouvir a forma mais curta 은/는 물론 com o 이고 omitido.\n\nO vizinho mais próximo de que você deve cuidar é -뿐만 아니라 ("não só... mas também"). Ambos acrescentam um segundo item, mas 물론이고 enquadra o primeiro como algo totalmente tido como certo, enquanto 뿐만 아니라 apenas diz de forma neutra "não só A": 그는 영어는 물론이고 중국어도 잘해요 vs. 그는 영어뿐만 아니라 중국어도 잘해요 — a primeira nuance é "inglês? obviamente, e chinês também", a segunda é simplesmente "não só inglês, mas chinês". O registro é neutro a formal e muito comum na escrita e em apresentações. O erro mais comum de quem aprende é anexá-lo a um verbo (X 가는 물론이고); para verbos você precisa nominalizar primeiro (가는 것은 물론이고) ou trocar para -을 뿐만 아니라. E não omita o -도 no segundo item: 물론이고 espera fortemente esse "também" emparelhado.',
      'หมายถึง "X น่ะแน่นอนอยู่แล้ว แถมยังมี Y อีกด้วย" คือคุณพูดถึงสิ่งที่ชัดเจนจนไม่ต้องเอ่ยถึงก็ได้ แล้วจึงเพิ่มสิ่งที่สอง (ซึ่งมักจะน่าประหลาดใจกว่า) เข้าไปอีก โครงสร้างนี้ต่อท้าย "คำนาม": คำนามที่ลงท้ายด้วยสระจะใช้ -는 물론이고 (외국어는 물론이고 "ภาษาต่างประเทศน่ะแน่นอน แถม...") และคำนามที่มี 받침 จะใช้ -은 물론이고 (한국말은 물론이고 "ภาษาเกาหลีน่ะแน่นอน แถม...") ดังนั้น 그 가게는 커피는 물론이고 디저트도 유명해요 "ร้านนั้นกาแฟก็ดังอยู่แล้วแน่นอน แถมของหวานก็ดังด้วย" สิ่งที่เพิ่มเข้ามามักจะมี -도 ("ก็...ด้วย") กำกับอยู่ เช่น 주말은 물론이고 평일에도 바빠요 "วันหยุดน่ะยุ่งอยู่แล้วแน่นอน แถมวันธรรมดาก็ยุ่งด้วย" → โดยธรรมชาติคือ 주말은 물론이고 평일에도 손님이 많아요 นอกจากนี้คุณจะได้ยินรูปแบบที่สั้นกว่าคือ 은/는 물론 ที่ตัด 이고 ออกไป\n\nตัวที่ใกล้เคียงที่สุดที่ต้องระวังคือ -뿐만 아니라 ("ไม่เพียงแต่... แต่ยัง...") ทั้งคู่ต่างเพิ่มสิ่งที่สองเข้ามา แต่ 물론이고 จะวางสิ่งแรกในฐานะสิ่งที่ถือว่าเป็นเรื่องธรรมดาแน่นอนอยู่แล้ว ในขณะที่ 뿐만 아니라 เพียงบอกอย่างเป็นกลางว่า "ไม่เพียงแต่ A": 그는 영어는 물론이고 중국어도 잘해요 เทียบกับ 그는 영어뿐만 아니라 중국어도 잘해요 — อันแรกให้ความรู้สึกว่า "ภาษาอังกฤษน่ะเหรอ? แน่นอนอยู่แล้ว แล้วภาษาจีนก็เก่งด้วย" อันที่สองเป็นเพียง "ไม่เพียงแต่อังกฤษ แต่จีนด้วย" ระดับภาษาอยู่ในช่วงกลางถึงทางการ และพบบ่อยมากในงานเขียนและการนำเสนอ ข้อผิดพลาดที่ผู้เรียนทำบ่อยที่สุดคือนำไปต่อท้ายคำกริยา (X 가는 물론이고) สำหรับคำกริยา คุณต้องทำให้เป็นคำนามก่อน (가는 것은 물론이고) หรือเปลี่ยนไปใช้ -을 뿐만 아니라 และอย่าตัด -도 ที่สิ่งที่สองออก เพราะ 물론이고 คาดหวังคำว่า "ก็...ด้วย" ที่จับคู่กันนี้อย่างมาก',
      'Berarti "tentu saja X, dan juga Y": kamu menyebutkan sesuatu yang begitu jelas sampai tak perlu dikatakan, lalu menambahkan item kedua (sering kali lebih mengejutkan) di atasnya. Ini melekat pada KATA BENDA: kata benda yang berakhir dengan vokal memakai -는 물론이고 (외국어는 물론이고 "bahasa asing tentu saja, dan..."), sedangkan kata benda dengan 받침 memakai -은 물론이고 (한국말은 물론이고 "bahasa Korea tentu saja, dan..."). Jadi 그 가게는 커피는 물론이고 디저트도 유명해요 "toko itu terkenal dengan kopinya tentu saja, dan juga pencuci mulutnya". Item yang ditambahkan sangat sering membawa -도 ("juga"), mis. 주말은 물론이고 평일에도 바빠요 "saya sibuk di akhir pekan tentu saja, dan juga di hari kerja" → secara alami 주말은 물론이고 평일에도 손님이 많아요. Kamu juga akan mendengar bentuk yang lebih pendek 은/는 물론 dengan 이고 yang dihilangkan.\n\nTetangga terdekat yang harus kamu perhatikan adalah -뿐만 아니라 ("bukan hanya... tetapi juga"). Keduanya menambahkan item kedua, tetapi 물론이고 membingkai item pertama sebagai sesuatu yang benar-benar dianggap sudah pasti, sedangkan 뿐만 아니라 hanya secara netral berkata "bukan hanya A": 그는 영어는 물론이고 중국어도 잘해요 vs. 그는 영어뿐만 아니라 중국어도 잘해요 — nuansa pertama adalah "bahasa Inggris? jelas dong, dan bahasa Mandarin juga", yang kedua hanyalah "bukan hanya bahasa Inggris tetapi juga Mandarin". Registernya netral-ke-formal dan sangat umum dalam tulisan dan presentasi. Kesalahan pelajar yang paling umum adalah melekatkannya pada kata kerja (X 가는 물론이고); untuk kata kerja kamu harus menominalkannya dulu (가는 것은 물론이고) atau beralih ke -을 뿐만 아니라. Jangan pula menghilangkan -도 pada item kedua — 물론이고 sangat mengharapkan pasangan "juga" itu.',
      'Có nghĩa là "tất nhiên là X, và còn cả Y nữa": bạn nêu ra một điều hiển nhiên đến mức khỏi cần nói, rồi thêm vào một mục thứ hai (thường bất ngờ hơn) ở trên đó. Nó gắn vào một DANH TỪ: danh từ kết thúc bằng nguyên âm dùng -는 물론이고 (외국어는 물론이고 "tiếng nước ngoài thì tất nhiên rồi, và..."), còn danh từ có 받침 dùng -은 물론이고 (한국말은 물론이고 "tiếng Hàn thì tất nhiên rồi, và..."). Vậy nên 그 가게는 커피는 물론이고 디저트도 유명해요 "tiệm đó nổi tiếng về cà phê thì khỏi phải nói, và còn cả món tráng miệng nữa". Mục được thêm vào rất thường mang -도 ("cũng"), ví dụ 주말은 물론이고 평일에도 바빠요 "tôi bận vào cuối tuần thì khỏi nói, và cả ngày thường cũng bận" → một cách tự nhiên là 주말은 물론이고 평일에도 손님이 많아요. Bạn cũng sẽ nghe thấy dạng ngắn hơn 은/는 물론 với phần 이고 bị lược bỏ.\n\nCấu trúc gần gũi nhất cần lưu ý là -뿐만 아니라 ("không chỉ... mà còn..."). Cả hai đều thêm một mục thứ hai, nhưng 물론이고 đặt mục đầu tiên như một điều hoàn toàn được xem là đương nhiên, trong khi 뿐만 아니라 chỉ nói một cách trung lập "không chỉ A": 그는 영어는 물론이고 중국어도 잘해요 so với 그는 영어뿐만 아니라 중국어도 잘해요 — sắc thái thứ nhất là "tiếng Anh à? hiển nhiên rồi, và cả tiếng Trung nữa", sắc thái thứ hai chỉ đơn thuần là "không chỉ tiếng Anh mà cả tiếng Trung". Ngữ vực ở mức trung tính đến trang trọng và rất phổ biến trong văn viết và thuyết trình. Lỗi thường gặp nhất của người học là gắn nó vào một động từ (X 가는 물론이고); với động từ bạn phải danh từ hóa trước (가는 것은 물론이고) hoặc chuyển sang -을 뿐만 아니라. Cũng đừng lược bỏ -도 ở mục thứ hai — 물론이고 rất mong đợi cái "cũng" đi kèm đó.',
      '「X はもちろん、Y も」という意味で、言うまでもないほど当たり前のことをまず述べ、その上に二つ目の（多くはより意外な）項目を付け加えます。これは「名詞」に付きます。母音で終わる名詞には -는 물론이고 が付き（외국어는 물론이고「外国語はもちろん、…」）、받침のある名詞には -은 물론이고 が付きます（한국말은 물론이고「韓国語はもちろん、…」）。なので 그 가게는 커피는 물론이고 디저트도 유명해요「あの店はコーヒーはもちろん、デザートも有名です」となります。付け加える項目には -도（「も」）が付くことが非常に多く、例えば 주말은 물론이고 평일에도 바빠요「週末はもちろん、平日も忙しいです」→自然には 주말은 물론이고 평일에도 손님이 많아요 となります。また、이고 を省いた短い形の 은/는 물론 も耳にします。\n\n最も近く、注意すべき隣人は -뿐만 아니라（「〜だけでなく…も」）です。どちらも二つ目の項目を加えますが、물론이고 は一つ目を完全に当然のこととして提示するのに対し、뿐만 아니라 は単に中立的に「A だけでなく」と述べます。그는 영어는 물론이고 중국어도 잘해요 と 그는 영어뿐만 아니라 중국어도 잘해요 を比べると、前者のニュアンスは「英語？当然でしょ、しかも中国語も」、後者は単なる「英語だけでなく中国語も」です。語調は中立〜フォーマルで、文章やプレゼンで非常によく使われます。学習者の最もよくある間違いは、これを動詞に付けてしまうこと（X 가는 물론이고）です。動詞の場合はまず名詞化する（가는 것은 물론이고）か、-을 뿐만 아니라 に切り替える必要があります。また、二つ目の項目の -도 を省略しないでください。물론이고 はその対になる「も」を強く要求します。',
    ),
  '-는 바람에': L(
      '-는 바람에 marks a sudden, usually unwanted cause that triggers an unexpected (often negative) result the speaker couldn\'t control: "because of / as a result of." It attaches to a verb stem with no allomorph change — 가다 → 가는 바람에, 먹다 → 먹는 바람에 — so the vowel/ㄹ stem and consonant/받침 stem look identical (ㄹ drops: 만들다 → 만드는 바람에). Crucially the form is fixed at 는 even for past events; you do NOT say 갔는 바람에. Tense is carried by the final clause: 늦잠을 자는 바람에 회의에 늦었어요 "I overslept, so (unexpectedly) I was late for the meeting." It does not attach to nouns directly, surviving only in frozen expressions like 그 바람에 "because of that," and the result clause should not be a command or suggestion.\n\nCompare -아서/어서, the neutral "because." 비가 오는 바람에 소풍이 취소됐어요 frames the rain as a sudden mishap that ruined the picnic, while 비가 와서 소풍이 취소됐어요 is just plain "it rained, so it was cancelled," no surprise or blame. So -는 바람에 carries an "out of my hands, bad luck" nuance that -아서/어서 lacks, and it strongly prefers a negative or at least unintended outcome — 열심히 공부하는 바람에 합격했어요 sounds odd. Register is neutral and works in both 해요 and formal speech. The most common learner mistakes are conjugating for past tense (갔는 바람에 ✗) and forcing a positive result. In casual speech the noun phrase 그 바람에 may be clipped to 그 바람, but the verb form 는 바람에 stays intact.',
      '-는 바람에 marca una causa repentina y normalmente no deseada que desencadena un resultado inesperado (a menudo negativo) que el hablante no pudo controlar: "por culpa de / como resultado de". Se une a una raíz verbal sin cambio de alomorfo — 가다 → 가는 바람에, 먹다 → 먹는 바람에 —, así que la raíz en vocal/ㄹ y la raíz en consonante/받침 se ven idénticas (la ㄹ se cae: 만들다 → 만드는 바람에). Algo clave: la forma queda fija en 는 incluso para eventos pasados; NO decís 갔는 바람에. El tiempo lo lleva la cláusula final: 늦잠을 자는 바람에 회의에 늦었어요 "me quedé dormido, así que (inesperadamente) llegué tarde a la reunión". No se une directamente a sustantivos, y sobrevive solo en expresiones fijas como 그 바람에 "por culpa de eso", y la cláusula de resultado no debería ser una orden ni una sugerencia.\n\nCompará -아서/어서, el "porque" neutro. 비가 오는 바람에 소풍이 취소됐어요 plantea la lluvia como un contratiempo repentino que arruinó el picnic, mientras que 비가 와서 소풍이 취소됐어요 es simplemente "llovió, así que se canceló", sin sorpresa ni reproche. Así que -는 바람에 acarrea un matiz de "no estuvo en mis manos, mala suerte" que -아서/어서 no tiene, y prefiere fuertemente un resultado negativo o al menos no intencionado — 열심히 공부하는 바람에 합격했어요 suena raro. El registro es neutro y funciona tanto en 해요 como en habla formal. Los errores más comunes de los estudiantes son conjugar en pasado (갔는 바람에 ✗) y forzar un resultado positivo. En el habla informal el sintagma nominal 그 바람에 se puede acortar a 그 바람, pero la forma verbal 는 바람에 se mantiene intacta.',
      '-는 바람에 marque une cause soudaine, généralement non souhaitée, qui déclenche un résultat inattendu (souvent négatif) que le locuteur ne pouvait pas contrôler : « à cause de / par suite de ». Il se rattache à un radical verbal sans changement d\'allomorphe — 가다 → 가는 바람에, 먹다 → 먹는 바람에 — si bien que le radical en voyelle/ㄹ et le radical en consonne/받침 se présentent de façon identique (le ㄹ tombe : 만들다 → 만드는 바람에). Point crucial : la forme reste figée à 는 même pour des événements passés ; on ne dit PAS 갔는 바람에. Le temps est porté par la proposition finale : 늦잠을 자는 바람에 회의에 늦었어요 « j\'ai fait la grasse matinée, donc (à l\'improviste) j\'étais en retard à la réunion ». Il ne se rattache pas directement aux noms, ne survivant que dans des expressions figées comme 그 바람에 « à cause de ça », et la proposition de résultat ne devrait pas être un ordre ni une suggestion.\n\nCompare avec -아서/어서, le « parce que » neutre. 비가 오는 바람에 소풍이 취소됐어요 présente la pluie comme une mésaventure soudaine qui a gâché le pique-nique, tandis que 비가 와서 소풍이 취소됐어요 dit juste « il a plu, donc c\'était annulé », sans surprise ni reproche. Ainsi -는 바람에 véhicule une nuance de « ça m\'a échappé, pas de chance » que -아서/어서 n\'a pas, et il préfère nettement un résultat négatif ou du moins non intentionnel — 열심히 공부하는 바람에 합격했어요 sonne bizarre. Le registre est neutre et fonctionne aussi bien en 해요 qu\'en langage formel. Les erreurs les plus fréquentes des apprenants sont de conjuguer au passé (갔는 바람에 ✗) et de forcer un résultat positif. À l\'oral familier, le groupe nominal 그 바람에 peut être tronqué en 그 바람, mais la forme verbale 는 바람에 reste intacte.',
      '-는 바람에 marca uma causa repentina, geralmente indesejada, que desencadeia um resultado inesperado (muitas vezes negativo) que o falante não conseguiu controlar: "por causa de / em consequência de". Liga-se a um radical verbal sem mudança de alomorfe — 가다 → 가는 바람에, 먹다 → 먹는 바람에 — de modo que o radical em vogal/ㄹ e o radical em consoante/받침 ficam idênticos (o ㄹ cai: 만들다 → 만드는 바람에). O ponto crucial é que a forma fica fixa em 는 mesmo para eventos passados; você NÃO diz 갔는 바람에. O tempo é carregado pela oração final: 늦잠을 자는 바람에 회의에 늦었어요 "dormi demais, então (inesperadamente) cheguei atrasado à reunião". Não se liga diretamente a substantivos, sobrevivendo apenas em expressões cristalizadas como 그 바람에 "por causa disso", e a oração de resultado não deve ser uma ordem nem uma sugestão.\n\nCompare com -아서/어서, o "porque" neutro. 비가 오는 바람에 소풍이 취소됐어요 enquadra a chuva como um contratempo repentino que estragou o piquenique, enquanto 비가 와서 소풍이 취소됐어요 é apenas "choveu, então foi cancelado", sem surpresa nem culpa. Então -는 바람에 carrega uma nuance de "fugiu do meu controle, azar" que -아서/어서 não tem, e prefere fortemente um resultado negativo ou pelo menos não intencional — 열심히 공부하는 바람에 합격했어요 soa estranho. O registro é neutro e funciona tanto no 해요 quanto na fala formal. Os erros mais comuns dos alunos são conjugar no passado (갔는 바람에 ✗) e forçar um resultado positivo. Na fala informal, o sintagma nominal 그 바람에 pode ser encurtado para 그 바람, mas a forma verbal 는 바람에 permanece intacta.',
      '-는 바람에 ใช้บอกสาเหตุที่เกิดขึ้นกะทันหันและมักเป็นสิ่งที่ไม่ต้องการ ซึ่งก่อให้เกิดผลลัพธ์ที่ไม่คาดคิด (มักเป็นเชิงลบ) ที่ผู้พูดควบคุมไม่ได้: "เพราะ / อันเป็นผลมาจาก" มันต่อท้ายรากกริยาโดยไม่มีการเปลี่ยนรูปแปร (allomorph) — 가다 → 가는 바람에, 먹다 → 먹는 바람에 — ดังนั้นรากที่ลงท้ายด้วยสระ/ㄹ กับรากที่ลงท้ายด้วยพยัญชนะ/받침 จึงหน้าตาเหมือนกัน (ㄹ จะหลุดออก: 만들다 → 만드는 바람에) จุดสำคัญคือรูปนี้ตรึงอยู่ที่ 는 แม้จะเป็นเหตุการณ์ในอดีตก็ตาม คุณจะ "ไม่" พูดว่า 갔는 바람에 กาลถูกแสดงผ่านอนุประโยคท้าย: 늦잠을 자는 바람에 회의에 늦었어요 "ฉันตื่นสาย เลย (โดยไม่คาดคิด) ไปประชุมสาย" มันไม่ต่อท้ายคำนามโดยตรง คงเหลืออยู่เพียงในสำนวนตายตัวอย่าง 그 바람에 "เพราะสิ่งนั้น" และอนุประโยคผลลัพธ์ไม่ควรเป็นประโยคคำสั่งหรือคำชักชวน\n\nลองเทียบกับ -아서/어서 ซึ่งเป็น "เพราะ" แบบกลางๆ 비가 오는 바람에 소풍이 취소됐어요 วางกรอบว่าฝนเป็นเหตุขัดข้องที่เกิดขึ้นกะทันหันและทำให้การไปปิกนิกพังไป ขณะที่ 비가 와서 소풍이 취소됐어요 เป็นเพียง "ฝนตก เลยถูกยกเลิก" โดยไม่มีความประหลาดใจหรือการตำหนิ ดังนั้น -는 바람에 จึงมีนัยของ "มันเกินการควบคุมของฉัน โชคร้าย" ที่ -아서/어서 ไม่มี และมันมีแนวโน้มอย่างชัดเจนที่จะใช้กับผลลัพธ์เชิงลบหรืออย่างน้อยก็เป็นสิ่งที่ไม่ตั้งใจ — 열심히 공부하는 바람에 합격했어요 ฟังดูแปลก ระดับภาษาเป็นกลางและใช้ได้ทั้งใน 해요 และการพูดแบบทางการ ข้อผิดพลาดที่ผู้เรียนทำบ่อยที่สุดคือการผันเป็นกาลอดีต (갔는 바람에 ✗) และการฝืนใช้กับผลลัพธ์เชิงบวก ในการพูดแบบลำลอง วลีนาม 그 바람에 อาจถูกตัดให้สั้นลงเป็น 그 바람 แต่รูปกริยา 는 바람에 ยังคงอยู่ครบถ้วน',
      '-는 바람에 menandai sebab yang mendadak, biasanya tidak diinginkan, yang memicu hasil tak terduga (sering kali negatif) yang tidak bisa dikendalikan penutur: "karena / sebagai akibat dari". Ia menempel pada akar kata kerja tanpa perubahan alomorf — 가다 → 가는 바람에, 먹다 → 먹는 바람에 — sehingga akar berhuruf vokal/ㄹ dan akar berhuruf konsonan/받침 terlihat identik (ㄹ luruh: 만들다 → 만드는 바람에). Yang krusial, bentuknya tetap pada 는 bahkan untuk peristiwa lampau; kamu TIDAK mengatakan 갔는 바람에. Kala dibawa oleh klausa akhir: 늦잠을 자는 바람에 회의에 늦었어요 "saya kesiangan, jadi (tak terduga) saya terlambat ke rapat". Ia tidak menempel langsung pada kata benda, hanya bertahan dalam ungkapan beku seperti 그 바람에 "karena itu", dan klausa hasil sebaiknya bukan perintah maupun ajakan.\n\nBandingkan dengan -아서/어서, "karena" yang netral. 비가 오는 바람에 소풍이 취소됐어요 membingkai hujan sebagai musibah mendadak yang merusak piknik, sedangkan 비가 와서 소풍이 취소됐어요 hanya berarti "hujan turun, jadi dibatalkan", tanpa kejutan atau penyalahan. Jadi -는 바람에 membawa nuansa "di luar kendali saya, nasib buruk" yang tidak dimiliki -아서/어서, dan ia sangat cenderung pada hasil negatif atau setidaknya tidak disengaja — 열심히 공부하는 바람에 합격했어요 terdengar janggal. Ragamnya netral dan berfungsi baik dalam 해요 maupun tutur formal. Kesalahan pembelajar yang paling umum adalah mengonjugasikan ke kala lampau (갔는 바람에 ✗) dan memaksakan hasil yang positif. Dalam tutur santai, frasa nomina 그 바람에 bisa dipangkas menjadi 그 바람, tetapi bentuk kata kerja 는 바람에 tetap utuh.',
      '-는 바람에 đánh dấu một nguyên nhân đột ngột, thường là ngoài ý muốn, làm phát sinh một kết quả không lường trước (thường tiêu cực) mà người nói không thể kiểm soát: "vì / do hậu quả của". Nó gắn vào gốc động từ mà không thay đổi tha hình vị (allomorph) — 가다 → 가는 바람에, 먹다 → 먹는 바람에 — nên gốc kết thúc bằng nguyên âm/ㄹ và gốc kết thúc bằng phụ âm/받침 trông giống hệt nhau (ㄹ rụng đi: 만들다 → 만드는 바람에). Điều then chốt là dạng này cố định ở 는 ngay cả với sự việc trong quá khứ; bạn KHÔNG nói 갔는 바람에. Thì được mang bởi mệnh đề cuối: 늦잠을 자는 바람에 회의에 늦었어요 "tôi ngủ quên, nên (bất ngờ) tôi đến họp muộn". Nó không gắn trực tiếp vào danh từ, chỉ tồn tại trong các thành ngữ cố định như 그 바람에 "vì thế", và mệnh đề kết quả không nên là câu mệnh lệnh hay đề nghị.\n\nHãy so sánh với -아서/어서, từ "vì" trung tính. 비가 오는 바람에 소풍이 취소됐어요 đóng khung cơn mưa như một sự cố đột ngột làm hỏng buổi dã ngoại, trong khi 비가 와서 소풍이 취소됐어요 chỉ đơn thuần là "trời mưa, nên bị hủy", không có sự ngạc nhiên hay đổ lỗi. Vậy nên -는 바람에 mang sắc thái "ngoài tầm tay tôi, xui xẻo" mà -아서/어서 không có, và nó thiên mạnh về một kết quả tiêu cực hoặc ít nhất là ngoài ý muốn — 열심히 공부하는 바람에 합격했어요 nghe có vẻ kỳ. Ngữ vực trung tính và dùng được cả trong 해요 lẫn lối nói trang trọng. Lỗi phổ biến nhất của người học là chia ở thì quá khứ (갔는 바람에 ✗) và gượng ép một kết quả tích cực. Trong lời nói thân mật, cụm danh từ 그 바람에 có thể được rút gọn thành 그 바람, nhưng dạng động từ 는 바람에 vẫn giữ nguyên.',
      '-는 바람에 は、話し手が制御できなかった予期せぬ(多くは否定的な)結果を引き起こす、突発的で通常は望まない原因を表します。「~のせいで/~の結果として」。動詞の語幹に異形態(allomorph)の変化なしに付きます — 가다 → 가는 바람에、먹다 → 먹는 바람에 — そのため母音/ㄹ語幹と子音/받침語幹は同じ形に見えます(ㄹは脱落:만들다 → 만드는 바람에)。重要なのは、過去の出来事であっても形は 는 に固定されることです。갔는 바람에 とは言いません。時制は後続の節が担います:늦잠을 자는 바람에 회의에 늦었어요「寝坊したので、(思いがけず)会議に遅刻しました」。名詞に直接は付かず、그 바람에「そのせいで」のような固定表現にのみ残り、結果の節は命令や勧誘であってはいけません。\n\n中立的な「~なので」である -아서/어서 と比べてみましょう。비가 오는 바람에 소풍이 취소됐어요 は、雨を遠足を台無しにした突発的な災難として枠づけしますが、비가 와서 소풍이 취소됐어요 は単に「雨が降ったので中止になった」で、驚きも非難もありません。つまり -는 바람에 には -아서/어서 にはない「自分にはどうしようもない、運が悪い」というニュアンスがあり、否定的な、あるいは少なくとも意図しない結果を強く好みます — 열심히 공부하는 바람에 합격했어요 は不自然に聞こえます。語調は中立的で、해요 でも改まった話し方でも使えます。学習者が最もよくする間違いは、過去時制に活用すること(갔는 바람에 ✗)と、肯定的な結果を無理に当てはめることです。くだけた話し言葉では名詞句 그 바람에 は 그 바람 と切り詰められることがありますが、動詞の形 는 바람에 はそのまま保たれます。',
    ),
  '-는 통에': L(
      'Marks a prolonged disorderly, chaotic situation that causes a negative, unintended result — "in the chaos/din of...", "because of all the commotion of...". It attaches to a verb stem and is almost always used with the present form -는 통에, regardless of when the event happened (먹다 → 먹는 통에, 울다 → 우는 통에, with ㄹ dropping: 떠들다 → 떠드는 통에 "amid all the racket"). It does not take past or future endings on the 통에 clause itself; tense is carried by the final verb: 아이가 우는 통에 한숨도 못 잤어요 ("the baby was bawling, so I couldn\'t sleep a wink"). The second clause must be something bad or undesirable — never a positive or planned outcome.\n\nThe closest neighbor to watch is -는 바람에. Both attach to a verb and explain an unwanted result, but -는 바람에 points at a single triggering event ("because of / as a result of"), while -는 통에 stresses a noisy, prolonged, chaotic mess. Compare 갑자기 비가 오는 바람에 옷이 다 젖었어요 ("it suddenly rained, so my clothes got soaked" — one cause) with 다들 떠드는 통에 발표를 망쳤어요 ("with everyone making a din, I botched the presentation" — ongoing turmoil). Register is neutral-to-spoken and colloquial; you\'ll hear it in conversation more than in formal writing. The most common learner mistake is using -는 통에 with a good result (X 합격하는 통에 기뻤어요) — it only ever introduces something negative — and pairing it with a command or suggestion, which it cannot do.',
      'Marca una situación prolongada, desordenada y caótica que provoca un resultado negativo no buscado: "en medio del caos/alboroto de...", "por culpa de todo el lío de...". Se une a la raíz de un verbo y casi siempre se usa con la forma de presente -는 통에, sin importar cuándo ocurrió el evento (먹다 → 먹는 통에, 울다 → 우는 통에, con caída de la ㄹ: 떠들다 → 떠드는 통에 "en medio de todo el escándalo"). No admite terminaciones de pasado ni futuro en la propia cláusula de 통에; el tiempo lo lleva el verbo final: 아이가 우는 통에 한숨도 못 잤어요 ("el bebé estaba llorando a gritos, así que no pegué ojo"). La segunda cláusula tiene que ser algo malo o indeseable, nunca un resultado positivo o planeado.\n\nEl vecino más cercano que tenés que vigilar es -는 바람에. Los dos se unen a un verbo y explican un resultado no deseado, pero -는 바람에 apunta a un único evento desencadenante ("por culpa de / como resultado de"), mientras que -는 통에 enfatiza un desastre ruidoso, prolongado y caótico. Compará 갑자기 비가 오는 바람에 옷이 다 젖었어요 ("de repente empezó a llover, así que se me empapó toda la ropa" — una sola causa) con 다들 떠드는 통에 발표를 망쳤어요 ("con todos haciendo bullicio, eché a perder la presentación" — un caos continuo). El registro es neutro-a-coloquial y propio del habla; lo vas a oír más en conversación que en la escritura formal. El error más común de quien aprende es usar -는 통에 con un resultado bueno (X 합격하는 통에 기뻤어요) — solo introduce algo negativo — y combinarlo con una orden o sugerencia, algo que no puede hacer.',
      'Marque une situation prolongée, désordonnée et chaotique qui provoque un résultat négatif et non voulu — "dans le chaos/le vacarme de...", "à cause de toute l\'agitation de...". Elle s\'attache au radical d\'un verbe et s\'emploie presque toujours à la forme du présent -는 통에, peu importe le moment où l\'événement s\'est produit (먹다 → 먹는 통에, 울다 → 우는 통에, avec chute du ㄹ : 떠들다 → 떠드는 통에 "au milieu de tout ce raffut"). Elle ne prend ni terminaison du passé ni du futur sur la proposition en 통에 elle-même ; le temps est porté par le verbe final : 아이가 우는 통에 한숨도 못 잤어요 ("le bébé hurlait, donc je n\'ai pas fermé l\'œil"). La seconde proposition doit être quelque chose de mauvais ou d\'indésirable — jamais un résultat positif ou prévu.\n\nLe voisin le plus proche à surveiller est -는 바람에. Les deux s\'attachent à un verbe et expliquent un résultat non voulu, mais -는 바람에 désigne un seul événement déclencheur ("à cause de / par suite de"), tandis que -는 통에 insiste sur un désordre bruyant, prolongé et chaotique. Compare 갑자기 비가 오는 바람에 옷이 다 젖었어요 ("il s\'est mis à pleuvoir d\'un coup, donc mes vêtements ont été trempés" — une seule cause) avec 다들 떠드는 통에 발표를 망쳤어요 ("avec tout le monde qui faisait du tapage, j\'ai raté ma présentation" — un tumulte continu). Le registre est neutre à oral et familier ; tu l\'entendras davantage à la conversation qu\'à l\'écrit formel. L\'erreur la plus fréquente des apprenants est d\'employer -는 통에 avec un bon résultat (X 합격하는 통에 기뻤어요) — il n\'introduit jamais que quelque chose de négatif — et de l\'associer à un ordre ou à une suggestion, ce qu\'il ne peut pas faire.',
      'Marca uma situação prolongada, desordenada e caótica que causa um resultado negativo e não intencional — "no meio do caos/da barulheira de...", "por causa de toda a confusão de...". Liga-se ao radical de um verbo e quase sempre é usada na forma de presente -는 통에, independentemente de quando o evento aconteceu (먹다 → 먹는 통에, 울다 → 우는 통에, com queda do ㄹ: 떠들다 → 떠드는 통에 "no meio de toda a algazarra"). Não recebe terminações de passado nem de futuro na própria oração de 통에; o tempo é carregado pelo verbo final: 아이가 우는 통에 한숨도 못 잤어요 ("o bebê estava chorando muito, então não preguei o olho"). A segunda oração tem que ser algo ruim ou indesejável — nunca um resultado positivo ou planejado.\n\nO vizinho mais próximo a ficar de olho é -는 바람에. Os dois se ligam a um verbo e explicam um resultado indesejado, mas -는 바람에 aponta para um único evento desencadeador ("por causa de / como resultado de"), enquanto -는 통에 enfatiza uma bagunça barulhenta, prolongada e caótica. Compare 갑자기 비가 오는 바람에 옷이 다 젖었어요 ("de repente começou a chover, então minha roupa ficou toda encharcada" — uma única causa) com 다들 떠드는 통에 발표를 망쳤어요 ("com todo mundo fazendo barulho, eu estraguei a apresentação" — um tumulto contínuo). O registro é neutro-a-falado e coloquial; você vai ouvir isso mais na conversa do que na escrita formal. O erro mais comum de quem aprende é usar -는 통에 com um resultado bom (X 합격하는 통에 기뻤어요) — ela só introduz algo negativo — e combiná-la com uma ordem ou sugestão, o que ela não pode fazer.',
      'ใช้บ่งบอกสถานการณ์ที่วุ่นวาย โกลาหล และยืดเยื้อ ซึ่งทำให้เกิดผลลัพธ์ในแง่ลบที่ไม่ได้ตั้งใจ — "ท่ามกลางความโกลาหล/เสียงอึกทึกของ...", "เพราะความวุ่นวายทั้งหมดของ...". มันเติมเข้ากับรากศัพท์ของคำกริยา และเกือบทุกครั้งจะใช้ในรูปปัจจุบัน -는 통에 ไม่ว่าเหตุการณ์จะเกิดขึ้นเมื่อใดก็ตาม (먹다 → 먹는 통에, 울다 → 우는 통에 และเมื่อ ㄹ หลุดหายไป: 떠들다 → 떠드는 통에 "ท่ามกลางเสียงเอะอะทั้งหมด") ตัวอนุประโยค 통에 เองจะไม่รับการผันรูปอดีตหรืออนาคต กาลจะถูกแบกไว้ที่คำกริยาตัวสุดท้าย: 아이가 우는 통에 한숨도 못 잤어요 ("เด็กร้องไห้งอแง เลยนอนไม่ได้แม้แต่นิดเดียว") อนุประโยคที่สองต้องเป็นเรื่องไม่ดีหรือไม่พึงประสงค์ — ไม่มีทางเป็นผลลัพธ์เชิงบวกหรือสิ่งที่วางแผนไว้\n\nตัวที่ใกล้เคียงที่สุดที่ต้องระวังคือ -는 바람에 ทั้งสองตัวเติมเข้ากับคำกริยาและอธิบายผลลัพธ์ที่ไม่พึงประสงค์ แต่ -는 바람에 ชี้ไปที่เหตุการณ์กระตุ้นเพียงเหตุการณ์เดียว ("เพราะ / อันเป็นผลจาก") ในขณะที่ -는 통에 เน้นความยุ่งเหยิงที่อึกทึก ยืดเยื้อ และโกลาหล ลองเทียบ 갑자기 비가 오는 바람에 옷이 다 젖었어요 ("จู่ๆ ฝนก็ตก เลยทำให้เสื้อผ้าเปียกโชกไปหมด" — สาเหตุเดียว) กับ 다들 떠드는 통에 발표를 망쳤어요 ("เพราะทุกคนส่งเสียงเอะอะ ฉันเลยทำการนำเสนอพังหมด" — ความวุ่นวายที่ดำเนินต่อเนื่อง) ระดับภาษาเป็นกลางถึงระดับพูดและไม่เป็นทางการ คุณจะได้ยินมันในบทสนทนามากกว่าในงานเขียนที่เป็นทางการ ข้อผิดพลาดที่ผู้เรียนพบบ่อยที่สุดคือการใช้ -는 통에 กับผลลัพธ์ที่ดี (X 합격하는 통에 기뻤어요) — มันใช้เพื่อนำเสนอแต่สิ่งที่เป็นแง่ลบเท่านั้น — และการนำไปจับคู่กับประโยคคำสั่งหรือคำชักชวน ซึ่งมันทำไม่ได้',
      'Menandai situasi yang berlarut-larut, kacau-balau, dan ribut yang menyebabkan akibat negatif yang tidak diinginkan — "di tengah kekacauan/keributan...", "karena segala keributan dari...". Ia melekat pada akar kata kerja dan hampir selalu dipakai dengan bentuk kini -는 통에, tidak peduli kapan peristiwanya terjadi (먹다 → 먹는 통에, 울다 → 우는 통에, dengan ㄹ luruh: 떠들다 → 떠드는 통에 "di tengah segala kegaduhan"). Ia tidak menerima akhiran lampau atau akan datang pada klausa 통에 itu sendiri; kala dibawa oleh kata kerja terakhir: 아이가 우는 통에 한숨도 못 잤어요 ("bayinya menangis kencang, jadi saya tidak bisa tidur sama sekali"). Klausa kedua harus berupa sesuatu yang buruk atau tidak diinginkan — tidak pernah berupa hasil yang positif atau terencana.\n\nTetangga terdekat yang perlu diperhatikan adalah -는 바람에. Keduanya melekat pada kata kerja dan menjelaskan hasil yang tidak diinginkan, tetapi -는 바람에 menunjuk pada satu peristiwa pemicu tunggal ("karena / sebagai akibat dari"), sedangkan -는 통에 menekankan kekacauan yang ribut, berlarut-larut, dan tidak teratur. Bandingkan 갑자기 비가 오는 바람에 옷이 다 젖었어요 ("tiba-tiba hujan, jadi baju saya basah kuyup semua" — satu penyebab) dengan 다들 떠드는 통에 발표를 망쳤어요 ("karena semua orang ribut, saya mengacaukan presentasi" — kekacauan yang berlangsung terus). Ragamnya netral-ke-lisan dan informal; kamu akan lebih sering mendengarnya dalam percakapan daripada dalam tulisan resmi. Kesalahan pembelajar yang paling umum adalah memakai -는 통에 dengan hasil yang baik (X 합격하는 통에 기뻤어요) — ia hanya pernah memperkenalkan sesuatu yang negatif — dan memasangkannya dengan perintah atau ajakan, yang tidak bisa ia lakukan.',
      'Đánh dấu một tình huống lộn xộn, hỗn loạn kéo dài gây ra một kết quả tiêu cực, ngoài ý muốn — "giữa cảnh hỗn loạn/ồn ào của...", "vì tất cả sự náo loạn của...". Nó gắn vào gốc động từ và hầu như luôn được dùng ở dạng hiện tại -는 통에, bất kể sự việc xảy ra khi nào (먹다 → 먹는 통에, 울다 → 우는 통에, với ㄹ bị lược bỏ: 떠들다 → 떠드는 통에 "giữa tất cả sự ồn ào náo nhiệt"). Nó không nhận đuôi quá khứ hay tương lai ngay trên mệnh đề 통에; thì được mang bởi động từ cuối câu: 아이가 우는 통에 한숨도 못 잤어요 ("đứa bé khóc ré lên, nên tôi chẳng chợp mắt được chút nào"). Mệnh đề thứ hai phải là điều gì đó xấu hoặc không mong muốn — không bao giờ là một kết quả tích cực hay có chủ đích.\n\nNgười hàng xóm gần nhất cần lưu ý là -는 바람에. Cả hai đều gắn vào động từ và giải thích một kết quả không mong muốn, nhưng -는 바람에 hướng đến một sự kiện khởi phát đơn lẻ ("vì / do kết quả của"), trong khi -는 통에 nhấn mạnh một mớ hỗn độn ồn ào, kéo dài và lộn xộn. Hãy so sánh 갑자기 비가 오는 바람에 옷이 다 젖었어요 ("trời bất ngờ đổ mưa, nên quần áo tôi ướt sũng hết" — một nguyên nhân) với 다들 떠드는 통에 발표를 망쳤어요 ("mọi người nhao nhao ồn ào, nên tôi làm hỏng bài thuyết trình" — sự náo loạn diễn ra liên tục). Văn phong trung tính đến khẩu ngữ và thân mật; bạn sẽ nghe nó trong hội thoại nhiều hơn là trong văn viết trang trọng. Lỗi phổ biến nhất của người học là dùng -는 통에 với một kết quả tốt (X 합격하는 통에 기뻤어요) — nó chỉ luôn dẫn ra điều gì đó tiêu cực — và ghép nó với một câu mệnh lệnh hay đề nghị, điều mà nó không thể làm.',
      '長く続く乱雑で混沌とした状況が、否定的で意図しない結果を引き起こすことを表します——「…の混乱/騒ぎの中で」「…のごたごたのせいで」。動詞の語幹に付き、出来事がいつ起きたかにかかわらず、ほぼ常に現在形の -는 통에 で使われます（먹다 → 먹는 통에、울다 → 우는 통에、ㄹが脱落して 떠들다 → 떠드는 통에「大騒ぎの中で」）。통에 の節そのものには過去や未来の語尾を取らず、時制は文末の動詞が担います：아이가 우는 통에 한숨도 못 잤어요（「赤ちゃんが泣きわめいて、一睡もできませんでした」）。後ろの節は必ず悪いことや望ましくないことでなければならず、肯定的だったり計画通りの結果になることは決してありません。\n\n注意すべき最も近い隣人は -는 바람에 です。どちらも動詞に付いて望ましくない結果を説明しますが、-는 바람에 は単一の引き金となる出来事を指す（「…のせいで／…の結果」）のに対し、-는 통에 は騒がしく長引く混沌としたごたごたを強調します。갑자기 비가 오는 바람에 옷이 다 젖었어요（「急に雨が降って、服が全部びしょ濡れになった」——原因は一つ）と、다들 떠드는 통에 발표를 망쳤어요（「みんながわいわい騒いで、発表を台無しにした」——続いている混乱）を比べてみてください。語調は中立的から口語的・くだけた感じで、改まった書き言葉よりも会話でよく耳にします。学習者の最も多い間違いは、-는 통에 を良い結果と一緒に使うこと（X 합격하는 통에 기뻤어요）——これは否定的なことしか導きません——と、命令や提案と組み合わせることで、これはできません。',
    ),
  '-(으)ㄹ 텐데': L(
      '-(으)ㄹ 텐데 expresses a firm, reasoned conjecture ("I suppose / it must be that...") usually followed by a contrasting or worried second clause, so it often lands as "...must be ..., but ...". It builds on -(으)ㄹ 터 ("expectation/intention") plus -ㄴ데. Attach it to a verb or adjective stem: a vowel/ㄹ stem takes -ㄹ 텐데 (오다 → 올 텐데, 살다 → 살 텐데, with ㄹ kept), and a consonant (받침) stem takes -을 텐데 (먹다 → 먹을 텐데, 좋다 → 좋을 텐데). For past situations use -았/었을 텐데 (벌써 도착했을 텐데 "they must have arrived already, but..."), and after a noun use N+일 텐데 (학생일 텐데). 비가 올 텐데 우산 가져가세요 = "It\'s bound to rain, so take an umbrella."\n\nThe closest neighbour to watch is plain -(으)ㄹ 거예요 (simple prediction). Compare 바쁠 거예요 "they\'ll probably be busy" — a flat forecast — with 바쁠 텐데 도와줄 수 있을까? "they must be busy, but could you help?", where 텐데 adds the speaker\'s reasoning and sets up a contrast or concern. 텐데 cannot stand alone as a neutral statement; it leans toward an unspoken "but/so". Register: neutral and common in speech and writing; politeness comes from the following clause\'s ending, not from 텐데 itself. The most common learner mistake is dropping the 받침 rule and writing 먹을 텐데 as 먹텐데, or misreading the 터 + ㄴ데 origin and spelling it 텐테/텐대. In casual speech you\'ll also hear sentences trail off on 텐데... to leave the worry implied.',
      '-(으)ㄹ 텐데 expresa una conjetura firme y razonada ("supongo que / seguro que..."), normalmente seguida de una segunda oración que contrasta o muestra preocupación, así que suele caer como "...seguramente..., pero...". Se construye sobre -(으)ㄹ 터 ("expectativa/intención") más -ㄴ데. Pegalo a la raíz de un verbo o adjetivo: una raíz que termina en vocal o en ㄹ toma -ㄹ 텐데 (오다 → 올 텐데, 살다 → 살 텐데, conservando la ㄹ), y una raíz con consonante final (받침) toma -을 텐데 (먹다 → 먹을 텐데, 좋다 → 좋을 텐데). Para situaciones pasadas usá -았/었을 텐데 (벌써 도착했을 텐데 "seguro que ya llegaron, pero..."), y después de un sustantivo usá N+일 텐데 (학생일 텐데). 비가 올 텐데 우산 가져가세요 = "Seguro que va a llover, así que llevate un paraguas."\n\nEl vecino más cercano que tenés que vigilar es el simple -(으)ㄹ 거예요 (predicción sencilla). Compará 바쁠 거예요 "probablemente estén ocupados" —un pronóstico plano— con 바쁠 텐데 도와줄 수 있을까? "seguro que están ocupados, pero ¿podrías ayudar?", donde 텐데 añade el razonamiento del hablante y prepara un contraste o una inquietud. 텐데 no puede ir solo como una afirmación neutra; se inclina hacia un "pero/así que" no dicho. Registro: neutro y común tanto al hablar como al escribir; la cortesía viene de la terminación de la oración siguiente, no de 텐데 en sí. El error más común de los estudiantes es saltarse la regla del 받침 y escribir 먹을 텐데 como 먹텐데, o malinterpretar el origen 터 + ㄴ데 y escribirlo 텐테/텐대. En el habla casual también vas a oír frases que se cortan en 텐데... para dejar la preocupación sobreentendida.',
      '-(으)ㄹ 텐데 exprime une supposition ferme et raisonnée (« je suppose que / ce doit être que... »), généralement suivie d\'une seconde proposition qui contraste ou qui exprime une inquiétude, si bien qu\'elle revient souvent à « ...ce doit être..., mais... ». Elle se construit sur -(으)ㄹ 터 (« attente/intention ») plus -ㄴ데. Attache-la au radical d\'un verbe ou d\'un adjectif : un radical en voyelle ou en ㄹ prend -ㄹ 텐데 (오다 → 올 텐데, 살다 → 살 텐데, en gardant le ㄹ), et un radical à consonne finale (받침) prend -을 텐데 (먹다 → 먹을 텐데, 좋다 → 좋을 텐데). Pour des situations passées, utilise -았/었을 텐데 (벌써 도착했을 텐데 « ils doivent déjà être arrivés, mais... »), et après un nom, utilise N+일 텐데 (학생일 텐데). 비가 올 텐데 우산 가져가세요 = « Il va sûrement pleuvoir, alors prends un parapluie. »\n\nLe voisin le plus proche à surveiller est le simple -(으)ㄹ 거예요 (prédiction toute simple). Compare 바쁠 거예요 « ils seront probablement occupés » —une prévision neutre— avec 바쁠 텐데 도와줄 수 있을까? « ils doivent être occupés, mais pourrais-tu aider ? », où 텐데 ajoute le raisonnement du locuteur et installe un contraste ou une inquiétude. 텐데 ne peut pas se tenir seul comme une affirmation neutre ; il penche vers un « mais/alors » non dit. Registre : neutre et courant à l\'oral comme à l\'écrit ; la politesse vient de la terminaison de la proposition suivante, pas de 텐데 lui-même. L\'erreur la plus fréquente des apprenants est d\'oublier la règle du 받침 et d\'écrire 먹을 텐데 sous la forme 먹텐데, ou de mal lire l\'origine 터 + ㄴ데 et de l\'orthographier 텐테/텐대. À l\'oral familier, tu entendras aussi des phrases qui s\'éteignent sur 텐데... pour laisser l\'inquiétude sous-entendue.',
      '-(으)ㄹ 텐데 expressa uma conjectura firme e fundamentada ("suponho que / deve ser que..."), geralmente seguida de uma segunda oração que contrasta ou demonstra preocupação, então costuma soar como "...deve ser..., mas...". Ela se constrói sobre -(으)ㄹ 터 ("expectativa/intenção") mais -ㄴ데. Anexe-a ao radical de um verbo ou adjetivo: um radical terminado em vogal ou em ㄹ recebe -ㄹ 텐데 (오다 → 올 텐데, 살다 → 살 텐데, mantendo o ㄹ), e um radical com consoante final (받침) recebe -을 텐데 (먹다 → 먹을 텐데, 좋다 → 좋을 텐데). Para situações passadas, use -았/었을 텐데 (벌써 도착했을 텐데 "eles já devem ter chegado, mas..."), e depois de um substantivo use N+일 텐데 (학생일 텐데). 비가 올 텐데 우산 가져가세요 = "Com certeza vai chover, então leve um guarda-chuva."\n\nO vizinho mais próximo a ficar de olho é o simples -(으)ㄹ 거예요 (previsão simples). Compare 바쁠 거예요 "eles provavelmente estarão ocupados" —uma previsão neutra— com 바쁠 텐데 도와줄 수 있을까? "eles devem estar ocupados, mas você poderia ajudar?", onde 텐데 acrescenta o raciocínio do falante e prepara um contraste ou uma preocupação. 텐데 não pode ficar sozinho como uma afirmação neutra; ele tende a um "mas/então" não dito. Registro: neutro e comum tanto na fala quanto na escrita; a cortesia vem da terminação da oração seguinte, não do próprio 텐데. O erro mais comum dos estudantes é ignorar a regra do 받침 e escrever 먹을 텐데 como 먹텐데, ou interpretar mal a origem 터 + ㄴ데 e grafá-lo como 텐테/텐대. Na fala casual, você também vai ouvir frases que se interrompem em 텐데... para deixar a preocupação subentendida.',
      '-(으)ㄹ 텐데 ใช้แสดงการคาดเดาที่หนักแน่นและมีเหตุผล ("ฉันคิดว่า / มันคงจะ...") โดยปกติจะตามด้วยประโยคที่สองที่ขัดแย้งหรือแสดงความกังวล จึงมักออกมาในรูป "...คงจะ... แต่...". มันสร้างขึ้นจาก -(으)ㄹ 터 ("ความคาดหวัง/ความตั้งใจ") บวกกับ -ㄴ데 เติมเข้ากับรากของกริยาหรือคำคุณศัพท์: รากที่ลงท้ายด้วยสระหรือ ㄹ ใช้ -ㄹ 텐데 (오다 → 올 텐데, 살다 → 살 텐데 โดยคง ㄹ ไว้) และรากที่มีตัวสะกด (받침) ใช้ -을 텐데 (먹다 → 먹을 텐데, 좋다 → 좋을 텐데) สำหรับสถานการณ์ในอดีตให้ใช้ -았/었을 텐데 (벌써 도착했을 텐데 "พวกเขาคงมาถึงแล้ว แต่...") และหลังคำนามให้ใช้ N+일 텐데 (학생일 텐데) 비가 올 텐데 우산 가져가세요 = "ฝนคงจะตกแน่ ๆ เพราะฉะนั้นเอาร่มไปด้วยนะ"\n\nเพื่อนบ้านที่ใกล้เคียงที่สุดที่ต้องระวังคือ -(으)ㄹ 거예요 แบบธรรมดา (การทำนายธรรมดา) ลองเปรียบเทียบ 바쁠 거예요 "พวกเขาคงจะยุ่ง" —คำพยากรณ์เรียบ ๆ— กับ 바쁠 텐데 도와줄 수 있을까? "พวกเขาคงจะยุ่ง แต่ช่วยหน่อยได้ไหม?" ซึ่ง 텐데 เพิ่มการให้เหตุผลของผู้พูดและปูทางไปสู่การขัดแย้งหรือความกังวล 텐데 ไม่สามารถยืนอยู่ลำพังในฐานะประโยคบอกเล่าที่เป็นกลางได้ มันโน้มเอียงไปทาง "แต่/เพราะฉะนั้น" ที่ไม่ได้พูดออกมา ระดับภาษา: เป็นกลางและพบได้ทั่วไปทั้งในการพูดและการเขียน ความสุภาพมาจากการลงท้ายของประโยคที่ตามมา ไม่ได้มาจาก 텐데 เอง ข้อผิดพลาดที่ผู้เรียนพบบ่อยที่สุดคือการละเลยกฎ 받침 แล้วเขียน 먹을 텐데 เป็น 먹텐데 หรืออ่านที่มา 터 + ㄴ데 ผิดแล้วสะกดเป็น 텐테/텐대 ในการพูดแบบลำลองคุณจะได้ยินประโยคที่ค่อย ๆ จางหายลงที่ 텐데... เพื่อทิ้งความกังวลไว้ให้เข้าใจกันเอง',
      '-(으)ㄹ 텐데 mengungkapkan dugaan yang tegas dan beralasan ("saya kira / pasti..."), biasanya diikuti klausa kedua yang berlawanan atau berisi kekhawatiran, sehingga sering terdengar seperti "...pasti..., tetapi...". Bentuk ini dibangun dari -(으)ㄹ 터 ("harapan/niat") ditambah -ㄴ데. Tempelkan pada kata kerja atau kata sifat: akar yang berakhiran vokal atau ㄹ memakai -ㄹ 텐데 (오다 → 올 텐데, 살다 → 살 텐데, dengan ㄹ tetap dipertahankan), dan akar berkonsonan akhir (받침) memakai -을 텐데 (먹다 → 먹을 텐데, 좋다 → 좋을 텐데). Untuk situasi masa lampau gunakan -았/었을 텐데 (벌써 도착했을 텐데 "mereka pasti sudah tiba, tetapi..."), dan setelah kata benda gunakan N+일 텐데 (학생일 텐데). 비가 올 텐데 우산 가져가세요 = "Pasti akan turun hujan, jadi bawalah payung."\n\nTetangga terdekat yang perlu diwaspadai adalah -(으)ㄹ 거예요 biasa (prediksi sederhana). Bandingkan 바쁠 거예요 "mereka mungkin akan sibuk" —ramalan yang datar— dengan 바쁠 텐데 도와줄 수 있을까? "mereka pasti sibuk, tetapi bisakah kamu membantu?", di mana 텐데 menambahkan penalaran si pembicara dan menyiapkan kontras atau kekhawatiran. 텐데 tidak bisa berdiri sendiri sebagai pernyataan netral; ia condong ke arah "tetapi/jadi" yang tidak terucap. Ragam: netral dan umum baik dalam percakapan maupun tulisan; kesopanan berasal dari akhiran klausa berikutnya, bukan dari 텐데 itu sendiri. Kesalahan pembelajar yang paling umum adalah mengabaikan aturan 받침 dan menulis 먹을 텐데 sebagai 먹텐데, atau salah memahami asal-usul 터 + ㄴ데 lalu mengejanya menjadi 텐테/텐대. Dalam percakapan santai, kamu juga akan mendengar kalimat yang dibiarkan menggantung pada 텐데... untuk menyiratkan kekhawatiran tanpa diucapkan.',
      '-(으)ㄹ 텐데 diễn đạt một phỏng đoán chắc chắn, có lập luận ("tôi cho rằng / chắc hẳn là..."), thường được theo sau bởi một mệnh đề thứ hai mang tính tương phản hoặc lo lắng, nên nó thường mang nghĩa "...chắc hẳn..., nhưng...". Nó được dựng trên -(으)ㄹ 터 ("kỳ vọng/ý định") cộng với -ㄴ데. Gắn nó vào gốc động từ hoặc tính từ: gốc kết thúc bằng nguyên âm hoặc ㄹ dùng -ㄹ 텐데 (오다 → 올 텐데, 살다 → 살 텐데, vẫn giữ ㄹ), còn gốc có phụ âm cuối (받침) dùng -을 텐데 (먹다 → 먹을 텐데, 좋다 → 좋을 텐데). Với tình huống quá khứ hãy dùng -았/었을 텐데 (벌써 도착했을 텐데 "họ chắc đã đến rồi, nhưng..."), và sau danh từ hãy dùng N+일 텐데 (학생일 텐데). 비가 올 텐데 우산 가져가세요 = "Trời chắc chắn sẽ mưa, nên hãy mang theo ô."\n\nNgười hàng xóm gần nhất cần để ý là -(으)ㄹ 거예요 thông thường (dự đoán đơn giản). Hãy so sánh 바쁠 거예요 "họ có lẽ sẽ bận" —một dự báo phẳng lặng— với 바쁠 텐데 도와줄 수 있을까? "họ chắc đang bận, nhưng bạn có thể giúp không?", nơi 텐데 thêm vào lập luận của người nói và mở đường cho sự tương phản hoặc nỗi lo. 텐데 không thể đứng một mình như một câu trần thuật trung tính; nó nghiêng về một "nhưng/nên" chưa nói ra. Ngữ vực: trung tính và phổ biến cả trong nói lẫn viết; sự lịch sự đến từ đuôi của mệnh đề theo sau, chứ không phải từ bản thân 텐데. Lỗi phổ biến nhất của người học là bỏ qua quy tắc 받침 và viết 먹을 텐데 thành 먹텐데, hoặc đọc sai nguồn gốc 터 + ㄴ데 rồi viết thành 텐테/텐대. Trong lời nói thân mật, bạn cũng sẽ nghe những câu bỏ lửng ở 텐데... để ngụ ý nỗi lo mà không nói thẳng ra.',
      '-(으)ㄹ 텐데 は、根拠のある確信的な推量(「〜だと思う/〜のはずだ」)を表し、たいてい対比や心配を含む後続の節が続くため、しばしば「…のはずだけど、…」という形になります。これは -(으)ㄹ 터(「予想・意図」)に -ㄴ데 が付いた形が土台です。動詞や形容詞の語幹に付けます。母音語幹や ㄹ 語幹には -ㄹ 텐데 が付き(오다 → 올 텐데、살다 → 살 텐데、ㄹ は残ります)、パッチム(받침)のある子音語幹には -을 텐데 が付きます(먹다 → 먹을 텐데、좋다 → 좋을 텐데)。過去の状況には -았/었을 텐데 を使い(벌써 도착했을 텐데 「もう着いているはずだけど、…」)、名詞の後では N+일 텐데 を使います(학생일 텐데)。비가 올 텐데 우산 가져가세요 =「きっと雨が降るから、傘を持って行ってください。」\n\n最も近くて注意すべきものは、ただの -(으)ㄹ 거예요(単純な予測)です。바쁠 거예요「たぶん忙しいでしょう」という淡々とした予報と、바쁠 텐데 도와줄 수 있을까? 「忙しいはずだけど、手伝ってくれる?」を比べてみてください。後者では 텐데 が話し手の推論を加え、対比や気がかりへの下地を作っています。텐데 は中立的な平叙文として単独では使えず、言外の「けれど/だから」へと傾きます。文体としては、話し言葉でも書き言葉でも中立的でよく使われ、丁寧さは 텐데 そのものではなく後続の節の語尾から生まれます。学習者の最も多い間違いは、받침 のルールを落として 먹을 텐데 を 먹텐데 と書いてしまうこと、あるいは 터 + ㄴ데 という由来を読み違えて 텐테/텐대 と綴ってしまうことです。くだけた話し言葉では、心配を言外にほのめかすために 텐데… と文を途中で途切れさせる言い方もよく耳にします。',
    ),
  '-(으)ㄹ 리가 없다': L(
      'Expresses the speaker\'s confident logical inference that something is impossible — "it can\'t be that ~ / there\'s no way that ~." You attach -(으)ㄹ 리가 없다 to the stem of a verb or adjective: a vowel/ㄹ stem takes -ㄹ 리가 없다 (오다 → 올 리가 없다 "there\'s no way they\'d come," 멀다 → 멀 리가 없다 "it can\'t be far," ㄹ kept), while a consonant (받침) stem takes -을 리가 없다 (먹다 → 먹을 리가 없다, 작다 → 작을 리가 없다). For past situations, build it on -았/었- before the form: 갔을 리가 없다 "there\'s no way they went," 알았을 리가 없다 "they couldn\'t have known." With nouns use 일 리가 없다 (사실일 리가 없다 "it can\'t be true"). The 가 is optional/droppable (올 리 없다), and you may also hear 리가 있다? as a rhetorical question meaning the same impossibility.\n\nCompare it with -(으)ㄹ 수 없다, which learners often confuse because both end in 없다. -(으)ㄹ 수 없다 means inability or impossibility of an action ("cannot do"), whereas -(으)ㄹ 리가 없다 is the speaker\'s reasoning that a claim cannot be the case. Minimal pair: 지금 갈 수 없어요 "I can\'t go right now (I\'m unable)" vs. 그 사람이 지금 갈 리가 없어요 "there\'s no way that person would go right now (I infer it\'s impossible)." Register-wise it\'s neutral and fully usable in both polite 해요체 (올 리가 없어요) and plain speech (올 리가 없어). The most common learner mistake is treating it as simple inability and swapping in -(으)ㄹ 수 없다, or forgetting the past needs -았/었을 리가 없다 (saying 갈 리가 없다 when meaning "couldn\'t have gone"). A frequent natural pattern is 그럴 리가 없어요 "that can\'t be right."',
      'Expresa la inferencia lógica y segura del hablante de que algo es imposible: "no puede ser que ~ / no hay manera de que ~". Le pegás -(으)ㄹ 리가 없다 a la raíz de un verbo o adjetivo: una raíz terminada en vocal o en ㄹ toma -ㄹ 리가 없다 (오다 → 올 리가 없다 "no hay manera de que vengan", 멀다 → 멀 리가 없다 "no puede estar lejos", se conserva la ㄹ), mientras que una raíz con consonante (받침) toma -을 리가 없다 (먹다 → 먹을 리가 없다, 작다 → 작을 리가 없다). Para situaciones pasadas, construilo sobre -았/었- antes de la forma: 갔을 리가 없다 "no hay manera de que hayan ido", 알았을 리가 없다 "no podían haberlo sabido". Con sustantivos usá 일 리가 없다 (사실일 리가 없다 "no puede ser verdad"). El 가 es opcional y se puede omitir (올 리 없다), y también vas a escuchar 리가 있다? como pregunta retórica que significa esa misma imposibilidad.\n\nComparalo con -(으)ㄹ 수 없다, que los estudiantes suelen confundir porque ambos terminan en 없다. -(으)ㄹ 수 없다 significa incapacidad o imposibilidad de una acción ("no poder hacer"), mientras que -(으)ㄹ 리가 없다 es el razonamiento del hablante de que una afirmación no puede ser el caso. Par mínimo: 지금 갈 수 없어요 "no puedo ir ahora mismo (no soy capaz)" vs. 그 사람이 지금 갈 리가 없어요 "no hay manera de que esa persona vaya ahora mismo (deduzco que es imposible)". En cuanto al registro es neutral y totalmente usable tanto en el cortés 해요체 (올 리가 없어요) como en el habla llana (올 리가 없어). El error más común es tratarlo como simple incapacidad y cambiarlo por -(으)ㄹ 수 없다, o olvidar que el pasado necesita -았/었을 리가 없다 (decir 갈 리가 없다 cuando querés decir "no podían haber ido"). Un patrón natural y frecuente es 그럴 리가 없어요 "eso no puede ser".',
      'Exprime l\'inférence logique et assurée du locuteur selon laquelle quelque chose est impossible : "il est impossible que ~ / il n\'y a aucune chance que ~". Tu attaches -(으)ㄹ 리가 없다 au radical d\'un verbe ou d\'un adjectif : un radical en voyelle ou en ㄹ prend -ㄹ 리가 없다 (오다 → 올 리가 없다 "il n\'y a aucune chance qu\'ils viennent", 멀다 → 멀 리가 없다 "ça ne peut pas être loin", le ㄹ est conservé), tandis qu\'un radical à consonne (받침) prend -을 리가 없다 (먹다 → 먹을 리가 없다, 작다 → 작을 리가 없다). Pour les situations passées, construis-le sur -았/었- avant la forme : 갔을 리가 없다 "il n\'y a aucune chance qu\'ils y soient allés", 알았을 리가 없다 "ils n\'auraient pas pu le savoir". Avec les noms, utilise 일 리가 없다 (사실일 리가 없다 "ça ne peut pas être vrai"). Le 가 est facultatif et peut être omis (올 리 없다), et tu entendras aussi 리가 있다? comme question rhétorique signifiant cette même impossibilité.\n\nCompare-le avec -(으)ㄹ 수 없다, que les apprenants confondent souvent parce que les deux se terminent en 없다. -(으)ㄹ 수 없다 signifie l\'incapacité ou l\'impossibilité d\'une action ("ne pas pouvoir faire"), tandis que -(으)ㄹ 리가 없다 est le raisonnement du locuteur selon lequel une affirmation ne peut pas être vraie. Paire minimale : 지금 갈 수 없어요 "je ne peux pas y aller tout de suite (j\'en suis incapable)" vs. 그 사람이 지금 갈 리가 없어요 "il n\'y a aucune chance que cette personne y aille tout de suite (j\'en déduis que c\'est impossible)". Côté registre, c\'est neutre et parfaitement utilisable aussi bien au poli 해요체 (올 리가 없어요) qu\'au langage familier (올 리가 없어). L\'erreur la plus fréquente des apprenants est de le traiter comme une simple incapacité et de le remplacer par -(으)ㄹ 수 없다, ou d\'oublier que le passé exige -았/었을 리가 없다 (dire 갈 리가 없다 alors qu\'on veut dire "ils n\'auraient pas pu y aller"). Un schéma naturel et fréquent est 그럴 리가 없어요 "ça ne peut pas être vrai".',
      'Expressa a inferência lógica e confiante do falante de que algo é impossível: "não pode ser que ~ / não tem como ~". Você anexa -(으)ㄹ 리가 없다 à raiz de um verbo ou adjetivo: uma raiz terminada em vogal ou em ㄹ recebe -ㄹ 리가 없다 (오다 → 올 리가 없다 "não tem como eles virem", 멀다 → 멀 리가 없다 "não pode ser longe", o ㄹ é mantido), enquanto uma raiz com consoante (받침) recebe -을 리가 없다 (먹다 → 먹을 리가 없다, 작다 → 작을 리가 없다). Para situações passadas, construa sobre -았/었- antes da forma: 갔을 리가 없다 "não tem como eles terem ido", 알았을 리가 없다 "eles não poderiam ter sabido". Com substantivos use 일 리가 없다 (사실일 리가 없다 "não pode ser verdade"). O 가 é opcional e pode ser omitido (올 리 없다), e você também vai ouvir 리가 있다? como pergunta retórica significando essa mesma impossibilidade.\n\nCompare com -(으)ㄹ 수 없다, que os estudantes costumam confundir porque ambos terminam em 없다. -(으)ㄹ 수 없다 significa incapacidade ou impossibilidade de uma ação ("não conseguir fazer"), enquanto -(으)ㄹ 리가 없다 é o raciocínio do falante de que uma afirmação não pode ser o caso. Par mínimo: 지금 갈 수 없어요 "não posso ir agora (sou incapaz)" vs. 그 사람이 지금 갈 리가 없어요 "não tem como essa pessoa ir agora (deduzo que é impossível)". Quanto ao registro, é neutro e totalmente utilizável tanto no polido 해요체 (올 리가 없어요) quanto na fala simples (올 리가 없어). O erro mais comum dos estudantes é tratá-lo como simples incapacidade e trocá-lo por -(으)ㄹ 수 없다, ou esquecer que o passado precisa de -았/었을 리가 없다 (dizer 갈 리가 없다 quando se quer dizer "não poderiam ter ido"). Um padrão natural e frequente é 그럴 리가 없어요 "isso não pode ser".',
      'แสดงการอนุมานเชิงตรรกะอย่างมั่นใจของผู้พูดว่าสิ่งใดสิ่งหนึ่งเป็นไปไม่ได้ — "เป็นไปไม่ได้ที่จะ ~ / ไม่มีทางที่จะ ~" คุณเติม -(으)ㄹ 리가 없다 เข้ากับรากของคำกริยาหรือคำคุณศัพท์: รากที่ลงท้ายด้วยสระหรือ ㄹ ใช้ -ㄹ 리가 없다 (오다 → 올 리가 없다 "ไม่มีทางที่พวกเขาจะมา", 멀다 → 멀 리가 없다 "เป็นไปไม่ได้ที่จะไกล", คง ㄹ ไว้) ส่วนรากที่ลงท้ายด้วยพยัญชนะ (받침) ใช้ -을 리가 없다 (먹다 → 먹을 리가 없다, 작다 → 작을 리가 없다) สำหรับเหตุการณ์ในอดีต ให้สร้างบน -았/었- ก่อนรูป: 갔을 리가 없다 "ไม่มีทางที่พวกเขาจะไป", 알았을 리가 없다 "พวกเขาไม่น่าจะรู้ได้" กับคำนามให้ใช้ 일 리가 없다 (사실일 리가 없다 "เป็นความจริงไม่ได้") ตัว 가 เป็นทางเลือกและละได้ (올 리 없다) และคุณอาจได้ยิน 리가 있다? เป็นคำถามเชิงวาทศิลป์ที่สื่อความเป็นไปไม่ได้แบบเดียวกันด้วย\n\nลองเทียบกับ -(으)ㄹ 수 없다 ซึ่งผู้เรียนมักสับสนเพราะทั้งคู่ลงท้ายด้วย 없다 -(으)ㄹ 수 없다 หมายถึงความไม่สามารถหรือความเป็นไปไม่ได้ของการกระทำ ("ทำไม่ได้") ในขณะที่ -(으)ㄹ 리가 없다 คือการให้เหตุผลของผู้พูดว่าข้อกล่าวอ้างหนึ่งเป็นจริงไม่ได้ คู่เปรียบเทียบขั้นต่ำ: 지금 갈 수 없어요 "ตอนนี้ฉันไปไม่ได้ (ไม่มีความสามารถจะไป)" กับ 그 사람이 지금 갈 리가 없어요 "ไม่มีทางที่คนคนนั้นจะไปตอนนี้ (ฉันอนุมานว่าเป็นไปไม่ได้)" ในแง่ของระดับภาษา มันเป็นกลางและใช้ได้เต็มที่ทั้งในรูปสุภาพ 해요체 (올 리가 없어요) และภาษาพูดธรรมดา (올 리가 없어) ข้อผิดพลาดที่พบบ่อยที่สุดของผู้เรียนคือมองว่ามันเป็นเพียงความไม่สามารถแล้วเปลี่ยนไปใช้ -(으)ㄹ 수 없다 หรือลืมว่ารูปอดีตต้องใช้ -았/었을 리가 없다 (พูด 갈 리가 없다 ทั้งที่ต้องการสื่อว่า "ไปไม่ได้แน่ ๆ ในอดีต") รูปแบบที่เป็นธรรมชาติและพบบ่อยคือ 그럴 리가 없어요 "เป็นแบบนั้นไม่ได้หรอก"',
      'Menyatakan kesimpulan logis penutur dengan penuh keyakinan bahwa sesuatu mustahil — "tidak mungkin ~ / tidak ada kemungkinan ~". Kamu melekatkan -(으)ㄹ 리가 없다 pada akar kata kerja atau kata sifat: akar berakhiran vokal atau ㄹ memakai -ㄹ 리가 없다 (오다 → 올 리가 없다 "tidak mungkin mereka datang", 멀다 → 멀 리가 없다 "tidak mungkin jauh", ㄹ dipertahankan), sedangkan akar berakhiran konsonan (받침) memakai -을 리가 없다 (먹다 → 먹을 리가 없다, 작다 → 작을 리가 없다). Untuk situasi lampau, bangun di atas -았/었- sebelum bentuknya: 갔을 리가 없다 "tidak mungkin mereka pergi", 알았을 리가 없다 "mereka tidak mungkin tahu". Dengan kata benda gunakan 일 리가 없다 (사실일 리가 없다 "tidak mungkin benar"). 가 bersifat opsional dan boleh dihilangkan (올 리 없다), dan kamu juga akan mendengar 리가 있다? sebagai pertanyaan retoris yang bermakna kemustahilan yang sama.\n\nBandingkan dengan -(으)ㄹ 수 없다, yang sering membingungkan pelajar karena keduanya berakhiran 없다. -(으)ㄹ 수 없다 berarti ketidakmampuan atau kemustahilan suatu tindakan ("tidak bisa melakukan"), sedangkan -(으)ㄹ 리가 없다 adalah penalaran penutur bahwa suatu klaim tidak mungkin benar. Pasangan minimal: 지금 갈 수 없어요 "saya tidak bisa pergi sekarang (tidak mampu)" vs. 그 사람이 지금 갈 리가 없어요 "tidak mungkin orang itu pergi sekarang (saya menyimpulkan itu mustahil)". Dari sisi ragam bahasa, ini netral dan sepenuhnya bisa dipakai baik dalam bentuk sopan 해요체 (올 리가 없어요) maupun bahasa biasa (올 리가 없어). Kesalahan pelajar yang paling umum adalah memperlakukannya sebagai sekadar ketidakmampuan lalu menggantinya dengan -(으)ㄹ 수 없다, atau lupa bahwa bentuk lampau memerlukan -았/었을 리가 없다 (mengatakan 갈 리가 없다 padahal maksudnya "tidak mungkin sudah pergi"). Pola alami yang sering muncul adalah 그럴 리가 없어요 "itu tidak mungkin benar".',
      'Diễn đạt suy luận logic đầy tự tin của người nói rằng điều gì đó là bất khả thi — "không thể nào ~ / chẳng có chuyện ~". Bạn gắn -(으)ㄹ 리가 없다 vào gốc của động từ hoặc tính từ: gốc kết thúc bằng nguyên âm hoặc ㄹ dùng -ㄹ 리가 없다 (오다 → 올 리가 없다 "chẳng có chuyện họ đến", 멀다 → 멀 리가 없다 "không thể nào xa được", giữ lại ㄹ), còn gốc có phụ âm cuối (받침) dùng -을 리가 없다 (먹다 → 먹을 리가 없다, 작다 → 작을 리가 없다). Với tình huống quá khứ, hãy dựng trên -았/었- trước cấu trúc: 갔을 리가 없다 "chẳng có chuyện họ đã đi", 알았을 리가 없다 "họ không thể nào biết được". Với danh từ thì dùng 일 리가 없다 (사실일 리가 없다 "không thể là sự thật"). Chữ 가 là tùy chọn và có thể lược bỏ (올 리 없다), và bạn cũng sẽ nghe 리가 있다? như một câu hỏi tu từ mang cùng nghĩa bất khả thi đó.\n\nHãy so sánh nó với -(으)ㄹ 수 없다, thứ mà người học thường nhầm lẫn vì cả hai đều kết thúc bằng 없다. -(으)ㄹ 수 없다 nghĩa là sự bất lực hoặc bất khả thi của một hành động ("không thể làm"), trong khi -(으)ㄹ 리가 없다 là lập luận của người nói rằng một khẳng định không thể là sự thật. Cặp tối thiểu: 지금 갈 수 없어요 "bây giờ tôi không đi được (không có khả năng)" so với 그 사람이 지금 갈 리가 없어요 "chẳng có chuyện người đó đi bây giờ (tôi suy ra điều đó là bất khả thi)". Về sắc thái, nó trung tính và hoàn toàn dùng được cả ở dạng lịch sự 해요체 (올 리가 없어요) lẫn lời nói thông thường (올 리가 없어). Lỗi phổ biến nhất của người học là coi nó như sự bất lực đơn thuần rồi thay bằng -(으)ㄹ 수 없다, hoặc quên rằng quá khứ cần -았/었을 리가 없다 (nói 갈 리가 없다 khi muốn nói "không thể nào đã đi"). Một mẫu câu tự nhiên và thường gặp là 그럴 리가 없어요 "không thể như vậy được".',
      '話し手が「ありえない・~なはずがない」と論理的に確信して推論する気持ちを表します。動詞や形容詞の語幹に -(으)ㄹ 리가 없다 を付けます。母音語幹や ㄹ 語幹には -ㄹ 리가 없다 が付き(오다 → 올 리가 없다「来るはずがない」、멀다 → 멀 리가 없다「遠いはずがない」、ㄹ は残ります)、子音(받침)語幹には -을 리가 없다 が付きます(먹다 → 먹을 리가 없다、작다 → 작을 리가 없다)。過去の状況では、形の前に -았/었- を入れて作ります:갔을 리가 없다「行ったはずがない」、알았을 리가 없다「知っていたはずがない」。名詞には 일 리가 없다 を使います(사실일 리가 없다「本当のはずがない」)。가 は任意で省略でき(올 리 없다)、同じ不可能性を表す反語として 리가 있다? と聞くこともあります。\n\n-(으)ㄹ 수 없다 と比べてみましょう。どちらも 없다 で終わるため、学習者がよく混同します。-(으)ㄹ 수 없다 は行為の不可能・できないこと(「~できない」)を表しますが、-(으)ㄹ 리가 없다 はある主張がそうであるはずがないという話し手の推論です。ミニマルペア:지금 갈 수 없어요「今は行けません(行く能力がない)」に対し、그 사람이 지금 갈 리가 없어요「あの人が今行くはずがありません(不可能だと推論している)」。語体としては中立で、丁寧な 해요체(올 리가 없어요)でもくだけた話し方(올 리가 없어)でも問題なく使えます。学習者の最も多い間違いは、単なる不可能と捉えて -(으)ㄹ 수 없다 に置き換えてしまうこと、または過去には -았/었을 리가 없다 が必要なのを忘れること(「行ったはずがない」の意味で 갈 리가 없다 と言ってしまう)です。よく使われる自然な表現に 그럴 리가 없어요「そんなはずがありません」があります。',
    ),
  '-(으)ㄹ걸 그랬다': L(
      '-(으)ㄹ걸 그랬다 expresses regret about something you did NOT do but now wish you had — "I should have…" / "I wish I\'d…". It attaches to the verb stem: a vowel/ㄹ stem takes -ㄹ걸 그랬다 (가다 → 갈걸 그랬다 "I should have gone"; 살다 → 살걸 그랬다, ㄹ stays), and a consonant (받침) stem takes -을걸 그랬다 (먹다 → 먹을걸 그랬다 "I should have eaten"; 입다 → 입을걸 그랬다). Crucially, the regret is already aimed at the past because 그랬다 ("did so") carries the past tense, so you do not have to mark the main verb for past. You may, however: 먹었을걸 그랬다 and 갔을걸 그랬다 are perfectly grammatical and in fact very common in everyday speech — the bare form (먹을걸 그랬다) and the past-marked form (먹었을걸 그랬다) coexist with essentially the same meaning, so neither is an error. The negative "I shouldn\'t have…" uses -지 말걸 그랬다 (사지 말걸 그랬다 "I shouldn\'t have bought it").\n\nThe confusable neighbour is -았/었어야 했다 ("had to / should have"). Compare 우산을 가져올걸 그랬어요 vs 우산을 가져왔어야 했어요: both mean "I should have brought an umbrella," but -(으)ㄹ걸 그랬다 is softer, more personal and emotional — a sigh of regret, often muttered to oneself — while -았/었어야 했다 sounds like a stronger obligation that went unmet, almost self-blame. In casual speech -(으)ㄹ걸 그랬다 is frequently shortened to just -(으)ㄹ걸 with falling intonation (그냥 집에 있을걸… "I should\'ve just stayed home…"). It is informal, so avoid it in formal writing or to a superior; for politeness add -요 (갈걸 그랬어요 / 갔을걸 그랬어요). The genuinely common learner pitfall is the opposite assumption — believing the past must never appear on the main verb — when in reality 갔을걸 그랬다 is just as natural as 갈걸 그랬다.',
      '-(으)ㄹ걸 그랬다 expresa arrepentimiento por algo que NO hiciste pero que ahora desearías haber hecho: "debería haber…" / "ojalá hubiera…". Se une a la raíz del verbo: una raíz terminada en vocal o en ㄹ toma -ㄹ걸 그랬다 (가다 → 갈걸 그랬다 "debería haber ido"; 살다 → 살걸 그랬다, la ㄹ se mantiene), y una raíz con consonante (받침) toma -을걸 그랬다 (먹다 → 먹을걸 그랬다 "debería haber comido"; 입다 → 입을걸 그랬다). Lo clave es que el arrepentimiento ya apunta al pasado porque 그랬다 ("lo hice así") lleva el tiempo pasado, así que no tenés que marcar el verbo principal en pasado. Sin embargo, podés: 먹었을걸 그랬다 y 갔을걸 그랬다 son perfectamente gramaticales y, de hecho, muy comunes en el habla cotidiana; la forma simple (먹을걸 그랬다) y la forma marcada en pasado (먹었을걸 그랬다) conviven con esencialmente el mismo significado, así que ninguna es un error. El negativo "no debería haber…" usa -지 말걸 그랬다 (사지 말걸 그랬다 "no debería haberlo comprado").\n\nEl vecino confundible es -았/었어야 했다 ("tenía que / debería haber"). Compará 우산을 가져올걸 그랬어요 vs 우산을 가져왔어야 했어요: ambas significan "debería haber traído un paraguas", pero -(으)ㄹ걸 그랬다 es más suave, más personal y emocional —un suspiro de arrepentimiento, a menudo murmurado para uno mismo—, mientras que -았/었어야 했다 suena como una obligación más fuerte que no se cumplió, casi un reproche a uno mismo. En el habla informal, -(으)ㄹ걸 그랬다 se acorta con frecuencia a solo -(으)ㄹ걸 con entonación descendente (그냥 집에 있을걸… "mejor me hubiera quedado en casa…"). Es informal, así que evitalo en la escritura formal o al dirigirte a un superior; para más cortesía agregá -요 (갈걸 그랬어요 / 갔을걸 그랬어요). El error realmente común del estudiante es la suposición contraria —creer que el pasado nunca debe aparecer en el verbo principal—, cuando en realidad 갔을걸 그랬다 es tan natural como 갈걸 그랬다.',
      '-(으)ㄹ걸 그랬다 exprime le regret d\'avoir NE PAS fait quelque chose qu\'on aurait aujourd\'hui voulu faire — « j\'aurais dû… » / « si seulement j\'avais… ». Il s\'attache au radical du verbe : un radical en voyelle ou en ㄹ prend -ㄹ걸 그랬다 (가다 → 갈걸 그랬다 « j\'aurais dû y aller » ; 살다 → 살걸 그랬다, le ㄹ reste), et un radical à consonne (받침) prend -을걸 그랬다 (먹다 → 먹을걸 그랬다 « j\'aurais dû manger » ; 입다 → 입을걸 그랬다). Point crucial : le regret vise déjà le passé parce que 그랬다 (« j\'ai fait ainsi ») porte le temps passé, donc tu n\'as pas à marquer le verbe principal au passé. Tu peux néanmoins le faire : 먹었을걸 그랬다 et 갔을걸 그랬다 sont parfaitement grammaticaux et en fait très courants dans la langue de tous les jours — la forme nue (먹을걸 그랬다) et la forme marquée au passé (먹었을걸 그랬다) coexistent avec essentiellement le même sens, aucune n\'est donc une erreur. Le négatif « je n\'aurais pas dû… » utilise -지 말걸 그랬다 (사지 말걸 그랬다 « je n\'aurais pas dû l\'acheter »).\n\nLe voisin que l\'on confond facilement est -았/었어야 했다 (« il fallait / on aurait dû »). Compare 우산을 가져올걸 그랬어요 et 우산을 가져왔어야 했어요 : les deux signifient « j\'aurais dû apporter un parapluie », mais -(으)ㄹ걸 그랬다 est plus doux, plus personnel et émotionnel — un soupir de regret, souvent marmonné pour soi-même — alors que -았/었어야 했다 sonne comme une obligation plus forte qui n\'a pas été remplie, presque un reproche envers soi-même. Dans le langage familier, -(으)ㄹ걸 그랬다 est souvent abrégé en simplement -(으)ㄹ걸 avec une intonation descendante (그냥 집에 있을걸… « j\'aurais mieux fait de rester à la maison… »). C\'est informel, donc évite-le à l\'écrit formel ou en t\'adressant à un supérieur ; pour la politesse, ajoute -요 (갈걸 그랬어요 / 갔을걸 그랬어요). Le piège vraiment fréquent pour l\'apprenant, c\'est l\'hypothèse inverse — croire que le passé ne doit jamais apparaître sur le verbe principal — alors qu\'en réalité 갔을걸 그랬다 est tout aussi naturel que 갈걸 그랬다.',
      '-(으)ㄹ걸 그랬다 expressa arrependimento por algo que você NÃO fez, mas que agora gostaria de ter feito — "eu deveria ter…" / "ah, se eu tivesse…". Liga-se ao radical do verbo: um radical terminado em vogal ou em ㄹ recebe -ㄹ걸 그랬다 (가다 → 갈걸 그랬다 "eu deveria ter ido"; 살다 → 살걸 그랬다, o ㄹ permanece), e um radical com consoante (받침) recebe -을걸 그랬다 (먹다 → 먹을걸 그랬다 "eu deveria ter comido"; 입다 → 입을걸 그랬다). O ponto crucial é que o arrependimento já aponta para o passado porque 그랬다 ("fiz assim") carrega o tempo passado, então você não precisa marcar o verbo principal no passado. Ainda assim, você pode: 먹었을걸 그랬다 e 갔을걸 그랬다 são perfeitamente gramaticais e, na verdade, muito comuns na fala do dia a dia — a forma simples (먹을걸 그랬다) e a forma marcada no passado (먹었을걸 그랬다) coexistem com essencialmente o mesmo sentido, então nenhuma das duas é erro. O negativo "eu não deveria ter…" usa -지 말걸 그랬다 (사지 말걸 그랬다 "eu não deveria ter comprado").\n\nO vizinho fácil de confundir é -았/었어야 했다 ("tinha que / deveria ter"). Compare 우산을 가져올걸 그랬어요 com 우산을 가져왔어야 했어요: ambos significam "eu deveria ter trazido um guarda-chuva", mas -(으)ㄹ걸 그랬다 é mais suave, mais pessoal e emocional — um suspiro de arrependimento, muitas vezes murmurado para si mesmo — enquanto -았/었어야 했다 soa como uma obrigação mais forte que não foi cumprida, quase uma autocensura. Na fala informal, -(으)ㄹ걸 그랬다 é frequentemente abreviado para apenas -(으)ㄹ걸 com entonação descendente (그냥 집에 있을걸… "eu deveria ter ficado em casa…"). É informal, então evite-o na escrita formal ou ao se dirigir a um superior; para mais educação, acrescente -요 (갈걸 그랬어요 / 갔을걸 그랬어요). A armadilha realmente comum do estudante é a suposição oposta — acreditar que o passado nunca pode aparecer no verbo principal — quando, na verdade, 갔을걸 그랬다 é tão natural quanto 갈걸 그랬다.',
      '-(으)ㄹ걸 그랬다 ใช้แสดงความเสียดายต่อสิ่งที่คุณ "ไม่ได้ทำ" แต่ตอนนี้กลับอยากให้ตัวเองได้ทำไป — "น่าจะ…" / "รู้งี้…ก็คงจะ…". มันเติมท้ายรากศัพท์ของกริยา: รากที่ลงท้ายด้วยสระหรือ ㄹ จะใช้ -ㄹ걸 그랬다 (가다 → 갈걸 그랬다 "น่าจะไปซะ"; 살다 → 살걸 그랬다 โดย ㄹ ยังคงอยู่) ส่วนรากที่ลงท้ายด้วยพยัญชนะ (받침) จะใช้ -을걸 그랬다 (먹다 → 먹을걸 그랬다 "น่าจะกินซะ"; 입다 → 입을걸 그랬다). จุดสำคัญคือความเสียดายนั้นชี้ไปที่อดีตอยู่แล้ว เพราะ 그랬다 ("ทำไปอย่างนั้น") เป็นตัวที่แบกรูปอดีตไว้ ดังนั้นคุณจึงไม่จำเป็นต้องผันกริยาหลักให้เป็นอดีต แต่คุณก็ทำได้เช่นกัน: 먹었을걸 그랬다 และ 갔을걸 그랬다 ถูกต้องตามไวยากรณ์อย่างสมบูรณ์ และที่จริงพบบ่อยมากในภาษาพูดประจำวัน — รูปธรรมดา (먹을걸 그랬다) กับรูปที่ผันอดีต (먹었을걸 그랬다) อยู่ร่วมกันได้โดยมีความหมายเหมือนกันแทบทุกประการ จึงไม่มีรูปไหนผิด ส่วนรูปปฏิเสธ "ไม่น่าจะ…" ใช้ -지 말걸 그랬다 (사지 말걸 그랬다 "ไม่น่าซื้อเลย").\n\nคำใกล้เคียงที่มักสับสนคือ -았/었어야 했다 ("ควรจะต้อง / น่าจะต้อง"). ลองเปรียบเทียบ 우산을 가져올걸 그랬어요 กับ 우산을 가져왔어야 했어요: ทั้งสองแปลว่า "น่าจะเอาร่มมาด้วย" แต่ -(으)ㄹ걸 그랬다 นั้นนุ่มนวลกว่า เป็นเรื่องส่วนตัวและเปี่ยมอารมณ์มากกว่า — เหมือนเสียงถอนหายใจด้วยความเสียดาย มักพึมพำกับตัวเอง — ในขณะที่ -았/었어야 했다 ฟังดูเหมือนภาระหน้าที่ที่หนักแน่นกว่าซึ่งไม่ได้ทำตาม เกือบจะเป็นการตำหนิตัวเอง ในภาษาพูดแบบกันเอง -(으)ㄹ걸 그랬다 มักถูกย่อเหลือเพียง -(으)ㄹ걸 พร้อมเสียงตกท้าย (그냥 집에 있을걸… "น่าจะอยู่บ้านเฉย ๆ ซะ…"). มันเป็นรูปไม่เป็นทางการ จึงควรเลี่ยงในงานเขียนทางการหรือเมื่อพูดกับผู้ที่อาวุโสกว่า; หากต้องการความสุภาพให้เติม -요 (갈걸 그랬어요 / 갔을걸 그랬어요). กับดักที่ผู้เรียนมักพลาดจริง ๆ คือการเข้าใจกลับกัน — คิดว่าห้ามใส่รูปอดีตที่กริยาหลักเด็ดขาด — ทั้งที่จริงแล้ว 갔을걸 그랬다 เป็นธรรมชาติพอ ๆ กับ 갈걸 그랬다.',
      '-(으)ㄹ걸 그랬다 mengungkapkan penyesalan atas sesuatu yang TIDAK kamu lakukan tetapi kini kamu berharap telah melakukannya — "seharusnya aku…" / "andai aku tadi…". Akhiran ini menempel pada akar verba: akar berakhiran vokal atau ㄹ memakai -ㄹ걸 그랬다 (가다 → 갈걸 그랬다 "seharusnya aku pergi"; 살다 → 살걸 그랬다, ㄹ tetap ada), sedangkan akar berakhiran konsonan (받침) memakai -을걸 그랬다 (먹다 → 먹을걸 그랬다 "seharusnya aku makan"; 입다 → 입을걸 그랬다). Yang penting, penyesalannya sudah mengarah ke masa lampau karena 그랬다 ("melakukan begitu") membawa kala lampau, jadi kamu tidak perlu menandai verba utama dengan bentuk lampau. Namun, kamu boleh saja: 먹었을걸 그랬다 dan 갔을걸 그랬다 sepenuhnya benar secara tata bahasa dan justru sangat umum dalam percakapan sehari-hari — bentuk polos (먹을걸 그랬다) dan bentuk berkala lampau (먹었을걸 그랬다) hidup berdampingan dengan makna yang pada dasarnya sama, jadi tidak ada yang salah. Bentuk negatif "seharusnya aku tidak…" memakai -지 말걸 그랬다 (사지 말걸 그랬다 "seharusnya aku tidak membelinya").\n\nTetangga yang mudah dikacaukan adalah -았/었어야 했다 ("harus / seharusnya"). Bandingkan 우산을 가져올걸 그랬어요 dengan 우산을 가져왔어야 했어요: keduanya berarti "seharusnya aku membawa payung", tetapi -(으)ㄹ걸 그랬다 lebih lembut, lebih pribadi dan emosional — sebuah desahan penyesalan, sering digumamkan kepada diri sendiri — sementara -았/었어야 했다 terdengar seperti kewajiban yang lebih kuat yang tidak terpenuhi, hampir menyalahkan diri sendiri. Dalam percakapan santai, -(으)ㄹ걸 그랬다 sering dipersingkat menjadi sekadar -(으)ㄹ걸 dengan intonasi menurun (그냥 집에 있을걸… "mendingan tadi aku di rumah saja…"). Bentuk ini informal, jadi hindari dalam tulisan resmi atau saat berbicara kepada orang yang lebih senior; untuk kesopanan, tambahkan -요 (갈걸 그랬어요 / 갔을걸 그랬어요). Jebakan yang benar-benar umum bagi pembelajar justru asumsi sebaliknya — mengira bentuk lampau tidak boleh muncul pada verba utama — padahal kenyataannya 갔을걸 그랬다 sama alaminya dengan 갈걸 그랬다.',
      '-(으)ㄹ걸 그랬다 diễn tả sự tiếc nuối về điều mà bạn đã KHÔNG làm nhưng giờ lại ước rằng mình đã làm — "đáng lẽ ra nên…" / "ước gì hồi đó mình đã…". Nó gắn vào gốc động từ: gốc kết thúc bằng nguyên âm hoặc ㄹ dùng -ㄹ걸 그랬다 (가다 → 갈걸 그랬다 "đáng lẽ ra nên đi"; 살다 → 살걸 그랬다, ㄹ vẫn được giữ lại), còn gốc kết thúc bằng phụ âm (받침) dùng -을걸 그랬다 (먹다 → 먹을걸 그랬다 "đáng lẽ ra nên ăn"; 입다 → 입을걸 그랬다). Điều quan trọng là sự tiếc nuối vốn đã hướng về quá khứ rồi, vì 그랬다 ("đã làm như vậy") mang thì quá khứ, nên bạn không cần đánh dấu thì quá khứ cho động từ chính. Tuy nhiên, bạn vẫn có thể: 먹었을걸 그랬다 và 갔을걸 그랬다 hoàn toàn đúng ngữ pháp và thực ra rất phổ biến trong lời ăn tiếng nói hằng ngày — dạng trần (먹을걸 그랬다) và dạng có đánh dấu quá khứ (먹었을걸 그랬다) cùng tồn tại với nghĩa về cơ bản là giống nhau, nên không dạng nào là sai cả. Thể phủ định "đáng lẽ ra không nên…" dùng -지 말걸 그랬다 (사지 말걸 그랬다 "đáng lẽ ra không nên mua nó").\n\nCấu trúc hàng xóm dễ gây nhầm lẫn là -았/었어야 했다 ("lẽ ra phải / đáng lẽ nên"). Hãy so sánh 우산을 가져올걸 그랬어요 với 우산을 가져왔어야 했어요: cả hai đều nghĩa là "đáng lẽ ra nên mang theo ô", nhưng -(으)ㄹ걸 그랬다 nhẹ nhàng hơn, mang tính cá nhân và cảm xúc hơn — như một tiếng thở dài tiếc nuối, thường lẩm bẩm một mình — trong khi -았/었어야 했다 nghe như một nghĩa vụ mạnh mẽ hơn đã không được thực hiện, gần như tự trách bản thân. Trong khẩu ngữ thân mật, -(으)ㄹ걸 그랬다 thường được rút gọn thành chỉ còn -(으)ㄹ걸 với ngữ điệu đi xuống (그냥 집에 있을걸… "biết vậy cứ ở nhà cho rồi…"). Đây là cách nói thân mật, vì vậy hãy tránh dùng trong văn viết trang trọng hoặc khi nói với người trên; để lịch sự hơn thì thêm -요 (갈걸 그랬어요 / 갔을걸 그랬어요). Cái bẫy thật sự phổ biến với người học lại là giả định ngược lại — tin rằng quá khứ tuyệt đối không được xuất hiện trên động từ chính — trong khi thực tế 갔을걸 그랬다 cũng tự nhiên y như 갈걸 그랬다.',
      '-(으)ㄹ걸 그랬다 は、実際にはしなかったが今になって「すればよかった」と悔やむ気持ちを表します — 「~すればよかった」「~しておけばよかった」。動詞の語幹に付きます。母音または ㄹ で終わる語幹には -ㄹ걸 그랬다 が付き(가다 → 갈걸 그랬다「行けばよかった」、살다 → 살걸 그랬다、ㄹ はそのまま残る)、子音（받침）で終わる語幹には -을걸 그랬다 が付きます（먹다 → 먹을걸 그랬다「食べればよかった」、입다 → 입을걸 그랬다）。重要なのは、그랬다（「そうした」）が過去時制を担っているため、後悔はすでに過去に向けられており、本動詞を過去形にする必要はないという点です。とはいえ過去形にしても構いません。먹었을걸 그랬다 や 갔을걸 그랬다 は文法的に完全に正しく、実際、日常会話では非常によく使われます。素の形（먹을걸 그랬다）と過去を付けた形（먹었을걸 그랬다）は本質的に同じ意味で共存しており、どちらも誤りではありません。否定の「~しなければよかった」は -지 말걸 그랬다 を使います（사지 말걸 그랬다「買わなければよかった」）。\n\n紛らわしい類義表現は -았/었어야 했다（「~すべきだった/しなければならなかった」）です。우산을 가져올걸 그랬어요 と 우산을 가져왔어야 했어요 を比べてみましょう。どちらも「傘を持ってくればよかった」という意味ですが、-(으)ㄹ걸 그랬다 はより柔らかく、より個人的で感情的 — 後悔のため息のようで、しばしば独り言のようにつぶやかれます — 一方 -았/었어야 했다 は、果たせなかったより強い義務、ほとんど自責のように響きます。くだけた話し言葉では、-(으)ㄹ걸 그랬다 はしばしば下降調のイントネーションで -(으)ㄹ걸 だけに短縮されます（그냥 집에 있을걸…「ただ家にいればよかった…」）。これはインフォーマルな表現なので、フォーマルな文章や目上の人に対しては避けましょう。丁寧にするには -요 を付けます（갈걸 그랬어요 / 갔을걸 그랬어요）。学習者が本当によく陥る落とし穴は、その逆の思い込み — 本動詞には決して過去を付けてはならないと信じること — ですが、実際には 갔을걸 그랬다 は 갈걸 그랬다 と同じくらい自然です。',
    ),
  '-(으)ㄴ/는 것을 보니': L(
      'Used to draw a conclusion from visible evidence — "judging from / seeing that / given that ..." The speaker observes a fact in the first clause and infers something in the second. It attaches to a verb stem as a modifier ending plus 것을 보니: present action verb → -는 것을 보니 (먹다 → 먹는 것을 보니 "seeing that he\'s eating"); past → -(으)ㄴ 것을 보니 (consonant stem 먹다 → 먹은 것을 보니, vowel/ㄹ stem 가다 → 간 것을 보니 "seeing that he left"). Adjectives take -(으)ㄴ 것을 보니 (바쁘다 → 바쁜 것을 보니), and a noun takes 인 것을 보니 (학생인 것을 보니). The object marker 을 is often dropped in speech, giving 것 보니, and 거 보니 is the casual contraction. Example: 우산을 든 것을 보니 비가 오나 봐요 "Judging from the umbrella he\'s carrying, it must be raining."\n\nDon\'t confuse it with -기 때문에 ("because"). Both relate two clauses, but the difference is evidence vs. cause: 불이 꺼진 것을 보니 자나 봐요 "seeing the light is off, she must be asleep" reasons FROM a clue toward a guess, while 불이 꺼졌기 때문에 안 보여요 "because the light went off, I can\'t see" states a direct cause and produces a fact, not a guess. So -것을 보니 normally pairs with an inference ending like -나 보다 / -(으)ㄴ/는 모양이다 / -겠- in the main clause, and it sounds odd with a flat factual result. Register is neutral and works in both polite (보니까 is the slightly more colloquial variant) and written styles. The most common learner mistake is choosing the wrong modifier tense — using -는 것을 보니 for a completed action instead of -(으)ㄴ 것을 보니 (e.g. saying 간 vs 가는) — so always match the ending to whether the observed event is ongoing or finished.',
      'Se usa para sacar una conclusión a partir de evidencia visible: "a juzgar por / viendo que / dado que...". El hablante observa un hecho en la primera cláusula e infiere algo en la segunda. Se adjunta a la raíz de un verbo como terminación de modificador más 것을 보니: verbo de acción en presente → -는 것을 보니 (먹다 → 먹는 것을 보니 "viendo que está comiendo"); pasado → -(으)ㄴ 것을 보니 (raíz consonántica 먹다 → 먹은 것을 보니, raíz en vocal/ㄹ 가다 → 간 것을 보니 "viendo que se fue"). Los adjetivos toman -(으)ㄴ 것을 보니 (바쁘다 → 바쁜 것을 보니), y un sustantivo toma 인 것을 보니 (학생인 것을 보니). El marcador de objeto 을 muchas veces se omite al hablar, dando 것 보니, y 거 보니 es la contracción casual. Ejemplo: 우산을 든 것을 보니 비가 오나 봐요 "A juzgar por el paraguas que lleva, debe estar lloviendo".\n\nNo lo confundás con -기 때문에 ("porque"). Ambos relacionan dos cláusulas, pero la diferencia es evidencia vs. causa: 불이 꺼진 것을 보니 자나 봐요 "viendo que la luz está apagada, debe estar dormida" razona DESDE una pista hacia una suposición, mientras que 불이 꺼졌기 때문에 안 보여요 "porque la luz se apagó, no veo" enuncia una causa directa y produce un hecho, no una suposición. Por eso -것을 보니 normalmente se combina con una terminación de inferencia como -나 보다 / -(으)ㄴ/는 모양이다 / -겠- en la cláusula principal, y suena raro con un resultado fáctico plano. El registro es neutral y funciona tanto en estilo cortés (보니까 es la variante un poco más coloquial) como escrito. El error más común del estudiante es elegir el tiempo equivocado del modificador: usar -는 것을 보니 para una acción terminada en vez de -(으)ㄴ 것을 보니 (por ejemplo, decir 간 vs 가는), así que siempre emparejá la terminación con si el evento observado está en curso o ya terminó.',
      'S\'emploie pour tirer une conclusion à partir d\'un indice visible — « à en juger par / voyant que / étant donné que... ». Le locuteur observe un fait dans la première proposition et en déduit quelque chose dans la seconde. Cela s\'attache au radical d\'un verbe sous forme de terminaison de modificateur suivie de 것을 보니 : verbe d\'action au présent → -는 것을 보니 (먹다 → 먹는 것을 보니 « voyant qu\'il mange ») ; passé → -(으)ㄴ 것을 보니 (radical en consonne 먹다 → 먹은 것을 보니, radical en voyelle/ㄹ 가다 → 간 것을 보니 « voyant qu\'il est parti »). Les adjectifs prennent -(으)ㄴ 것을 보니 (바쁘다 → 바쁜 것을 보니), et un nom prend 인 것을 보니 (학생인 것을 보니). Le marqueur d\'objet 을 est souvent omis à l\'oral, ce qui donne 것 보니, et 거 보니 est la contraction familière. Exemple : 우산을 든 것을 보니 비가 오나 봐요 « À en juger par le parapluie qu\'il porte, il doit pleuvoir ».\n\nNe le confonds pas avec -기 때문에 (« parce que »). Les deux relient deux propositions, mais la différence est indice vs. cause : 불이 꺼진 것을 보니 자나 봐요 « voyant que la lumière est éteinte, elle doit dormir » raisonne À PARTIR d\'un indice vers une supposition, tandis que 불이 꺼졌기 때문에 안 보여요 « parce que la lumière s\'est éteinte, je ne vois pas » énonce une cause directe et produit un fait, pas une supposition. C\'est pourquoi -것을 보니 se combine normalement avec une terminaison d\'inférence comme -나 보다 / -(으)ㄴ/는 모양이다 / -겠- dans la proposition principale, et sonne bizarrement avec un résultat factuel neutre. Le registre est neutre et fonctionne aussi bien en style poli (보니까 est la variante un peu plus familière) qu\'à l\'écrit. L\'erreur la plus fréquente des apprenants est de choisir le mauvais temps du modificateur — utiliser -는 것을 보니 pour une action achevée au lieu de -(으)ㄴ 것을 보니 (par exemple dire 간 vs 가는) — alors accorde toujours la terminaison selon que l\'événement observé est en cours ou terminé.',
      'Usado para tirar uma conclusão a partir de evidência visível — "a julgar por / vendo que / dado que...". O falante observa um fato na primeira oração e infere algo na segunda. Liga-se ao radical de um verbo como terminação de modificador mais 것을 보니: verbo de ação no presente → -는 것을 보니 (먹다 → 먹는 것을 보니 "vendo que ele está comendo"); passado → -(으)ㄴ 것을 보니 (radical em consoante 먹다 → 먹은 것을 보니, radical em vogal/ㄹ 가다 → 간 것을 보니 "vendo que ele foi embora"). Os adjetivos usam -(으)ㄴ 것을 보니 (바쁘다 → 바쁜 것을 보니), e um substantivo usa 인 것을 보니 (학생인 것을 보니). O marcador de objeto 을 muitas vezes é omitido na fala, resultando em 것 보니, e 거 보니 é a contração informal. Exemplo: 우산을 든 것을 보니 비가 오나 봐요 "A julgar pelo guarda-chuva que ele carrega, deve estar chovendo".\n\nNão confunda com -기 때문에 ("porque"). Ambos relacionam duas orações, mas a diferença é evidência vs. causa: 불이 꺼진 것을 보니 자나 봐요 "vendo que a luz está apagada, ela deve estar dormindo" raciocina A PARTIR de uma pista em direção a uma suposição, enquanto 불이 꺼졌기 때문에 안 보여요 "porque a luz se apagou, não consigo ver" enuncia uma causa direta e produz um fato, não uma suposição. Por isso -것을 보니 normalmente se combina com uma terminação de inferência como -나 보다 / -(으)ㄴ/는 모양이다 / -겠- na oração principal, e soa estranho com um resultado factual neutro. O registro é neutro e funciona tanto no estilo polido (보니까 é a variante um pouco mais coloquial) quanto no escrito. O erro mais comum dos aprendizes é escolher o tempo errado do modificador — usar -는 것을 보니 para uma ação concluída em vez de -(으)ㄴ 것을 보니 (por exemplo, dizer 간 vs 가는) — então sempre combine a terminação com o fato de o evento observado estar em curso ou já ter terminado.',
      'ใช้เพื่อสรุปข้อสันนิษฐานจากหลักฐานที่มองเห็นได้ — "ดูจาก / เห็นว่า / เมื่อพิจารณาจาก...". ผู้พูดสังเกตข้อเท็จจริงในประโยคแรกแล้วอนุมานบางอย่างในประโยคที่สอง โดยเติมท้ายรากศัพท์ของคำกริยาในรูปคำขยายตามด้วย 것을 보니: คำกริยาแสดงการกระทำในปัจจุบัน → -는 것을 보니 (먹다 → 먹는 것을 보니 "เห็นว่าเขากำลังกิน"); อดีต → -(으)ㄴ 것을 보니 (รากศัพท์ลงท้ายด้วยพยัญชนะ 먹다 → 먹은 것을 보니, รากศัพท์ลงท้ายด้วยสระ/ㄹ 가다 → 간 것을 보니 "เห็นว่าเขาไปแล้ว"). คำคุณศัพท์ใช้ -(으)ㄴ 것을 보니 (바쁘다 → 바쁜 것을 보니) และคำนามใช้ 인 것을 보니 (학생인 것을 보니). คำชี้กรรม 을 มักถูกละในการพูด กลายเป็น 것 보니 และ 거 보니 คือรูปย่อแบบไม่เป็นทางการ ตัวอย่าง: 우산을 든 것을 보니 비가 오나 봐요 "ดูจากร่มที่เขาถืออยู่ ฝนคงกำลังตก".\n\nอย่าสับสนกับ -기 때문에 ("เพราะว่า") ทั้งสองเชื่อมสองประโยคเข้าด้วยกัน แต่ความต่างคือหลักฐาน vs. สาเหตุ: 불이 꺼진 것을 보니 자나 봐요 "เห็นว่าไฟดับ เธอคงหลับแล้ว" เป็นการให้เหตุผลจากเบาะแสไปสู่การคาดเดา ขณะที่ 불이 꺼졌기 때문에 안 보여요 "เพราะไฟดับ ฉันจึงมองไม่เห็น" ระบุสาเหตุโดยตรงและให้ผลเป็นข้อเท็จจริง ไม่ใช่การคาดเดา ดังนั้น -것을 보니 มักจับคู่กับคำลงท้ายแสดงการอนุมานอย่าง -나 보다 / -(으)ㄴ/는 모양이다 / -겠- ในประโยคหลัก และจะฟังดูแปลกหากตามด้วยผลลัพธ์ที่เป็นข้อเท็จจริงเรียบ ๆ ระดับภาษาเป็นกลางและใช้ได้ทั้งในรูปสุภาพ (보니까 เป็นรูปที่ค่อนข้างเป็นกันเองกว่าเล็กน้อย) และในภาษาเขียน ข้อผิดพลาดที่ผู้เรียนพบบ่อยที่สุดคือเลือกกาลของคำขยายผิด — ใช้ -는 것을 보니 กับการกระทำที่เสร็จสิ้นแล้วแทนที่จะใช้ -(으)ㄴ 것을 보니 (เช่น พูด 간 กับ 가는) — ดังนั้นจงจับคู่คำลงท้ายให้ตรงกับว่าเหตุการณ์ที่สังเกตนั้นกำลังดำเนินอยู่หรือสิ้นสุดแล้วเสมอ',
      'Digunakan untuk menarik kesimpulan dari bukti yang terlihat — "dilihat dari / melihat bahwa / mengingat bahwa...". Penutur mengamati suatu fakta di klausa pertama lalu menyimpulkan sesuatu di klausa kedua. Bentuk ini melekat pada akar kata kerja sebagai akhiran pemodifikasi ditambah 것을 보니: kata kerja aksi bentuk kini → -는 것을 보니 (먹다 → 먹는 것을 보니 "melihat bahwa dia sedang makan"); lampau → -(으)ㄴ 것을 보니 (akar berkonsonan 먹다 → 먹은 것을 보니, akar bervokal/ㄹ 가다 → 간 것을 보니 "melihat bahwa dia sudah pergi"). Kata sifat memakai -(으)ㄴ 것을 보니 (바쁘다 → 바쁜 것을 보니), dan kata benda memakai 인 것을 보니 (학생인 것을 보니). Penanda objek 을 sering dihilangkan dalam percakapan, menjadi 것 보니, dan 거 보니 adalah kontraksi santainya. Contoh: 우산을 든 것을 보니 비가 오나 봐요 "Dilihat dari payung yang dibawanya, sepertinya sedang hujan".\n\nJangan keliru dengan -기 때문에 ("karena"). Keduanya menghubungkan dua klausa, tetapi perbedaannya adalah bukti vs. sebab: 불이 꺼진 것을 보니 자나 봐요 "melihat lampunya mati, dia mungkin sedang tidur" menalar DARI sebuah petunjuk menuju dugaan, sementara 불이 꺼졌기 때문에 안 보여요 "karena lampunya mati, aku tidak bisa melihat" menyatakan sebab langsung dan menghasilkan fakta, bukan dugaan. Maka -것을 보니 biasanya dipasangkan dengan akhiran inferensi seperti -나 보다 / -(으)ㄴ/는 모양이다 / -겠- di klausa utama, dan terdengar janggal dengan hasil faktual yang datar. Ragamnya netral dan cocok baik dalam gaya sopan (보니까 adalah varian yang sedikit lebih kolokial) maupun tulisan. Kesalahan pembelajar yang paling umum adalah memilih kala pemodifikasi yang salah — memakai -는 것을 보니 untuk aksi yang sudah selesai alih-alih -(으)ㄴ 것을 보니 (misalnya mengatakan 간 vs 가는) — jadi selalu sesuaikan akhiran dengan apakah peristiwa yang diamati sedang berlangsung atau sudah selesai.',
      'Dùng để rút ra kết luận từ bằng chứng nhìn thấy được — "xét theo / thấy rằng / căn cứ vào...". Người nói quan sát một sự việc ở mệnh đề thứ nhất và suy luận điều gì đó ở mệnh đề thứ hai. Nó gắn vào gốc động từ dưới dạng đuôi định ngữ cộng với 것을 보니: động từ hành động ở hiện tại → -는 것을 보니 (먹다 → 먹는 것을 보니 "thấy rằng anh ấy đang ăn"); quá khứ → -(으)ㄴ 것을 보니 (gốc kết thúc bằng phụ âm 먹다 → 먹은 것을 보니, gốc kết thúc bằng nguyên âm/ㄹ 가다 → 간 것을 보니 "thấy rằng anh ấy đã đi"). Tính từ dùng -(으)ㄴ 것을 보니 (바쁘다 → 바쁜 것을 보니), và danh từ dùng 인 것을 보니 (학생인 것을 보니). Trợ từ tân ngữ 을 thường được lược bỏ khi nói, thành 것 보니, và 거 보니 là dạng rút gọn thân mật. Ví dụ: 우산을 든 것을 보니 비가 오나 봐요 "Xét theo cây dù anh ấy đang cầm, chắc trời đang mưa".\n\nĐừng nhầm nó với -기 때문에 ("bởi vì"). Cả hai đều nối hai mệnh đề, nhưng khác biệt là bằng chứng và nguyên nhân: 불이 꺼진 것을 보니 자나 봐요 "thấy đèn đã tắt, chắc cô ấy đang ngủ" lập luận TỪ một manh mối hướng tới một phỏng đoán, trong khi 불이 꺼졌기 때문에 안 보여요 "vì đèn đã tắt nên tôi không nhìn thấy" nêu một nguyên nhân trực tiếp và tạo ra một sự thật, chứ không phải phỏng đoán. Vì vậy -것을 보니 thường đi kèm với một đuôi suy luận như -나 보다 / -(으)ㄴ/는 모양이다 / -겠- ở mệnh đề chính, và nghe sẽ kỳ cục nếu đi với một kết quả sự thật phẳng lặng. Văn phong trung tính và dùng được cả ở thể lịch sự (보니까 là biến thể hơi thân mật hơn một chút) lẫn văn viết. Lỗi phổ biến nhất của người học là chọn sai thì của định ngữ — dùng -는 것을 보니 cho một hành động đã hoàn tất thay vì -(으)ㄴ 것을 보니 (chẳng hạn nói 간 thay vì 가는) — nên hãy luôn khớp đuôi với việc sự việc được quan sát đang diễn ra hay đã kết thúc.',
      '目に見える証拠から結論を導くときに使います——「～から判断すると／～を見ると／～を考えると」。話し手は前の節で事実を観察し、後の節で何かを推測します。動詞の語幹に連体形の語尾＋것을 보니を付けます。現在の動作動詞 → -는 것을 보니（먹다 → 먹는 것을 보니「食べているのを見ると」）、過去 → -(으)ㄴ 것을 보니（子音語幹の먹다 → 먹은 것을 보니、母音/ㄹ語幹の가다 → 간 것을 보니「行ったのを見ると」）。形容詞は-(으)ㄴ 것을 보니（바쁘다 → 바쁜 것을 보니）、名詞は인 것을 보니（학생인 것을 보니）を取ります。目的格の을は話し言葉ではよく省略されて것 보니になり、거 보니はくだけた縮約形です。例：우산을 든 것을 보니 비가 오나 봐요「傘を持っているのを見ると、雨が降っているようです」。\n\n-기 때문에（「～だから」）と混同しないでください。どちらも二つの節をつなぎますが、違いは証拠か原因かです。불이 꺼진 것을 보니 자나 봐요「明かりが消えているのを見ると、寝ているようだ」は手がかりから推測へと推論しますが、불이 꺼졌기 때문에 안 보여요「明かりが消えたので見えない」は直接的な原因を述べ、推測ではなく事実を生みます。ですから-것을 보니は普通、主節で-나 보다 / -(으)ㄴ/는 모양이다 / -겠-のような推量の語尾と組み合わさり、単なる事実的な結果と一緒だと不自然に聞こえます。語調は中立的で、丁寧体（보니까はやや口語的な異形）でも書き言葉でも使えます。学習者が最も犯しやすい間違いは連体形の時制を取り違えることです——完了した動作に-(으)ㄴ 것을 보니ではなく-는 것을 보니を使う（例：간と가는を言い間違える）——ので、観察した出来事が進行中か完了したかに応じて、常に語尾を合わせてください。',
    ),
  '-다가': L(
      'Connects two actions by the same subject where the first is interrupted or suspended and a second action takes over — "was doing X, and then (mid-stream) Y." It attaches straight to the verb stem with no allomorph change: vowel/ㄹ stem 가다 → 가다가, 만들다 → 만들다가 (ㄹ stays); consonant stem 먹다 → 먹다가, 읽다 → 읽다가. So 학교에 가다가 친구를 만났어요 means "I was on my way to school and (then) met a friend" — the going stopped or was suspended when the meeting happened. With a past tense before it (-았/었다가) the first action is fully completed and then a second, often contrasting, action follows: 샀다가 환불했어요 "I bought it and then returned it." In speech it often shortens to -다 (가다가 → 가다).\n\nThe neighbour to separate it from is -고 나서 ("after doing"), which signals clean completion before the next action, with no interruption: 밥을 먹고 나서 산책했어요 "after I finished eating, I took a walk" versus 밥을 먹다가 전화를 받았어요 "I was eating and (broke off to) answer the phone." -다가 keeps the first action incomplete or running until the second cuts in; -고 나서 finishes it first. Register is neutral — the connector itself carries no politeness, and the sentence\'s level is set by the final ending, so it works in both 해요 and 합니다 speech, casual and formal. A common learner mistake is confusing it with the cumulative/discovery pattern 다 보면/다 보니까; another is forgetting that for the "interrupt and switch" sense the actor is normally the same person across both clauses. Spoken Korean frequently clips it to plain -다.',
      'Conecta dos acciones del mismo sujeto donde la primera se interrumpe o se suspende y una segunda acción toma el relevo: "estaba haciendo X, y entonces (a mitad de camino) Y". Se pega directo a la raíz del verbo sin cambio de alomorfo: raíz en vocal/ㄹ 가다 → 가다가, 만들다 → 만들다가 (la ㄹ se queda); raíz en consonante 먹다 → 먹다가, 읽다 → 읽다가. Así, 학교에 가다가 친구를 만났어요 significa "iba camino a la escuela y (entonces) me encontré con un amigo": el ir se detuvo o quedó suspendido cuando ocurrió el encuentro. Con un pasado delante (-았/었다가) la primera acción se completa por completo y luego sigue una segunda acción, a menudo contrastante: 샀다가 환불했어요 "lo compré y después lo devolví". Al hablar muchas veces se acorta a -다 (가다가 → 가다).\n\nEl vecino del que tenés que separarlo es -고 나서 ("después de hacer"), que marca una finalización limpia antes de la siguiente acción, sin interrupción: 밥을 먹고 나서 산책했어요 "después de terminar de comer, salí a caminar" frente a 밥을 먹다가 전화를 받았어요 "estaba comiendo y (lo corté para) contestar el teléfono". -다가 mantiene la primera acción incompleta o en curso hasta que la segunda la interrumpe; -고 나서 la termina primero. El registro es neutro: el conector en sí no carga ninguna cortesía, y el nivel de la oración lo fija la terminación final, así que funciona tanto en 해요 como en 합니다, informal y formal. Un error común de quien aprende es confundirlo con el patrón acumulativo/de descubrimiento 다 보면/다 보니까; otro es olvidar que, para el sentido de "interrumpir y cambiar", el actor normalmente es la misma persona en ambas cláusulas. El coreano hablado con frecuencia lo recorta al simple -다.',
      'Relie deux actions du même sujet où la première est interrompue ou suspendue et où une seconde action prend le relais — « j\'étais en train de faire X, et puis (en cours de route) Y ». Il s\'attache directement au radical du verbe sans changement d\'allomorphe : radical en voyelle/ㄹ 가다 → 가다가, 만들다 → 만들다가 (le ㄹ reste) ; radical en consonne 먹다 → 먹다가, 읽다 → 읽다가. Ainsi, 학교에 가다가 친구를 만났어요 signifie « j\'allais à l\'école et (alors) j\'ai rencontré un ami » — le fait d\'aller s\'est arrêté ou a été suspendu au moment de la rencontre. Avec un passé devant (-았/었다가), la première action est entièrement achevée, puis une seconde action, souvent contrastée, suit : 샀다가 환불했어요 « je l\'ai acheté puis je l\'ai rendu ». À l\'oral, ça se réduit souvent à -다 (가다가 → 가다).\n\nLe voisin dont il faut le distinguer est -고 나서 (« après avoir fait »), qui signale un achèvement net avant l\'action suivante, sans interruption : 밥을 먹고 나서 산책했어요 « après avoir fini de manger, je suis allé me promener » contre 밥을 먹다가 전화를 받았어요 « j\'étais en train de manger et (j\'ai interrompu pour) répondre au téléphone ». -다가 maintient la première action incomplète ou en cours jusqu\'à ce que la seconde s\'y insère ; -고 나서 la termine d\'abord. Le registre est neutre : le connecteur lui-même ne porte aucune politesse, et le niveau de la phrase est fixé par la terminaison finale, donc il fonctionne aussi bien en 해요 qu\'en 합니다, en langage familier comme soutenu. Une erreur fréquente chez les apprenants est de le confondre avec le schéma cumulatif/de découverte 다 보면/다 보니까 ; une autre est d\'oublier que, pour le sens « interrompre et basculer », l\'acteur est normalement la même personne dans les deux propositions. Le coréen parlé le réduit fréquemment au simple -다.',
      'Conecta duas ações do mesmo sujeito em que a primeira é interrompida ou suspensa e uma segunda ação assume o lugar — "eu estava fazendo X, e então (no meio do caminho) Y". Ele se liga direto ao radical do verbo sem mudança de alomorfe: radical em vogal/ㄹ 가다 → 가다가, 만들다 → 만들다가 (o ㄹ permanece); radical em consoante 먹다 → 먹다가, 읽다 → 읽다가. Assim, 학교에 가다가 친구를 만났어요 significa "eu estava a caminho da escola e (então) encontrei um amigo" — o ir parou ou foi suspenso quando o encontro aconteceu. Com um passado antes dele (-았/었다가), a primeira ação é totalmente concluída e depois segue uma segunda ação, muitas vezes contrastante: 샀다가 환불했어요 "comprei e depois devolvi". Na fala, costuma encurtar para -다 (가다가 → 가다).\n\nO vizinho do qual você precisa separá-lo é -고 나서 ("depois de fazer"), que sinaliza uma conclusão limpa antes da próxima ação, sem interrupção: 밥을 먹고 나서 산책했어요 "depois que terminei de comer, fui caminhar" versus 밥을 먹다가 전화를 받았어요 "eu estava comendo e (interrompi para) atender o telefone". O -다가 mantém a primeira ação incompleta ou em andamento até a segunda cortar; o -고 나서 termina ela primeiro. O registro é neutro — o conector em si não carrega nenhuma polidez, e o nível da frase é definido pela terminação final, então ele funciona tanto na fala 해요 quanto na 합니다, informal e formal. Um erro comum de quem está aprendendo é confundi-lo com o padrão cumulativo/de descoberta 다 보면/다 보니까; outro é esquecer que, para o sentido de "interromper e trocar", o agente normalmente é a mesma pessoa nas duas orações. O coreano falado frequentemente reduz para o simples -다.',
      'เชื่อมสองการกระทำของประธานคนเดียวกัน โดยการกระทำแรกถูกขัดจังหวะหรือถูกพักไว้ แล้วการกระทำที่สองเข้ามาแทนที่ — "กำลังทำ X อยู่ แล้วก็ (ระหว่างนั้น) Y" มันต่อกับรากศัพท์ของกริยาได้ตรงๆ โดยไม่มีการเปลี่ยนรูปอัลโลมอร์ฟ: รากที่ลงท้ายด้วยสระ/ㄹ 가다 → 가다가, 만들다 → 만들다가 (ㄹ ยังอยู่); รากที่ลงท้ายด้วยพยัญชนะ 먹다 → 먹다가, 읽다 → 읽다가 ดังนั้น 학교에 가다가 친구를 만났어요 หมายถึง "ฉันกำลังเดินทางไปโรงเรียน แล้ว (ก็) เจอเพื่อน" — การไปหยุดหรือถูกพักไว้เมื่อการพบเพื่อนเกิดขึ้น เมื่อมีรูปอดีตอยู่ข้างหน้า (-았/었다가) การกระทำแรกเสร็จสมบูรณ์อย่างเต็มที่ แล้วการกระทำที่สองซึ่งมักจะตรงกันข้ามจึงตามมา: 샀다가 환불했어요 "ฉันซื้อมันแล้วก็เอาไปคืน" ในการพูดมักจะย่อเป็น -다 (가다가 → 가다)\n\nตัวที่ต้องแยกออกจากกันคือ -고 나서 ("หลังจากทำ") ซึ่งบ่งบอกถึงการทำให้เสร็จสิ้นอย่างชัดเจนก่อนการกระทำถัดไป โดยไม่มีการขัดจังหวะ: 밥을 먹고 나서 산책했어요 "หลังจากกินข้าวเสร็จ ฉันก็ไปเดินเล่น" ตรงข้ามกับ 밥을 먹다가 전화를 받았어요 "ฉันกำลังกินข้าวอยู่ แล้ว (ก็หยุดเพื่อ) รับโทรศัพท์" -다가 ทำให้การกระทำแรกยังไม่เสร็จหรือยังดำเนินอยู่จนกระทั่งการกระทำที่สองเข้ามาแทรก ส่วน -고 나서 ทำให้มันเสร็จก่อน ระดับภาษาเป็นกลาง — ตัวเชื่อมเองไม่มีความสุภาพในตัว และระดับของประโยคถูกกำหนดโดยคำลงท้าย ดังนั้นมันใช้ได้ทั้งในการพูดแบบ 해요 และ 합니다 ทั้งแบบลำลองและทางการ ข้อผิดพลาดที่ผู้เรียนมักทำคือสับสนกับรูปแบบสะสม/การค้นพบ 다 보면/다 보니까; อีกอย่างคือลืมไปว่าสำหรับความหมาย "ขัดจังหวะแล้วเปลี่ยน" ผู้กระทำมักจะเป็นคนเดียวกันในทั้งสองอนุประโยค ภาษาเกาหลีพูดมักจะตัดให้สั้นเหลือเพียง -다',
      'Menghubungkan dua tindakan oleh subjek yang sama, di mana tindakan pertama terganggu atau ditangguhkan dan tindakan kedua mengambil alih — "sedang melakukan X, lalu (di tengah-tengah) Y". Ia menempel langsung pada akar kata kerja tanpa perubahan alomorf: akar berakhiran vokal/ㄹ 가다 → 가다가, 만들다 → 만들다가 (ㄹ tetap ada); akar berakhiran konsonan 먹다 → 먹다가, 읽다 → 읽다가. Jadi 학교에 가다가 친구를 만났어요 berarti "saya sedang dalam perjalanan ke sekolah dan (lalu) bertemu seorang teman" — perjalanannya berhenti atau ditangguhkan saat pertemuan itu terjadi. Dengan bentuk lampau di depannya (-았/었다가), tindakan pertama sepenuhnya selesai lalu diikuti tindakan kedua yang sering kali bertolak belakang: 샀다가 환불했어요 "saya membelinya lalu mengembalikannya". Dalam percakapan sering disingkat menjadi -다 (가다가 → 가다).\n\nTetangga yang harus kamu bedakan darinya adalah -고 나서 ("setelah melakukan"), yang menandakan penyelesaian yang tuntas sebelum tindakan berikutnya, tanpa gangguan: 밥을 먹고 나서 산책했어요 "setelah selesai makan, saya berjalan-jalan" berbeda dengan 밥을 먹다가 전화를 받았어요 "saya sedang makan dan (berhenti untuk) menjawab telepon". -다가 menjaga tindakan pertama tetap belum selesai atau sedang berlangsung sampai tindakan kedua menyela; -고 나서 menyelesaikannya terlebih dahulu. Tingkat tuturnya netral — konektornya sendiri tidak membawa kesopanan apa pun, dan tingkat kalimat ditentukan oleh akhiran terakhir, jadi ia bekerja baik dalam tuturan 해요 maupun 합니다, santai maupun formal. Kesalahan umum pembelajar adalah mengacaukannya dengan pola kumulatif/penemuan 다 보면/다 보니까; kesalahan lain adalah lupa bahwa untuk makna "menginterupsi dan beralih", pelakunya biasanya orang yang sama di kedua klausa. Bahasa Korea lisan sering memangkasnya menjadi -다 sederhana.',
      'Nối hai hành động của cùng một chủ thể, trong đó hành động thứ nhất bị gián đoạn hoặc tạm dừng và một hành động thứ hai thay thế — "đang làm X, rồi (giữa chừng) Y". Nó gắn thẳng vào gốc động từ mà không thay đổi tha hình vị: gốc kết thúc bằng nguyên âm/ㄹ 가다 → 가다가, 만들다 → 만들다가 (ㄹ vẫn giữ nguyên); gốc kết thúc bằng phụ âm 먹다 → 먹다가, 읽다 → 읽다가. Vậy 학교에 가다가 친구를 만났어요 nghĩa là "tôi đang trên đường đến trường thì (rồi) gặp một người bạn" — việc đi dừng lại hoặc bị tạm ngưng khi cuộc gặp xảy ra. Với một thì quá khứ đứng trước (-았/었다가), hành động thứ nhất hoàn tất trọn vẹn rồi một hành động thứ hai, thường trái ngược, mới theo sau: 샀다가 환불했어요 "tôi đã mua nó rồi trả lại". Trong khẩu ngữ nó thường rút gọn thành -다 (가다가 → 가다).\n\nCái cần phân biệt với nó là -고 나서 ("sau khi làm"), báo hiệu một sự hoàn tất gọn gàng trước hành động kế tiếp, không có gián đoạn: 밥을 먹고 나서 산책했어요 "sau khi ăn xong, tôi đi dạo" so với 밥을 먹다가 전화를 받았어요 "tôi đang ăn thì (ngừng lại để) nghe điện thoại". -다가 giữ cho hành động thứ nhất chưa hoàn tất hoặc đang diễn ra cho đến khi hành động thứ hai chen vào; -고 나서 hoàn tất nó trước. Mức độ ngôn ngữ trung lập — bản thân từ nối không mang sắc thái lịch sự nào, và mức độ của câu được quyết định bởi đuôi kết thúc, nên nó dùng được cả trong lối nói 해요 lẫn 합니다, cả thân mật lẫn trang trọng. Một lỗi thường gặp của người học là nhầm nó với mẫu tích lũy/phát hiện 다 보면/다 보니까; một lỗi khác là quên rằng với nghĩa "ngắt và chuyển", chủ thể thường là cùng một người ở cả hai mệnh đề. Tiếng Hàn nói thường rút gọn nó thành -다 đơn giản.',
      '同じ主語による二つの動作をつなぎ、最初の動作が中断・保留され、二つ目の動作がそれに取って代わることを表します — 「Xをしていて、それから(その途中で)Y」。語幹に直接つき、異形態の変化はありません。母音/ㄹ語幹 가다 → 가다가、만들다 → 만들다가(ㄹ は残る)、子音語幹 먹다 → 먹다가、읽다 → 읽다가。したがって 학교에 가다가 친구를 만났어요 は「学校へ行く途中で(それから)友達に会った」という意味で、会ったときに行くことが止まる、または保留されたわけです。前に過去形が来ると(-았/었다가)、最初の動作は完全に完了し、そのあとに二つ目の、しばしば対照的な動作が続きます。샀다가 환불했어요「買って、それから返品した」。話し言葉ではしばしば -다 に縮約されます(가다가 → 가다)。\n\n区別すべき隣人は -고 나서(「~したあとで」)で、これは中断なしに次の動作の前にきっぱりと完了することを示します。밥을 먹고 나서 산책했어요「ご飯を食べ終えてから、散歩した」に対して、밥을 먹다가 전화를 받았어요「ご飯を食べていて(中断して)電話に出た」。-다가 は二つ目の動作が割り込むまで最初の動作を未完了・進行中のままにします。-고 나서 はまずそれを終わらせます。語調は中立的です — 接続語そのものは丁寧さを持たず、文のレベルは文末表現で決まるので、해요 体でも 합니다 体でも、くだけた場面でもかしこまった場面でも使えます。学習者がよくする間違いは、累積・発見のパターン 다 보면/다 보니까 と混同することです。もう一つは、「中断して切り替える」の意味では、両方の節で動作主が通常同一人物であることを忘れることです。話し言葉の韓国語では頻繁に単なる -다 に縮められます。',
    ),
  '-(으)ㄴ/는 척하다': L(
      'Expresses pretending or feigning — "to pretend to / act as if (one) does or is something." It attaches to the descriptive form of a verb or adjective, so the allomorph depends on tense and word class. For a present action, use 는 척하다 on any verb stem regardless of 받침 (먹다 → 먹는 척하다 "pretend to eat," 자다 → 자는 척하다 "pretend to sleep"). For a present state (adjective) or a completed/past action, use -(으)ㄴ 척하다: a vowel/ㄹ stem takes -ㄴ (아프다 → 아픈 척하다 "pretend to be sick"; ㄹ drops: 알다 → 아는 척하다 "pretend to know"), while a consonant stem takes -은 (먹다 → 먹은 척하다 "pretend to have eaten," 좋다 → 좋은 척하다 "pretend to be nice/good"). 척하다 itself then conjugates normally: 척했어요, 척해요.\n\nA genuine confusable is 척하다 vs. -(으)ㄴ/는 것 같다 ("seem / look like"). The difference is intention: 척하다 is a deliberate act of faking, while -(으)ㄴ/는 것 같다 is the speaker\'s honest guess about reality. 자는 척해요 = "(he) is pretending to be asleep (but isn\'t)"; 자는 것 같아요 = "(he) seems to be asleep (I think he really is)." Note also the near-synonym 체하다, which is interchangeable (자는 체하다). Politeness lives entirely in the final 하다 ending (척해요 polite, 척한다/척해 casual), so the grammar fits any register. The most common learner mistake is using the plain present 는 척하다 for a finished action — saying 먹는 척했어요 when 먹은 척했어요 ("pretended to have already eaten") is meant — so always match the 는/-(으)ㄴ form to the tense, not just to the verb.',
      'Expresa fingir o aparentar algo: "fingir que / hacer como si uno hace o es algo". Se une a la forma descriptiva de un verbo o adjetivo, así que el alomorfo depende del tiempo y de la clase de palabra. Para una acción presente, usá 는 척하다 sobre cualquier raíz verbal sin importar el 받침 (먹다 → 먹는 척하다 "fingir que come", 자다 → 자는 척하다 "fingir que duerme"). Para un estado presente (adjetivo) o una acción completada/pasada, usá -(으)ㄴ 척하다: una raíz en vocal o en ㄹ toma -ㄴ (아프다 → 아픈 척하다 "fingir que está enfermo"; la ㄹ se cae: 알다 → 아는 척하다 "fingir que sabe"), mientras que una raíz en consonante toma -은 (먹다 → 먹은 척하다 "fingir que ya comió", 좋다 → 좋은 척하다 "fingir que es agradable/bueno"). Después 척하다 se conjuga normalmente: 척했어요, 척해요.\n\nUna confusión genuina es 척하다 vs. -(으)ㄴ/는 것 같다 ("parecer / dar la impresión de"). La diferencia está en la intención: 척하다 es un acto deliberado de fingir, mientras que -(으)ㄴ/는 것 같다 es la suposición honesta del hablante sobre la realidad. 자는 척해요 = "(él) está fingiendo que duerme (pero no duerme)"; 자는 것 같아요 = "(él) parece estar dormido (creo que de verdad lo está)". Fijate también en el casi sinónimo 체하다, que es intercambiable (자는 체하다). La cortesía vive enteramente en la terminación final 하다 (척해요 cortés, 척한다/척해 informal), así que la gramática encaja en cualquier registro. El error más común del estudiante es usar el presente simple 는 척하다 para una acción terminada —decir 먹는 척했어요 cuando se quiere decir 먹은 척했어요 ("fingió que ya había comido")—, así que siempre hacé coincidir la forma 는/-(으)ㄴ con el tiempo, no solo con el verbo.',
      'Exprime le fait de faire semblant ou de feindre : « faire semblant de / agir comme si l\'on fait ou est quelque chose ». Cela s\'attache à la forme descriptive d\'un verbe ou d\'un adjectif, donc l\'allomorphe dépend du temps et de la classe du mot. Pour une action au présent, utilise 는 척하다 sur n\'importe quel radical verbal, quel que soit le 받침 (먹다 → 먹는 척하다 « faire semblant de manger », 자다 → 자는 척하다 « faire semblant de dormir »). Pour un état présent (adjectif) ou une action achevée/passée, utilise -(으)ㄴ 척하다 : un radical en voyelle ou en ㄹ prend -ㄴ (아프다 → 아픈 척하다 « faire semblant d\'être malade » ; le ㄹ tombe : 알다 → 아는 척하다 « faire semblant de savoir »), tandis qu\'un radical en consonne prend -은 (먹다 → 먹은 척하다 « faire semblant d\'avoir mangé », 좋다 → 좋은 척하다 « faire semblant d\'être gentil/bon »). 척하다 se conjugue alors normalement : 척했어요, 척해요.\n\nUne véritable confusion possible est 척하다 contre -(으)ㄴ/는 것 같다 (« sembler / avoir l\'air »). La différence tient à l\'intention : 척하다 est un acte délibéré de feinte, tandis que -(으)ㄴ/는 것 같다 est la supposition honnête du locuteur sur la réalité. 자는 척해요 = « (il) fait semblant de dormir (mais ne dort pas) » ; 자는 것 같아요 = « (il) a l\'air de dormir (je pense qu\'il dort vraiment) ». Note aussi le quasi-synonyme 체하다, interchangeable (자는 체하다). La politesse réside entièrement dans la terminaison finale 하다 (척해요 poli, 척한다/척해 familier), donc cette grammaire convient à tous les registres. L\'erreur la plus fréquente des apprenants est d\'employer le présent simple 는 척하다 pour une action achevée — dire 먹는 척했어요 alors qu\'on veut dire 먹은 척했어요 (« a fait semblant d\'avoir déjà mangé ») — alors fais toujours correspondre la forme 는/-(으)ㄴ au temps, et pas seulement au verbe.',
      'Expressa fingir ou simular — "fingir que / agir como se alguém faz ou é algo". Liga-se à forma descritiva de um verbo ou adjetivo, então o alomorfe depende do tempo e da classe da palavra. Para uma ação no presente, use 는 척하다 em qualquer radical verbal, independentemente do 받침 (먹다 → 먹는 척하다 "fingir que come", 자다 → 자는 척하다 "fingir que dorme"). Para um estado presente (adjetivo) ou uma ação concluída/passada, use -(으)ㄴ 척하다: um radical em vogal ou em ㄹ recebe -ㄴ (아프다 → 아픈 척하다 "fingir que está doente"; o ㄹ cai: 알다 → 아는 척하다 "fingir que sabe"), enquanto um radical em consoante recebe -은 (먹다 → 먹은 척하다 "fingir que já comeu", 좋다 → 좋은 척하다 "fingir que é gentil/bom"). Então o próprio 척하다 se conjuga normalmente: 척했어요, 척해요.\n\nUma confusão genuína é 척하다 vs. -(으)ㄴ/는 것 같다 ("parecer / dar a impressão de"). A diferença está na intenção: 척하다 é um ato deliberado de fingimento, enquanto -(으)ㄴ/는 것 같다 é o palpite sincero do falante sobre a realidade. 자는 척해요 = "(ele) está fingindo que dorme (mas não está)"; 자는 것 같아요 = "(ele) parece estar dormindo (acho que está mesmo)". Observe também o quase sinônimo 체하다, que é intercambiável (자는 체하다). A polidez reside inteiramente na terminação final 하다 (척해요 polido, 척한다/척해 informal), então essa gramática se encaixa em qualquer registro. O erro mais comum dos aprendizes é usar o presente simples 는 척하다 para uma ação concluída — dizer 먹는 척했어요 quando se quer dizer 먹은 척했어요 ("fingiu que já tinha comido") — então sempre faça a forma 는/-(으)ㄴ corresponder ao tempo, não apenas ao verbo.',
      'แสดงการแกล้งทำหรือเสแสร้ง — "แกล้งทำเป็น / ทำราวกับว่า (ตน) ทำหรือเป็นอะไรบางอย่าง" มันเกาะกับรูปบรรยายของคำกริยาหรือคำคุณศัพท์ ดังนั้นรูปแปร (allomorph) จึงขึ้นอยู่กับกาลและชนิดของคำ สำหรับการกระทำในปัจจุบัน ให้ใช้ 는 척하다 กับรากกริยาใด ๆ ไม่ว่าจะมี 받침 หรือไม่ (먹다 → 먹는 척하다 "แกล้งทำเป็นกิน", 자다 → 자는 척하다 "แกล้งทำเป็นนอน") สำหรับสภาวะในปัจจุบัน (คำคุณศัพท์) หรือการกระทำที่เสร็จสิ้น/อดีต ให้ใช้ -(으)ㄴ 척하다: รากที่ลงท้ายด้วยสระหรือ ㄹ จะรับ -ㄴ (아프다 → 아픈 척하다 "แกล้งทำเป็นป่วย"; ㄹ หลุดออก: 알다 → 아는 척하다 "แกล้งทำเป็นรู้") ในขณะที่รากที่ลงท้ายด้วยพยัญชนะจะรับ -은 (먹다 → 먹은 척하다 "แกล้งทำเป็นว่ากินแล้ว", 좋다 → 좋은 척하다 "แกล้งทำเป็นใจดี/ดี") จากนั้นตัว 척하다 เองก็ผันตามปกติ: 척했어요, 척해요\n\nจุดที่สับสนกันจริง ๆ คือ 척하다 กับ -(으)ㄴ/는 것 같다 ("ดูเหมือนว่า / ดูราวกับ") ความแตกต่างอยู่ที่เจตนา: 척하다 คือการแกล้งทำอย่างจงใจ ส่วน -(으)ㄴ/는 것 같다 คือการคาดเดาตามจริงของผู้พูดเกี่ยวกับความเป็นจริง 자는 척해요 = "(เขา) กำลังแกล้งทำเป็นหลับ (แต่จริง ๆ ไม่ได้หลับ)"; 자는 것 같아요 = "(เขา) ดูเหมือนกำลังหลับอยู่ (ฉันคิดว่าเขาหลับจริง ๆ)" สังเกตคำที่เกือบเป็นไวพจน์อย่าง 체하다 ด้วย ซึ่งใช้แทนกันได้ (자는 체하다) ความสุภาพอยู่ที่ส่วนลงท้าย 하다 ทั้งหมด (척해요 สุภาพ, 척한다/척해 กันเอง) ดังนั้นไวยากรณ์นี้จึงเข้าได้กับทุกระดับภาษา ข้อผิดพลาดที่ผู้เรียนทำบ่อยที่สุดคือการใช้ปัจจุบันธรรมดา 는 척하다 กับการกระทำที่จบไปแล้ว — พูดว่า 먹는 척했어요 ทั้งที่ต้องการสื่อ 먹은 척했어요 ("แกล้งทำเป็นว่ากินไปแล้ว") — ดังนั้นจงจับคู่รูป 는/-(으)ㄴ ให้ตรงกับกาลเสมอ ไม่ใช่แค่ตรงกับคำกริยา',
      'Menyatakan tindakan berpura-pura atau berlagak — "berpura-pura / bertingkah seolah-olah (seseorang) melakukan atau adalah sesuatu." Ia melekat pada bentuk deskriptif dari kata kerja atau kata sifat, jadi alomorfnya bergantung pada kala dan kelas kata. Untuk tindakan masa kini, gunakan 는 척하다 pada batang kata kerja apa pun tanpa memandang 받침 (먹다 → 먹는 척하다 "berpura-pura makan," 자다 → 자는 척하다 "berpura-pura tidur"). Untuk keadaan masa kini (kata sifat) atau tindakan yang sudah selesai/lampau, gunakan -(으)ㄴ 척하다: batang berakhiran vokal atau ㄹ mengambil -ㄴ (아프다 → 아픈 척하다 "berpura-pura sakit"; ㄹ luruh: 알다 → 아는 척하다 "berpura-pura tahu"), sedangkan batang berakhiran konsonan mengambil -은 (먹다 → 먹은 척하다 "berpura-pura sudah makan," 좋다 → 좋은 척하다 "berpura-pura baik/ramah"). Setelah itu 척하다 sendiri dikonjugasikan seperti biasa: 척했어요, 척해요.\n\nSumber kebingungan yang nyata adalah 척하다 vs. -(으)ㄴ/는 것 같다 ("tampaknya / terlihat seperti"). Perbedaannya ada pada niat: 척하다 adalah tindakan berpura-pura yang disengaja, sedangkan -(으)ㄴ/는 것 같다 adalah dugaan jujur penutur tentang kenyataan. 자는 척해요 = "(dia) sedang berpura-pura tidur (padahal tidak)"; 자는 것 같아요 = "(dia) sepertinya sedang tidur (saya rasa dia benar-benar tidur)". Perhatikan juga padanan dekat 체하다, yang dapat dipertukarkan (자는 체하다). Kesopanan sepenuhnya terletak pada akhiran 하다 di akhir (척해요 sopan, 척한다/척해 santai), jadi tata bahasa ini cocok untuk ragam apa pun. Kesalahan pembelajar yang paling umum adalah memakai bentuk kini sederhana 는 척하다 untuk tindakan yang sudah selesai — mengatakan 먹는 척했어요 padahal yang dimaksud 먹은 척했어요 ("berpura-pura sudah makan") — jadi selalu cocokkan bentuk 는/-(으)ㄴ dengan kala, bukan sekadar dengan kata kerjanya.',
      'Diễn tả việc giả vờ hoặc làm bộ — "giả vờ / làm như thể (ai đó) làm hoặc là điều gì đó." Nó gắn vào dạng mô tả của động từ hay tính từ, nên biến thể (allomorph) phụ thuộc vào thì và loại từ. Đối với hành động ở hiện tại, dùng 는 척하다 với bất kỳ thân động từ nào bất kể có 받침 hay không (먹다 → 먹는 척하다 "giả vờ ăn," 자다 → 자는 척하다 "giả vờ ngủ"). Đối với trạng thái hiện tại (tính từ) hoặc hành động đã hoàn tất/quá khứ, dùng -(으)ㄴ 척하다: thân kết thúc bằng nguyên âm hoặc ㄹ lấy -ㄴ (아프다 → 아픈 척하다 "giả vờ ốm"; ㄹ rụng đi: 알다 → 아는 척하다 "giả vờ biết"), còn thân kết thúc bằng phụ âm lấy -은 (먹다 → 먹은 척하다 "giả vờ đã ăn," 좋다 → 좋은 척하다 "giả vờ tốt bụng/tử tế"). Sau đó bản thân 척하다 chia bình thường: 척했어요, 척해요.\n\nMột điểm dễ nhầm thật sự là 척하다 với -(으)ㄴ/는 것 같다 ("có vẻ / trông như"). Khác biệt nằm ở chủ ý: 척하다 là hành động cố tình giả tạo, còn -(으)ㄴ/는 것 같다 là phỏng đoán thành thật của người nói về thực tế. 자는 척해요 = "(anh ấy) đang giả vờ ngủ (nhưng thực ra không ngủ)"; 자는 것 같아요 = "(anh ấy) có vẻ đang ngủ (tôi nghĩ anh ấy thực sự đang ngủ)". Cũng lưu ý từ gần như đồng nghĩa 체하다, có thể dùng thay thế cho nhau (자는 체하다). Tính lịch sự nằm hoàn toàn ở đuôi 하다 cuối cùng (척해요 lịch sự, 척한다/척해 thân mật), nên ngữ pháp này hợp với mọi ngữ vực. Lỗi thường gặp nhất của người học là dùng hiện tại đơn 는 척하다 cho một hành động đã xong — nói 먹는 척했어요 trong khi ý muốn là 먹은 척했어요 ("giả vờ đã ăn rồi") — vì vậy luôn khớp dạng 는/-(으)ㄴ với thì, chứ không chỉ với động từ.',
      'ふりをすること、見せかけることを表します——「〜するふりをする／〜であるかのように振る舞う」。動詞や形容詞の連体形に付くため、異形態（allomorph）は時制と品詞によって変わります。現在の動作には、받침の有無にかかわらずどの動詞語幹にも 는 척하다 を使います（먹다 → 먹는 척하다「食べるふりをする」、자다 → 자는 척하다「寝るふりをする」）。現在の状態（形容詞）や完了した・過去の動作には -(으)ㄴ 척하다 を使います。母音語幹や ㄹ 語幹は -ㄴ を取り（아프다 → 아픈 척하다「具合が悪いふりをする」、ㄹ は脱落：알다 → 아는 척하다「知っているふりをする」）、子音語幹は -은 を取ります（먹다 → 먹은 척하다「もう食べたふりをする」、좋다 → 좋은 척하다「いい人のふりをする／良いふりをする」）。そのあと 척하다 自体は普通に活用します：척했어요、척해요。\n\n本当に紛らわしいのは 척하다 と -(으)ㄴ/는 것 같다（「〜のようだ／〜に見える」）です。違いは意図にあります。척하다 は意図的に装う行為であり、-(으)ㄴ/는 것 같다 は現実についての話し手の正直な推測です。자는 척해요 =「（彼は）寝たふりをしている（実際は寝ていない）」、자는 것 같아요 =「（彼は）寝ているようだ（本当に寝ていると思う）」。さらに、ほぼ同義で置き換え可能な 체하다 にも注目してください（자는 체하다）。丁寧さはすべて末尾の 하다 の語尾に宿るので（척해요 は丁寧、척한다/척해 はくだけた言い方）、この文法はどの語調にも合います。学習者に最も多い間違いは、完了した動作に単純現在の 는 척하다 を使うことです——먹은 척했어요（「もう食べたふりをした」）と言うべきところを 먹는 척했어요 と言ってしまうのです——ですから 는/-(으)ㄴ の形は、動詞だけでなく必ず時制に合わせてください。',
    ),
  '-게 하다': L(
      '-게 하다 is the flexible "periphrastic" causative — it makes someone do something or lets/allows them to. You build it by attaching -게 to a plain verb stem (no allomorph juggling: the form is always -게 regardless of 받침) and then conjugating 하다 for tense and politeness. So a vowel stem like 가다 becomes 가게 하다 (엄마가 동생을 학교에 가게 했어요 "Mom made my brother go to school"), and a consonant stem like 먹다 becomes 먹게 하다 (선생님이 학생들에게 책을 읽게 했어요 "The teacher had the students read the book"). The person being caused is usually marked with 을/를, or sometimes 에게/한테 for a softer "let/allow" feel.\n\nThe neighbour to watch is the short-form causative built into specific verbs, like 먹이다 ("feed") vs. 먹게 하다. Compare 아이에게 밥을 먹였어요 "I fed the child (directly)" with 아이가 밥을 먹게 했어요 "I made the child eat (themselves)" — in the -게 하다 version it\'s the causee, not the causer, who actually performs the action, so it conveys indirect causation and covers verbs that have no lexical causative. -게 하다 works in all registers; just match 하다 to your level (했어요 polite, 했다 plain). The most common learner mistake is over-attaching: never add -을/를 or tense to -게 itself (먹게 하다, not 먹을게 하다), and remember spoken Korean often drops to -게 해 in casual speech.',
      '-게 하다 es el causativo "perifrástico" flexible: hace que alguien haga algo o le permite/deja hacerlo. Lo armás pegando -게 a la raíz verbal simple (sin malabares de alomorfos: la forma siempre es -게 sin importar el 받침) y después conjugás 하다 para el tiempo y el nivel de cortesía. Así, una raíz vocálica como 가다 se vuelve 가게 하다 (엄마가 동생을 학교에 가게 했어요 "Mamá hizo que mi hermano fuera a la escuela"), y una raíz con consonante como 먹다 se vuelve 먹게 하다 (선생님이 학생들에게 책을 읽게 했어요 "El profesor hizo que los estudiantes leyeran el libro"). A la persona a la que se le causa la acción se la marca normalmente con 을/를, o a veces con 에게/한테 para un matiz más suave de "dejar/permitir".\n\nEl vecino que tenés que vigilar es el causativo de forma corta incorporado en ciertos verbos, como 먹이다 ("dar de comer") frente a 먹게 하다. Compará 아이에게 밥을 먹였어요 "Le di de comer al niño (directamente)" con 아이가 밥을 먹게 했어요 "Hice que el niño comiera (por sí mismo)": en la versión con -게 하다 es el causado, no quien causa, el que de verdad realiza la acción, así que transmite una causación indirecta y cubre verbos que no tienen causativo léxico. -게 하다 funciona en todos los registros; solo ajustá 하다 a tu nivel (했어요 cortés, 했다 llano). El error más común de quien aprende es pegar de más: nunca le agregues -을/를 ni tiempo al propio -게 (먹게 하다, no 먹을게 하다), y acordate de que el coreano hablado a menudo se reduce a -게 해 en el registro casual.',
      '-게 하다 est le causatif « périphrastique » souple : il fait faire quelque chose à quelqu\'un ou le lui permet/l\'y autorise. Tu le construis en attachant -게 à un radical verbal simple (pas de jonglage d\'allomorphes : la forme est toujours -게 quel que soit le 받침), puis en conjuguant 하다 pour le temps et la politesse. Ainsi un radical en voyelle comme 가다 devient 가게 하다 (엄마가 동생을 학교에 가게 했어요 « Maman a fait aller mon petit frère à l\'école »), et un radical en consonne comme 먹다 devient 먹게 하다 (선생님이 학생들에게 책을 읽게 했어요 « Le professeur a fait lire le livre aux élèves »). La personne à qui l\'on fait faire l\'action est généralement marquée par 을/를, ou parfois par 에게/한테 pour une nuance plus douce de « laisser/permettre ».\n\nLe voisin à surveiller, c\'est le causatif de forme courte intégré à certains verbes, comme 먹이다 (« nourrir ») face à 먹게 하다. Compare 아이에게 밥을 먹였어요 « J\'ai nourri l\'enfant (directement) » avec 아이가 밥을 먹게 했어요 « J\'ai fait manger l\'enfant (lui-même) » : dans la version en -게 하다, c\'est le causé, et non le causateur, qui accomplit réellement l\'action, ce qui exprime une causation indirecte et couvre les verbes sans causatif lexical. -게 하다 fonctionne dans tous les registres ; il suffit d\'accorder 하다 à ton niveau (했어요 poli, 했다 neutre). L\'erreur la plus fréquente des apprenants, c\'est d\'en rajouter : n\'ajoute jamais -을/를 ni le temps à -게 lui-même (먹게 하다, et non 먹을게 하다), et souviens-toi que le coréen parlé se réduit souvent à -게 해 dans le registre familier.',
      '-게 하다 é o causativo "perifrástico" flexível: ele faz alguém fazer algo ou deixa/permite que faça. Você o monta colando -게 a uma raiz verbal simples (sem malabarismo de alomorfes: a forma é sempre -게 independentemente do 받침) e depois conjuga 하다 para o tempo e o nível de polidez. Assim, uma raiz vocálica como 가다 vira 가게 하다 (엄마가 동생을 학교에 가게 했어요 "A mãe fez meu irmão ir à escola"), e uma raiz com consoante como 먹다 vira 먹게 하다 (선생님이 학생들에게 책을 읽게 했어요 "O professor fez os alunos lerem o livro"). A pessoa a quem se causa a ação costuma ser marcada com 을/를, ou às vezes com 에게/한테 para um tom mais suave de "deixar/permitir".\n\nO vizinho a ficar de olho é o causativo de forma curta embutido em certos verbos, como 먹이다 ("alimentar") em comparação com 먹게 하다. Compare 아이에게 밥을 먹였어요 "Eu alimentei a criança (diretamente)" com 아이가 밥을 먹게 했어요 "Eu fiz a criança comer (sozinha)": na versão com -게 하다 é quem sofre a causa, e não quem causa, que de fato realiza a ação, então ela transmite causação indireta e cobre verbos que não têm causativo lexical. -게 하다 funciona em todos os registros; é só ajustar 하다 ao seu nível (했어요 polido, 했다 simples). O erro mais comum de quem está aprendendo é colar coisas demais: nunca adicione -을/를 nem tempo ao próprio -게 (먹게 하다, não 먹을게 하다), e lembre-se de que o coreano falado muitas vezes se reduz a -게 해 na fala casual.',
      '-게 하다 คือรูปการก (causative) แบบ "อ้อม" ที่ยืดหยุ่น ใช้บอกว่าทำให้ใครทำอะไร หรือยอม/อนุญาตให้ทำ คุณสร้างมันโดยเติม -게 เข้ากับรากกริยารูปธรรมดา (ไม่ต้องสลับ allomorph ให้ยุ่งยาก: รูปจะเป็น -게 เสมอไม่ว่าจะมี 받침 หรือไม่) แล้วผัน 하다 ตามกาลและระดับความสุภาพ ดังนั้นรากที่ลงท้ายด้วยสระอย่าง 가다 จะกลายเป็น 가게 하다 (엄마가 동생을 학교에 가게 했어요 "แม่ทำให้น้องไปโรงเรียน") และรากที่ลงท้ายด้วยพยัญชนะอย่าง 먹다 จะกลายเป็น 먹게 하다 (선생님이 학생들에게 책을 읽게 했어요 "ครูให้นักเรียนอ่านหนังสือ") คนที่ถูกทำให้ทำสิ่งนั้นมักจะกำกับด้วย 을/를 หรือบางครั้งใช้ 에게/한테 เพื่อให้รู้สึกนุ่มนวลแบบ "ยอม/อนุญาต" มากขึ้น\n\nตัวที่ต้องระวังคือการกรูปสั้นที่ฝังอยู่ในกริยาบางคำ เช่น 먹이다 ("ป้อน/ให้กิน") เทียบกับ 먹게 하다 ลองเปรียบ 아이에게 밥을 먹였어요 "ฉันป้อนข้าวให้เด็ก (โดยตรง)" กับ 아이가 밥을 먹게 했어요 "ฉันทำให้เด็กกินข้าว (ด้วยตัวเอง)" — ในรูป -게 하다 คนที่ลงมือทำจริงคือผู้ถูกกระทำ ไม่ใช่ผู้ก่อให้เกิด มันจึงสื่อถึงการกระทำแบบอ้อม และครอบคลุมกริยาที่ไม่มีรูปการกเฉพาะของตัวเอง -게 하다 ใช้ได้ในทุกระดับภาษา เพียงปรับ 하다 ให้ตรงกับระดับของคุณ (했어요 สุภาพ, 했다 ธรรมดา) ข้อผิดพลาดที่ผู้เรียนเจอบ่อยที่สุดคือเติมเกิน: อย่าเติม -을/를 หรือกาลเข้ากับตัว -게 เอง (먹게 하다 ไม่ใช่ 먹을게 하다) และจำไว้ว่าภาษาเกาหลีพูดมักลดรูปเหลือ -게 해 ในการพูดแบบลำลอง',
      '-게 하다 adalah kausatif "periphrastik" yang fleksibel — ia membuat seseorang melakukan sesuatu atau membiarkan/mengizinkannya. Kamu membentuknya dengan menempelkan -게 pada akar kata kerja polos (tanpa repot mengatur alomorf: bentuknya selalu -게 terlepas dari ada tidaknya 받침), lalu mengonjugasikan 하다 untuk kala dan tingkat kesopanan. Jadi, akar berakhiran vokal seperti 가다 menjadi 가게 하다 (엄마가 동생을 학교에 가게 했어요 "Ibu menyuruh adikku pergi ke sekolah"), dan akar berakhiran konsonan seperti 먹다 menjadi 먹게 하다 (선생님이 학생들에게 책을 읽게 했어요 "Guru menyuruh para murid membaca buku itu"). Orang yang dikenai perbuatan biasanya ditandai dengan 을/를, atau kadang 에게/한테 untuk nuansa "membiarkan/mengizinkan" yang lebih lembut.\n\nTetangga yang perlu diwaspadai adalah kausatif bentuk pendek yang melekat pada kata kerja tertentu, seperti 먹이다 ("menyuapi") dibandingkan dengan 먹게 하다. Bandingkan 아이에게 밥을 먹였어요 "Aku menyuapi anak itu (secara langsung)" dengan 아이가 밥을 먹게 했어요 "Aku membuat anak itu makan (sendiri)" — dalam versi -게 하다, yang benar-benar melakukan perbuatan adalah pihak yang dikenai, bukan pihak yang menyebabkan, sehingga ia menyampaikan kausasi tidak langsung dan mencakup kata kerja yang tidak punya kausatif leksikal. -게 하다 berfungsi di semua ragam bahasa; cukup sesuaikan 하다 dengan tingkatmu (했어요 sopan, 했다 polos). Kesalahan paling umum pembelajar adalah menempelkan terlalu banyak: jangan pernah menambahkan -을/를 atau kala pada -게 itu sendiri (먹게 하다, bukan 먹을게 하다), dan ingat bahwa bahasa Korea lisan sering menyusut menjadi -게 해 dalam percakapan santai.',
      '-게 하다 là dạng sai khiến "diễn đạt vòng" linh hoạt — nó khiến ai đó làm điều gì hoặc để/cho phép họ làm. Bạn tạo nó bằng cách gắn -게 vào gốc động từ ở dạng đơn (không phải xoay xở với biến thể: dạng luôn là -게 bất kể có 받침 hay không), rồi chia 하다 theo thì và mức độ lịch sự. Vậy nên gốc kết thúc bằng nguyên âm như 가다 sẽ thành 가게 하다 (엄마가 동생을 학교에 가게 했어요 "Mẹ bắt em tôi đi học"), còn gốc kết thúc bằng phụ âm như 먹다 sẽ thành 먹게 하다 (선생님이 학생들에게 책을 읽게 했어요 "Cô giáo cho học sinh đọc cuốn sách"). Người bị khiến thực hiện hành động thường được đánh dấu bằng 을/를, hoặc đôi khi bằng 에게/한테 để mang sắc thái "để/cho phép" mềm mại hơn.\n\nCái cần để mắt là dạng sai khiến rút gọn được tích hợp sẵn trong một số động từ nhất định, như 먹이다 ("cho ăn") so với 먹게 하다. Hãy so sánh 아이에게 밥을 먹였어요 "Tôi cho đứa bé ăn (trực tiếp)" với 아이가 밥을 먹게 했어요 "Tôi bắt đứa bé tự ăn" — ở dạng -게 하다, người thực sự thực hiện hành động là người bị sai khiến chứ không phải người sai khiến, nên nó diễn đạt sự sai khiến gián tiếp và bao phủ cả những động từ không có dạng sai khiến từ vựng. -게 하다 dùng được ở mọi văn phong; chỉ cần chỉnh 하다 cho khớp với mức của bạn (했어요 lịch sự, 했다 dạng trống). Lỗi phổ biến nhất của người học là gắn thừa: đừng bao giờ thêm -을/를 hay thì vào chính phần -게 (먹게 하다, không phải 먹을게 하다), và nhớ rằng tiếng Hàn nói thường rút gọn thành -게 해 trong lời nói thân mật.',
      '-게 하다 は柔軟な「迂言的」使役で、誰かに何かをさせる、あるいは〜することを許す・させてあげるという意味を表します。作り方は、動詞の語幹そのままに -게 を付け（異形態の使い分けは不要で、받침 の有無にかかわらず常に -게 です）、そのあとに 하다 を時制と丁寧さに合わせて活用させます。ですから 가다 のような母音語幹は 가게 하다 となり（엄마가 동생을 학교에 가게 했어요「お母さんが弟を学校に行かせた」）、먹다 のような子音語幹は 먹게 하다 となります（선생님이 학생들에게 책을 읽게 했어요「先生が生徒たちに本を読ませた」）。使役を受ける人は普通 을/를 で示しますが、「〜させてあげる・許す」という柔らかいニュアンスを出すときには 에게/한테 を使うこともあります。\n\n注意したい隣人は、特定の動詞に組み込まれた短形使役で、たとえば 먹이다（「食べさせる・餌をやる」）と 먹게 하다 の対比です。아이에게 밥을 먹였어요「子どもにご飯を食べさせた（直接）」と 아이가 밥을 먹게 했어요「子どもに（自分で）ご飯を食べさせた」を比べてみましょう。-게 하다 のほうでは、実際に動作を行うのは使役を引き起こす側ではなく使役を受ける側なので、間接的な使役を表し、語彙的な使役形を持たない動詞もカバーできます。-게 하다 はあらゆる語体で使えます。あとは 하다 を自分のレベルに合わせるだけです（했어요 は丁寧、했다 はぞんざい）。学習者に最も多い間違いは付けすぎることです。-게 そのものに -을/를 や時制を決して加えないでください（먹게 하다 であって 먹을게 하다 ではありません）。そして話し言葉ではカジュアルな場面で -게 해 に縮まることが多いことも覚えておきましょう。',
    ),
  '-(으)ㄴ/는 대로': L(
      '-(으)ㄴ/는 대로 attaches to a verb stem and means "in accordance with / just like / exactly as," or — depending on tense — "right after." With a present-tense verb it takes 는 대로 regardless of 받침 (가다 → 가는 대로 "as you go," 먹다 → 먹는 대로 "as you eat / right after eating"). With a past-tense verb it follows the -(으)ㄴ pattern: a vowel or ㄹ stem takes -ㄴ 대로 (보다 → 본 대로 "just as I saw it"), and a consonant stem takes -은 대로 (받다 → 받은 대로 "just as I received it"). Note that 듣다 is a ㄷ-irregular: the ㄷ becomes ㄹ and it adds -은, giving 들은 대로 "exactly as I heard." It can also follow a noun directly (사실대로 "as it is/truthfully," 마음대로 "as one pleases," 약속대로 "as promised"), where it means "according to N."\n\nThe closest neighbour to watch is -자마자 ("as soon as"). Both can render "right after," but 는 대로 carries a sense of doing the second action without delay and often implies intention or a plan, while -자마자 is purely about immediate temporal sequence and works for unplanned events too. 도착하는 대로 연락할게요 "I\'ll contact you as soon as I arrive" (I intend to, the moment I get there) vs. 도착하자마자 비가 왔어요 "as soon as I arrived, it rained" — here 는 대로 sounds odd because nobody planned the rain. Both forms are register-neutral; politeness lives in the final ending (연락할게요 vs. 연락하겠습니다). The most common learner mistake is using past-tense -(으)ㄴ 대로 for a future "as soon as" meaning; for "right after," always keep the present 는 대로 (가는 대로, not 간 대로). Remember that past 본 대로/들은 대로 means "exactly as (I saw/heard)," the manner sense, not the timing sense.',
      '-(으)ㄴ/는 대로 se une a la raíz de un verbo y significa "de acuerdo con / tal como / exactamente como", o —según el tiempo verbal— "justo después de". Con un verbo en presente toma 는 대로 sin importar el 받침 (가다 → 가는 대로 "a medida que vas", 먹다 → 먹는 대로 "a medida que comés / justo después de comer"). Con un verbo en pasado sigue el patrón -(으)ㄴ: una raíz terminada en vocal o en ㄹ toma -ㄴ 대로 (보다 → 본 대로 "tal como lo vi"), y una raíz terminada en consonante toma -은 대로 (받다 → 받은 대로 "tal como lo recibí"). Tené en cuenta que 듣다 es un verbo irregular en ㄷ: la ㄷ se vuelve ㄹ y agrega -은, dando 들은 대로 "exactamente como lo escuché". También puede ir directamente después de un sustantivo (사실대로 "tal como es/con la verdad", 마음대로 "como a uno se le antoja", 약속대로 "como se prometió"), donde significa "según N".\n\nEl vecino más cercano que tenés que vigilar es -자마자 ("apenas / en cuanto"). Ambos pueden traducir "justo después", pero 는 대로 lleva un sentido de hacer la segunda acción sin demora y a menudo implica intención o un plan, mientras que -자마자 trata puramente de la secuencia temporal inmediata y también funciona para hechos no planeados. 도착하는 대로 연락할게요 "te aviso apenas llegue" (tengo la intención de hacerlo, en el momento en que llegue) frente a 도착하자마자 비가 왔어요 "apenas llegué, empezó a llover" —acá 는 대로 suena raro porque nadie planeó la lluvia. Ambas formas son neutras en cuanto al registro; la cortesía vive en la terminación final (연락할게요 vs. 연락하겠습니다). El error más común de quien aprende es usar el pasado -(으)ㄴ 대로 para un sentido futuro de "apenas"; para "justo después", mantené siempre el presente 는 대로 (가는 대로, no 간 대로). Acordate de que el pasado 본 대로/들은 대로 significa "exactamente como (lo vi/escuché)", el sentido de manera, no el de tiempo.',
      '-(으)ㄴ/는 대로 s\'attache à un radical verbal et signifie « conformément à / tout comme / exactement comme », ou — selon le temps — « juste après ». Avec un verbe au présent, il prend 는 대로 quel que soit le 받침 (가다 → 가는 대로 « à mesure que tu vas », 먹다 → 먹는 대로 « à mesure que tu manges / juste après avoir mangé »). Avec un verbe au passé, il suit le schéma -(으)ㄴ : un radical en voyelle ou en ㄹ prend -ㄴ 대로 (보다 → 본 대로 « tout comme je l\'ai vu »), et un radical en consonne prend -은 대로 (받다 → 받은 대로 « tout comme je l\'ai reçu »). Note que 듣다 est un verbe irrégulier en ㄷ : le ㄷ devient ㄹ et il ajoute -은, donnant 들은 대로 « exactement comme je l\'ai entendu ». Il peut aussi suivre directement un nom (사실대로 « tel quel / en toute vérité », 마음대로 « comme on veut », 약속대로 « comme promis »), où il signifie « selon N ».\n\nLe voisin le plus proche à surveiller est -자마자 (« dès que »). Les deux peuvent rendre « juste après », mais 는 대로 comporte l\'idée de faire la seconde action sans délai et implique souvent une intention ou un plan, tandis que -자마자 concerne purement la séquence temporelle immédiate et fonctionne aussi pour des événements imprévus. 도착하는 대로 연락할게요 « je te contacte dès que j\'arrive » (j\'en ai l\'intention, au moment même où j\'arrive) contre 도착하자마자 비가 왔어요 « dès que je suis arrivé, il a plu » — ici 는 대로 sonne bizarre parce que personne n\'a prévu la pluie. Les deux formes sont neutres en registre ; la politesse réside dans la terminaison finale (연락할게요 vs 연락하겠습니다). L\'erreur la plus fréquente chez l\'apprenant est d\'utiliser le passé -(으)ㄴ 대로 pour un sens futur de « dès que » ; pour « juste après », garde toujours le présent 는 대로 (가는 대로, et non 간 대로). Souviens-toi que le passé 본 대로/들은 대로 signifie « exactement comme (je l\'ai vu/entendu) », le sens de manière, et non celui de moment.',
      '-(으)ㄴ/는 대로 se liga a uma raiz verbal e significa "de acordo com / assim como / exatamente como", ou — dependendo do tempo verbal — "logo depois de". Com um verbo no presente, ele leva 는 대로 independentemente do 받침 (가다 → 가는 대로 "à medida que você vai", 먹다 → 먹는 대로 "à medida que você come / logo depois de comer"). Com um verbo no passado, ele segue o padrão -(으)ㄴ: uma raiz terminada em vogal ou em ㄹ leva -ㄴ 대로 (보다 → 본 대로 "exatamente como eu vi"), e uma raiz terminada em consoante leva -은 대로 (받다 → 받은 대로 "exatamente como eu recebi"). Observe que 듣다 é um verbo irregular em ㄷ: o ㄷ vira ㄹ e ele acrescenta -은, resultando em 들은 대로 "exatamente como eu ouvi". Ele também pode vir diretamente após um substantivo (사실대로 "tal como é / com a verdade", 마음대로 "como se quer", 약속대로 "conforme prometido"), onde significa "de acordo com N".\n\nO vizinho mais próximo a observar é -자마자 ("assim que"). Ambos podem traduzir "logo depois", mas 는 대로 carrega o sentido de fazer a segunda ação sem demora e muitas vezes implica intenção ou um plano, enquanto -자마자 trata puramente da sequência temporal imediata e funciona também para eventos não planejados. 도착하는 대로 연락할게요 "eu te aviso assim que chegar" (tenho a intenção de fazê-lo, no momento em que chegar) versus 도착하자마자 비가 왔어요 "assim que cheguei, começou a chover" — aqui 는 대로 soa estranho porque ninguém planejou a chuva. Ambas as formas são neutras quanto ao registro; a cortesia mora na terminação final (연락할게요 vs. 연락하겠습니다). O erro mais comum de quem aprende é usar o passado -(으)ㄴ 대로 para um sentido futuro de "assim que"; para "logo depois", mantenha sempre o presente 는 대로 (가는 대로, não 간 대로). Lembre-se de que o passado 본 대로/들은 대로 significa "exatamente como (eu vi/ouvi)", o sentido de modo, não o de tempo.',
      '-(으)ㄴ/는 대로 เติมท้ายรากคำกริยา และมีความหมายว่า "ตามที่ / เหมือนกับ / ตรงตามที่" หรือ — ขึ้นอยู่กับกาล — "ทันทีหลังจาก" เมื่อใช้กับกริยาในกาลปัจจุบัน จะใช้ 는 대로 ไม่ว่าจะมี 받침 หรือไม่ (가다 → 가는 대로 "ขณะที่ไป", 먹다 → 먹는 대로 "ขณะที่กิน / ทันทีหลังจากกิน") เมื่อใช้กับกริยาในกาลอดีต จะตามรูปแบบ -(으)ㄴ: รากที่ลงท้ายด้วยสระหรือ ㄹ ใช้ -ㄴ 대로 (보다 → 본 대로 "ตรงตามที่ฉันเห็น") และรากที่ลงท้ายด้วยพยัญชนะใช้ -은 대로 (받다 → 받은 대로 "ตรงตามที่ฉันได้รับ") โปรดสังเกตว่า 듣다 เป็นกริยาผันไม่ปกติแบบ ㄷ: ㄷ จะเปลี่ยนเป็น ㄹ และเติม -은 กลายเป็น 들은 대로 "ตรงตามที่ฉันได้ยิน" นอกจากนี้ยังสามารถตามหลังคำนามได้โดยตรง (사실대로 "ตามความเป็นจริง / ตามที่เป็น", 마음대로 "ตามใจชอบ", 약속대로 "ตามที่สัญญาไว้") ซึ่งในกรณีนี้มีความหมายว่า "ตาม N"\n\nคำใกล้เคียงที่ต้องระวังที่สุดคือ -자마자 ("ทันทีที่") ทั้งสองรูปสามารถแปลว่า "ทันทีหลังจาก" ได้ แต่ 는 대로 มีนัยของการทำสิ่งที่สองโดยไม่ชักช้า และมักสื่อถึงความตั้งใจหรือแผนการ ในขณะที่ -자마자 พูดถึงลำดับเวลาที่เกิดขึ้นทันทีล้วน ๆ และใช้กับเหตุการณ์ที่ไม่ได้วางแผนไว้ได้ด้วย 도착하는 대로 연락할게요 "ฉันจะติดต่อไปทันทีที่ฉันไปถึง" (ฉันตั้งใจจะทำ ในวินาทีที่ไปถึง) เทียบกับ 도착하자마자 비가 왔어요 "พอฉันไปถึง ฝนก็ตก" — ในที่นี้ 는 대로 ฟังดูแปลก เพราะไม่มีใครวางแผนให้ฝนตก ทั้งสองรูปเป็นกลางในแง่ระดับภาษา ความสุภาพอยู่ที่คำลงท้าย (연락할게요 เทียบกับ 연락하겠습니다) ข้อผิดพลาดที่ผู้เรียนพบบ่อยที่สุดคือการใช้รูปอดีต -(으)ㄴ 대로 เพื่อสื่อความหมายอนาคตว่า "ทันทีที่" สำหรับ "ทันทีหลังจาก" ให้คงรูปปัจจุบัน 는 대로 ไว้เสมอ (가는 대로 ไม่ใช่ 간 대로) จงจำไว้ว่ารูปอดีต 본 대로/들은 대로 หมายถึง "ตรงตามที่ (ฉันเห็น/ได้ยิน)" ซึ่งเป็นความหมายในแง่ลักษณะวิธี ไม่ใช่ในแง่เวลา',
      '-(으)ㄴ/는 대로 menempel pada akar kata kerja dan berarti "sesuai dengan / persis seperti / tepat seperti", atau — tergantung kala — "tepat setelah". Dengan kata kerja kala kini, ia memakai 는 대로 tanpa memandang 받침 (가다 → 가는 대로 "sambil kamu pergi", 먹다 → 먹는 대로 "sambil kamu makan / tepat setelah makan"). Dengan kata kerja kala lampau, ia mengikuti pola -(으)ㄴ: akar yang berakhir vokal atau ㄹ memakai -ㄴ 대로 (보다 → 본 대로 "persis seperti yang saya lihat"), dan akar yang berakhir konsonan memakai -은 대로 (받다 → 받은 대로 "persis seperti yang saya terima"). Perhatikan bahwa 듣다 adalah kata kerja tak beraturan ㄷ: ㄷ berubah menjadi ㄹ dan menambahkan -은, sehingga menjadi 들은 대로 "persis seperti yang saya dengar". Ia juga bisa langsung mengikuti kata benda (사실대로 "apa adanya / dengan jujur", 마음대로 "sesuka hati", 약속대로 "sesuai janji"), yang berarti "menurut N".\n\nTetangga terdekat yang perlu diwaspadai adalah -자마자 ("segera setelah"). Keduanya bisa menyampaikan makna "tepat setelah", tetapi 는 대로 mengandung kesan melakukan tindakan kedua tanpa menunda dan sering menyiratkan niat atau rencana, sedangkan -자마자 murni tentang urutan waktu yang langsung dan juga berlaku untuk peristiwa yang tidak direncanakan. 도착하는 대로 연락할게요 "saya akan menghubungi begitu saya tiba" (saya berniat melakukannya, pada saat saya tiba) versus 도착하자마자 비가 왔어요 "begitu saya tiba, hujan turun" — di sini 는 대로 terdengar janggal karena tidak ada yang merencanakan hujan. Kedua bentuk netral dari segi ragam bahasa; kesopanan terletak pada akhiran terakhir (연락할게요 vs. 연락하겠습니다). Kesalahan paling umum bagi pembelajar adalah memakai bentuk lampau -(으)ㄴ 대로 untuk makna masa depan "segera setelah"; untuk "tepat setelah", selalu pertahankan bentuk kini 는 대로 (가는 대로, bukan 간 대로). Ingatlah bahwa bentuk lampau 본 대로/들은 대로 berarti "persis seperti (yang saya lihat/dengar)", makna cara, bukan makna waktu.',
      '-(으)ㄴ/는 대로 gắn vào gốc động từ và mang nghĩa "theo / đúng như / y như", hoặc — tùy theo thì — "ngay sau khi". Với động từ ở thì hiện tại, nó dùng 는 대로 bất kể có 받침 hay không (가다 → 가는 대로 "khi bạn đi", 먹다 → 먹는 대로 "khi bạn ăn / ngay sau khi ăn"). Với động từ ở thì quá khứ, nó theo dạng -(으)ㄴ: gốc kết thúc bằng nguyên âm hoặc ㄹ dùng -ㄴ 대로 (보다 → 본 대로 "đúng như tôi đã thấy"), còn gốc kết thúc bằng phụ âm dùng -은 대로 (받다 → 받은 대로 "đúng như tôi đã nhận"). Lưu ý rằng 듣다 là động từ bất quy tắc ㄷ: ㄷ biến thành ㄹ và thêm -은, tạo thành 들은 대로 "đúng y như tôi đã nghe". Nó cũng có thể đi trực tiếp sau danh từ (사실대로 "đúng sự thật / như nó vốn có", 마음대로 "tùy ý", 약속대로 "như đã hứa"), khi đó mang nghĩa "theo N".\n\nNgười hàng xóm gần nhất cần lưu ý là -자마자 ("ngay khi"). Cả hai đều có thể diễn đạt "ngay sau khi", nhưng 는 대로 mang sắc thái thực hiện hành động thứ hai không chậm trễ và thường ngụ ý ý định hoặc kế hoạch, trong khi -자마자 thuần túy nói về trình tự thời gian tức thì và cũng dùng được cho những sự việc không định trước. 도착하는 대로 연락할게요 "tôi sẽ liên lạc ngay khi tôi đến" (tôi có ý định làm vậy, ngay khoảnh khắc tôi đến) so với 도착하자마자 비가 왔어요 "vừa đến nơi thì trời mưa" — ở đây 는 대로 nghe lạ tai vì không ai lên kế hoạch cho cơn mưa cả. Cả hai dạng đều trung tính về sắc thái lịch sự; mức độ lịch sự nằm ở đuôi câu cuối cùng (연락할게요 so với 연락하겠습니다). Lỗi phổ biến nhất của người học là dùng dạng quá khứ -(으)ㄴ 대로 cho nghĩa tương lai "ngay khi"; với nghĩa "ngay sau khi", hãy luôn giữ dạng hiện tại 는 대로 (가는 대로, không phải 간 대로). Hãy nhớ rằng dạng quá khứ 본 대로/들은 대로 mang nghĩa "đúng y như (tôi đã thấy/nghe)", tức nghĩa về cách thức, chứ không phải nghĩa về thời điểm.',
      '-(으)ㄴ/는 대로 は動詞の語幹に付き、「〜のとおりに/〜と同じように/ちょうど〜のとおり」、あるいは時制によっては「〜したらすぐに」という意味になります。現在形の動詞では、받침の有無にかかわらず 는 대로 を取ります（가다 → 가는 대로「行くとおりに」、먹다 → 먹는 대로「食べるそばから/食べたらすぐ」）。過去形の動詞では -(으)ㄴ のパターンに従い、母音語幹または ㄹ 語幹は -ㄴ 대로 を取り（보다 → 본 대로「見たとおりに」）、子音語幹は -은 대로 を取ります（받다 → 받은 대로「受け取ったとおりに」）。なお 듣다 は ㄷ不規則で、ㄷ が ㄹ に変わって -은 が付き、들은 대로「聞いたとおりに」となります。また名詞に直接付くこともでき（사실대로「ありのままに/正直に」、마음대로「気のままに」、약속대로「約束どおりに」）、その場合は「Nのとおりに」という意味になります。\n\n最も注意すべき近い表現は -자마자（「〜するやいなや」）です。どちらも「〜したらすぐに」と訳せますが、는 대로 は二つ目の動作を遅れずに行うという含みがあり、しばしば意図や計画を暗示します。一方 -자마자 は純粋に直後の時間的な前後関係を表し、計画外の出来事にも使えます。도착하는 대로 연락할게요「着いたらすぐに連絡します」（着いた瞬間にそうするつもりだ）に対し、도착하자마자 비가 왔어요「着いたとたんに雨が降った」— ここで 는 대로 は不自然です。誰も雨を計画していないからです。どちらの形も文体的には中立で、丁寧さは文末の語尾に宿ります（연락할게요 と 연락하겠습니다 の違い）。学習者の最も多い間違いは、未来の「〜したらすぐに」の意味で過去形の -(으)ㄴ 대로 を使ってしまうことです。「〜したらすぐに」には必ず現在形の 는 대로 を保ってください（가는 대로 であり、간 대로 ではありません）。過去形の 본 대로/들은 대로 は「（見た/聞いた）とおりに」という様態の意味であり、タイミングの意味ではないことを覚えておきましょう。',
    ),
  '-(으)ㄹ 만하다': L(
      'Expresses that something is "worth doing" or, when negated/qualified, "tolerable / bearable / passable" — it rates whether an action has enough value or is endurable enough to be worth the effort. It attaches to a verb stem: a vowel or ㄹ stem takes -ㄹ 만하다 (보다 → 볼 만하다 "worth seeing", 살다 → 살 만하다 "livable / bearable", ㄹ kept), while a consonant (받침) stem takes -을 만하다 (먹다 → 먹을 만하다 "edible / worth eating", 믿다 → 믿을 만하다 "trustworthy"). 만하다 then conjugates normally: 볼 만해요, 볼 만했어요 (past), 볼 만할 거예요 (future). 그 영화 정말 볼 만해요 = "That movie is really worth watching."\n\nCompare it with -(으)ㄹ 수 있다, which marks plain ability/possibility ("can"), not worth: 이 음식은 먹을 수 있어요 just means "I can eat this food (it\'s edible)," whereas 이 음식은 먹을 만해요 means "this food is decent enough to eat / passable" — a verdict on value, not capacity. Register is neutral and works in both 해요체 and formal 합니다체 (볼 만합니다). The most common learner mistake is dropping the future-marking ㄹ/을 and saying 보 만하다 or treating 만하다 as a noun; remember the ㄹ/을 is obligatory and 만 here is the "worth" 만, not the 만 meaning "only." In speech you\'ll often hear it shortened in casual judgments like 갈 만해, 쓸 만해 ("it\'ll do / it\'s usable").',
      'Expresa que algo "vale la pena hacer" o, cuando se niega o matiza, "es tolerable / soportable / pasable" — califica si una acción tiene suficiente valor o es lo bastante llevadera como para que valga el esfuerzo. Se une a una raíz verbal: una raíz terminada en vocal o en ㄹ toma -ㄹ 만하다 (보다 → 볼 만하다 "vale la pena ver", 살다 → 살 만하다 "habitable / llevadero", se conserva la ㄹ), mientras que una raíz con consonante final (받침) toma -을 만하다 (먹다 → 먹을 만하다 "comestible / vale la pena comer", 믿다 → 믿을 만하다 "fiable"). Después 만하다 se conjuga con normalidad: 볼 만해요, 볼 만했어요 (pasado), 볼 만할 거예요 (futuro). 그 영화 정말 볼 만해요 = "Esa película realmente vale la pena verla".\n\nComparalo con -(으)ㄹ 수 있다, que marca simple capacidad/posibilidad ("poder"), no valor: 이 음식은 먹을 수 있어요 solo significa "puedo comer esta comida (es comestible)", mientras que 이 음식은 먹을 만해요 significa "esta comida es lo bastante decente como para comerse / pasable" — un veredicto sobre el valor, no sobre la capacidad. El registro es neutro y funciona tanto en 해요체 como en el formal 합니다체 (볼 만합니다). El error más común de quien aprende es soltar la ㄹ/을 que marca el futuro y decir 보 만하다, o tratar 만하다 como un sustantivo; acordate de que la ㄹ/을 es obligatoria y que el 만 de acá es el 만 de "valer", no el 만 que significa "solo". En el habla vas a oírlo acortado a menudo en juicios casuales como 갈 만해, 쓸 만해 ("sirve / se puede usar").',
      'Exprime que quelque chose « vaut la peine d\'être fait » ou, à la forme négative ou nuancée, « est tolérable / supportable / passable » — cela évalue si une action a assez de valeur ou est assez endurable pour mériter l\'effort. La forme s\'attache à un radical verbal : un radical en voyelle ou en ㄹ prend -ㄹ 만하다 (보다 → 볼 만하다 « qui vaut la peine d\'être vu », 살다 → 살 만하다 « vivable / supportable », le ㄹ est conservé), tandis qu\'un radical à consonne finale (받침) prend -을 만하다 (먹다 → 먹을 만하다 « mangeable / qui vaut la peine d\'être mangé », 믿다 → 믿을 만하다 « digne de confiance »). 만하다 se conjugue ensuite normalement : 볼 만해요, 볼 만했어요 (passé), 볼 만할 거예요 (futur). 그 영화 정말 볼 만해요 = « Ce film vaut vraiment la peine d\'être vu. »\n\nCompare-le avec -(으)ㄹ 수 있다, qui marque la simple capacité/possibilité (« pouvoir »), et non la valeur : 이 음식은 먹을 수 있어요 signifie seulement « je peux manger cette nourriture (elle est mangeable) », alors que 이 음식은 먹을 만해요 signifie « cette nourriture est assez correcte pour être mangée / passable » — un verdict sur la valeur, pas sur la capacité. Le registre est neutre et fonctionne aussi bien en 해요체 qu\'en 합니다체 formel (볼 만합니다). L\'erreur la plus fréquente chez l\'apprenant est d\'omettre le ㄹ/을 marquant le futur et de dire 보 만하다, ou de traiter 만하다 comme un nom ; rappelle-toi que le ㄹ/을 est obligatoire et que le 만 ici est le 만 de « valeur », pas le 만 qui signifie « seulement ». À l\'oral, tu l\'entendras souvent raccourci dans des jugements familiers comme 갈 만해, 쓸 만해 (« ça fera l\'affaire / c\'est utilisable »).',
      'Expressa que algo "vale a pena fazer" ou, quando negado ou qualificado, "é tolerável / suportável / passável" — avalia se uma ação tem valor suficiente ou é suportável o bastante para valer o esforço. Liga-se a um radical verbal: um radical terminado em vogal ou em ㄹ recebe -ㄹ 만하다 (보다 → 볼 만하다 "vale a pena ver", 살다 → 살 만하다 "habitável / suportável", o ㄹ é mantido), enquanto um radical com consoante final (받침) recebe -을 만하다 (먹다 → 먹을 만하다 "comestível / vale a pena comer", 믿다 → 믿을 만하다 "confiável"). Depois 만하다 conjuga normalmente: 볼 만해요, 볼 만했어요 (passado), 볼 만할 거예요 (futuro). 그 영화 정말 볼 만해요 = "Esse filme realmente vale a pena assistir."\n\nCompare com -(으)ㄹ 수 있다, que marca simples capacidade/possibilidade ("conseguir / poder"), não valor: 이 음식은 먹을 수 있어요 significa apenas "eu consigo comer essa comida (ela é comestível)", ao passo que 이 음식은 먹을 만해요 significa "essa comida é boa o suficiente para se comer / passável" — um veredito sobre o valor, não sobre a capacidade. O registro é neutro e funciona tanto no 해요체 quanto no formal 합니다체 (볼 만합니다). O erro mais comum de quem está aprendendo é omitir o ㄹ/을 que marca o futuro e dizer 보 만하다, ou tratar 만하다 como um substantivo; lembre-se de que o ㄹ/을 é obrigatório e que o 만 aqui é o 만 de "valor", não o 만 que significa "apenas". Na fala, você vai ouvi-lo muitas vezes encurtado em julgamentos informais como 갈 만해, 쓸 만해 ("dá pro gasto / dá pra usar").',
      'แสดงว่าสิ่งใดสิ่งหนึ่ง "คุ้มค่าที่จะทำ" หรือเมื่อใช้ในรูปปฏิเสธหรือมีเงื่อนไข ก็หมายถึง "พอทนได้ / พอรับได้ / พอใช้ได้" — เป็นการประเมินว่าการกระทำนั้นมีคุณค่ามากพอหรือทนได้มากพอที่จะคุ้มกับความพยายามหรือไม่ มันเติมเข้ากับรากศัพท์กริยา: รากที่ลงท้ายด้วยสระหรือ ㄹ ใช้ -ㄹ 만하다 (보다 → 볼 만하다 "ควรค่าแก่การดู", 살다 → 살 만하다 "พออยู่ได้ / พอทนได้" โดยคง ㄹ ไว้) ส่วนรากที่มีตัวสะกดพยัญชนะ (받침) ใช้ -을 만하다 (먹다 → 먹을 만하다 "กินได้ / ควรค่าแก่การกิน", 믿다 → 믿을 만하다 "น่าเชื่อถือ") จากนั้น 만하다 ก็ผันตามปกติ: 볼 만해요, 볼 만했어요 (อดีต), 볼 만할 거예요 (อนาคต) 그 영화 정말 볼 만해요 = "หนังเรื่องนั้นน่าดูจริง ๆ"\n\nลองเปรียบเทียบกับ -(으)ㄹ 수 있다 ซึ่งบ่งบอกความสามารถ/ความเป็นไปได้ล้วน ๆ ("ทำได้") ไม่ใช่คุณค่า: 이 음식은 먹을 수 있어요 แปลว่า "ฉันกินอาหารนี้ได้ (มันกินได้)" เฉย ๆ ในขณะที่ 이 음식은 먹을 만해요 แปลว่า "อาหารนี้ดีพอที่จะกินได้ / พอใช้ได้" — เป็นการตัดสินเรื่องคุณค่า ไม่ใช่ความสามารถ ระดับภาษาเป็นกลางและใช้ได้ทั้งใน 해요체 และ 합니다체 ที่เป็นทางการ (볼 만합니다) ข้อผิดพลาดที่ผู้เรียนพบบ่อยที่สุดคือการละ ㄹ/을 ที่บ่งบอกอนาคตแล้วพูดว่า 보 만하다 หรือมองว่า 만하다 เป็นคำนาม จำไว้ว่า ㄹ/을 เป็นสิ่งที่ต้องมีเสมอ และ 만 ในที่นี้คือ 만 ที่แปลว่า "คุ้มค่า" ไม่ใช่ 만 ที่แปลว่า "เท่านั้น" ในภาษาพูดคุณจะได้ยินมันถูกย่อบ่อย ๆ ในการตัดสินแบบลำลอง เช่น 갈 만해, 쓸 만해 ("ก็พอไหว / พอใช้ได้")',
      'Menyatakan bahwa sesuatu "layak/patut dilakukan" atau, ketika dinegasikan atau diberi syarat, "masih bisa ditoleransi / tertahankan / lumayan" — bentuk ini menilai apakah suatu tindakan punya cukup nilai atau cukup bisa ditahan sehingga sepadan dengan usahanya. Ia melekat pada akar kata kerja: akar berakhiran vokal atau ㄹ memakai -ㄹ 만하다 (보다 → 볼 만하다 "layak ditonton", 살다 → 살 만하다 "layak ditinggali / masih bisa dijalani", ㄹ tetap dipertahankan), sedangkan akar berkonsonan akhir (받침) memakai -을 만하다 (먹다 → 먹을 만하다 "bisa dimakan / layak dimakan", 믿다 → 믿을 만하다 "bisa dipercaya"). Setelah itu 만하다 dikonjugasikan secara normal: 볼 만해요, 볼 만했어요 (lampau), 볼 만할 거예요 (masa depan). 그 영화 정말 볼 만해요 = "Film itu benar-benar layak ditonton."\n\nBandingkan dengan -(으)ㄹ 수 있다, yang menandai kemampuan/kemungkinan biasa ("bisa"), bukan nilai: 이 음식은 먹을 수 있어요 hanya berarti "saya bisa makan makanan ini (makanan ini bisa dimakan)", sementara 이 음식은 먹을 만해요 berarti "makanan ini cukup layak untuk dimakan / lumayan" — sebuah penilaian atas nilai, bukan atas kemampuan. Ragamnya netral dan bisa dipakai baik dalam 해요체 maupun 합니다체 yang formal (볼 만합니다). Kesalahan paling umum yang dilakukan pembelajar adalah menghilangkan ㄹ/을 penanda masa depan sehingga menjadi 보 만하다, atau memperlakukan 만하다 sebagai kata benda; ingatlah bahwa ㄹ/을 itu wajib, dan 만 di sini adalah 만 yang berarti "layak", bukan 만 yang berarti "hanya". Dalam percakapan kamu akan sering mendengarnya dipersingkat dalam penilaian santai seperti 갈 만해, 쓸 만해 ("ya boleh lah / masih bisa dipakai").',
      'Diễn tả rằng một điều gì đó "đáng làm" hoặc, khi ở dạng phủ định hay có điều kiện, "có thể chịu được / chấp nhận được / tạm ổn" — nó đánh giá xem một hành động có đủ giá trị hoặc đủ dễ chịu để bỏ công sức ra hay không. Nó gắn vào gốc động từ: gốc kết thúc bằng nguyên âm hoặc bằng ㄹ dùng -ㄹ 만하다 (보다 → 볼 만하다 "đáng xem", 살다 → 살 만하다 "đáng sống / chịu đựng được", ㄹ được giữ lại), còn gốc có phụ âm cuối (받침) dùng -을 만하다 (먹다 → 먹을 만하다 "ăn được / đáng ăn", 믿다 → 믿을 만하다 "đáng tin"). Sau đó 만하다 chia bình thường: 볼 만해요, 볼 만했어요 (quá khứ), 볼 만할 거예요 (tương lai). 그 영화 정말 볼 만해요 = "Bộ phim đó thực sự đáng xem."\n\nHãy so sánh với -(으)ㄹ 수 있다, vốn đánh dấu khả năng/tính khả thi đơn thuần ("có thể"), chứ không phải giá trị: 이 음식은 먹을 수 있어요 chỉ có nghĩa "tôi có thể ăn món này (nó ăn được)", trong khi 이 음식은 먹을 만해요 có nghĩa "món này đủ ngon để ăn / tạm ổn" — một sự đánh giá về giá trị, không phải về khả năng. Sắc thái ngôn ngữ trung tính và dùng được cả trong 해요체 lẫn 합니다체 trang trọng (볼 만합니다). Lỗi phổ biến nhất của người học là bỏ mất ㄹ/을 đánh dấu tương lai rồi nói 보 만하다, hoặc coi 만하다 như một danh từ; hãy nhớ rằng ㄹ/을 là bắt buộc và 만 ở đây là 만 mang nghĩa "đáng giá", chứ không phải 만 mang nghĩa "chỉ". Trong lời nói, bạn sẽ thường nghe nó được rút gọn trong những nhận xét thân mật như 갈 만해, 쓸 만해 ("cũng tạm / dùng được đấy").',
      '何かが「やる価値がある」こと、あるいは否定や条件をつけた場合には「我慢できる／耐えられる／まあまあ通用する」ことを表します。つまり、その動作に取り組むだけの価値が十分にあるか、あるいは十分に耐えられるかを評価する表現です。動詞の語幹に付き、母音語幹や ㄹ 語幹には -ㄹ 만하다 が付きます（보다 → 볼 만하다「見る価値がある」、살다 → 살 만하다「住める／なんとか暮らせる」、ㄹ はそのまま残る）。一方、子音（받침）で終わる語幹には -을 만하다 が付きます（먹다 → 먹을 만하다「食べられる／食べる価値がある」、믿다 → 믿을 만하다「信頼できる」）。そのあと 만하다 は普通に活用します。볼 만해요、볼 만했어요（過去）、볼 만할 거예요（未来）。그 영화 정말 볼 만해요 =「あの映画は本当に見る価値があります。」\n\nこれを -(으)ㄹ 수 있다 と比べてみましょう。こちらは単なる能力・可能性（「〜できる」）を表し、価値を表すわけではありません。이 음식은 먹을 수 있어요 は単に「この料理は食べられます（食べることが可能だ）」という意味ですが、이 음식은 먹을 만해요 は「この料理はそこそこ食べられる／まあまあだ」という意味で、能力ではなく価値についての判断です。語調は中立的で、해요체 でも丁寧な 합니다체 でも使えます（볼 만합니다）。学習者がいちばんよくする間違いは、未来を示す ㄹ/을 を落として 보 만하다 と言ってしまったり、만하다 を名詞のように扱ったりすることです。ここでの ㄹ/을 は必須であり、この 만 は「価値」の 만 であって「〜だけ」を意味する 만 ではないと覚えておきましょう。話し言葉では、갈 만해、쓸 만해（「まあいける／使える」）のようなくだけた判断で短縮されて聞こえることがよくあります。',
    ),
  '-(으)ㄹ 정도로': L(
      'Expresses that something reaches an extreme degree — "to the point of / so... that...". The whole clause describes how intense an action or state is by pinning it to a vivid yardstick. Form: it attaches to a verb or adjective stem. Vowel/ㄹ stem → -ㄹ 정도로 (아프다 → 아플 정도로 "to the point of hurting", 울다 → 울 정도로 "enough to cry", the ㄹ-stem ㄹ is kept and absorbs the ending); consonant stem (받침) → -을 정도로 (먹다 → 먹을 정도로, 죽다 → 죽을 정도로 "to the point of dying/to death"). With nouns you instead say N + 정도(로) ("about/roughly," a different sense), so 정도로 in this grammar lives on a verb/adjective. Example: 다리가 떨어질 정도로 많이 걸었어요 "I walked so much my legs felt like falling off."\n\nClose neighbor to watch: -(으)ㄹ 만큼. In the pure degree sense the two are often interchangeable: 죽을 정도로 힘들었어요 and 죽을 만큼 힘들었어요 both mean "it was hard to the point of dying." The slight nuance is that -(으)ㄹ 정도로 frames the clause as the threshold an action/state reaches ("so... that..."), while -(으)ㄹ 만큼 also covers a proportional "as much as / in proportion to" use that 정도로 does not — e.g. 노력한 만큼 결과가 나와요 "you get results in proportion to how hard you tried," where 정도로 would not fit. Register is neutral — fine in both casual and polite speech. The most common learner mistake is dropping 로 and leaving bare 정도 (which then reads as "around/approximately"), or wrongly attaching it to a noun stem directly; keep it on a verb/adjective. In speech 정도로 is sometimes shortened to 정도, but the result-clause meaning still needs the verb/adjective stem before it.',
      'Expresa que algo llega a un grado extremo — "hasta el punto de / tan... que...". Toda la cláusula describe lo intensa que es una acción o un estado anclándolo a un patrón de medida muy vívido. Forma: se pega a la raíz de un verbo o un adjetivo. Raíz terminada en vocal o en ㄹ → -ㄹ 정도로 (아프다 → 아플 정도로 "hasta el punto de doler", 울다 → 울 정도로 "tanto como para llorar"; la ㄹ de la raíz en ㄹ se mantiene y absorbe la terminación); raíz terminada en consonante (받침) → -을 정도로 (먹다 → 먹을 정도로, 죽다 → 죽을 정도로 "hasta el punto de morir / a morir"). Con sustantivos en cambio decís N + 정도(로) ("más o menos, aproximadamente", un sentido distinto), así que el 정도로 de esta gramática vive sobre un verbo o adjetivo. Ejemplo: 다리가 떨어질 정도로 많이 걸었어요 "Caminé tanto que sentía que se me caían las piernas."\n\nVecino cercano al que prestar atención: -(으)ㄹ 만큼. En el sentido puro de grado, los dos suelen ser intercambiables: 죽을 정도로 힘들었어요 y 죽을 만큼 힘들었어요 significan ambos "fue difícil hasta el punto de morir." El matiz sutil es que -(으)ㄹ 정도로 enmarca la cláusula como el umbral que alcanza una acción o estado ("tan... que..."), mientras que -(으)ㄹ 만큼 cubre además un uso proporcional de "tanto como / en proporción a" que 정도로 no tiene — p. ej. 노력한 만큼 결과가 나와요 "obtenés resultados en proporción a lo que te esforzaste", donde 정도로 no encajaría. El registro es neutral — está bien tanto en el habla informal como en la cortés. El error más común del estudiante es soltar el 로 y dejar 정도 a secas (que entonces se lee como "alrededor de / aproximadamente"), o pegarlo por error directamente a una raíz nominal; mantenelo sobre un verbo o adjetivo. En el habla, 정도로 a veces se acorta a 정도, pero el significado de cláusula-resultado todavía necesita la raíz del verbo o adjetivo delante.',
      'Exprime que quelque chose atteint un degré extrême — "au point de / tellement... que...". Toute la proposition décrit à quel point une action ou un état est intense en la rattachant à un repère bien parlant. Forme : il s\'attache à la racine d\'un verbe ou d\'un adjectif. Racine en voyelle ou en ㄹ → -ㄹ 정도로 (아프다 → 아플 정도로 "au point d\'avoir mal", 울다 → 울 정도로 "au point de pleurer" ; le ㄹ de la racine en ㄹ est conservé et absorbe la terminaison) ; racine en consonne (받침) → -을 정도로 (먹다 → 먹을 정도로, 죽다 → 죽을 정도로 "au point de mourir / à en mourir"). Avec des noms, tu dis plutôt N + 정도(로) ("environ / à peu près", un autre sens), donc le 정도로 de cette grammaire vit sur un verbe ou un adjectif. Exemple : 다리가 떨어질 정도로 많이 걸었어요 "J\'ai tellement marché que j\'avais l\'impression que mes jambes allaient tomber."\n\nVoisin proche à surveiller : -(으)ㄹ 만큼. Dans le sens pur de degré, les deux sont souvent interchangeables : 죽을 정도로 힘들었어요 et 죽을 만큼 힘들었어요 veulent tous deux dire "c\'était dur au point d\'en mourir." La nuance légère, c\'est que -(으)ㄹ 정도로 présente la proposition comme le seuil qu\'atteint une action ou un état ("tellement... que..."), tandis que -(으)ㄹ 만큼 couvre aussi un emploi proportionnel "autant que / en proportion de" que 정도로 n\'a pas — p. ex. 노력한 만큼 결과가 나와요 "tu obtiens des résultats à la hauteur de tes efforts", là où 정도로 ne conviendrait pas. Le registre est neutre — convient aussi bien à l\'oral familier qu\'au discours poli. L\'erreur la plus fréquente chez l\'apprenant est d\'oublier le 로 et de laisser 정도 tout seul (qui se lit alors "environ / à peu près"), ou de l\'attacher à tort directement à une racine nominale ; garde-le sur un verbe ou un adjectif. À l\'oral, 정도로 se raccourcit parfois en 정도, mais le sens de proposition-résultat exige toujours la racine du verbe ou de l\'adjectif devant.',
      'Expressa que algo chega a um grau extremo — "a ponto de / tão... que...". A oração inteira descreve o quão intensa é uma ação ou um estado, fixando-a a uma medida bem vívida. Forma: ela se liga à raiz de um verbo ou adjetivo. Raiz terminada em vogal ou em ㄹ → -ㄹ 정도로 (아프다 → 아플 정도로 "a ponto de doer", 울다 → 울 정도로 "a ponto de chorar"; o ㄹ da raiz em ㄹ é mantido e absorve a terminação); raiz terminada em consoante (받침) → -을 정도로 (먹다 → 먹을 정도로, 죽다 → 죽을 정도로 "a ponto de morrer / até morrer"). Com substantivos, em vez disso você diz N + 정도(로) ("cerca de / aproximadamente", um sentido diferente), então o 정도로 desta gramática vive sobre um verbo ou adjetivo. Exemplo: 다리가 떨어질 정도로 많이 걸었어요 "Andei tanto que parecia que minhas pernas iam cair."\n\nVizinho próximo para ficar de olho: -(으)ㄹ 만큼. No sentido puro de grau, os dois costumam ser intercambiáveis: 죽을 정도로 힘들었어요 e 죽을 만큼 힘들었어요 ambos significam "foi difícil a ponto de morrer." A nuance sutil é que -(으)ㄹ 정도로 enquadra a oração como o limite que uma ação ou estado atinge ("tão... que..."), enquanto -(으)ㄹ 만큼 também cobre um uso proporcional de "tanto quanto / na proporção de" que 정도로 não tem — por exemplo, 노력한 만큼 결과가 나와요 "você obtém resultados na proporção do seu esforço", onde 정도로 não caberia. O registro é neutro — serve tanto na fala casual quanto na polida. O erro mais comum do aprendiz é largar o 로 e deixar 정도 sozinho (que então se lê como "por volta de / aproximadamente"), ou ligá-lo erroneamente direto a uma raiz nominal; mantenha-o sobre um verbo ou adjetivo. Na fala, 정도로 às vezes é encurtado para 정도, mas o sentido de oração-resultado ainda precisa da raiz do verbo ou adjetivo antes dele.',
      'แสดงว่าบางสิ่งไปถึงระดับสุดขีด — "จนถึงขั้น / ...มากจน...". ทั้งอนุประโยคบรรยายว่าการกระทำหรือสภาวะหนึ่งเข้มข้นแค่ไหน โดยเทียบกับมาตรวัดที่เห็นภาพชัดเจน รูปแบบ: เติมท้ายรากของคำกริยาหรือคำคุณศัพท์ รากที่ลงท้ายด้วยสระหรือ ㄹ → -ㄹ 정도로 (아프다 → 아플 정도로 "จนถึงขั้นเจ็บ", 울다 → 울 정도로 "มากพอจะร้องไห้" โดย ㄹ ของรากที่ลงท้ายด้วย ㄹ จะคงไว้และกลืนกับท้ายคำ); รากที่ลงท้ายด้วยพยัญชนะ (받침) → -을 정도로 (먹다 → 먹을 정도로, 죽다 → 죽을 정도로 "จนถึงขั้นตาย / จนตาย"). ส่วนกับคำนามนั้นคุณจะพูดว่า N + 정도(로) แทน ("ราว ๆ / ประมาณ" ซึ่งเป็นอีกความหมายหนึ่ง) ดังนั้น 정도로 ในไวยากรณ์นี้จึงอยู่กับคำกริยาหรือคำคุณศัพท์ ตัวอย่าง: 다리가 떨어질 정도로 많이 걸었어요 "ฉันเดินมากจนรู้สึกว่าขาจะหลุดออกมาเลย"\n\nเพื่อนบ้านใกล้ตัวที่ต้องระวัง: -(으)ㄹ 만큼 ในความหมายเชิงระดับล้วน ๆ ทั้งสองมักใช้แทนกันได้: 죽을 정도로 힘들었어요 และ 죽을 만큼 힘들었어요 ต่างก็แปลว่า "มันยากจนถึงขั้นจะตาย" ความต่างเล็กน้อยคือ -(으)ㄹ 정도로 วางกรอบให้อนุประโยคเป็นเกณฑ์ที่การกระทำหรือสภาวะไปถึง ("...มากจน...") ส่วน -(으)ㄹ 만큼 ยังครอบคลุมการใช้แบบสัดส่วน "มากเท่ากับ / ตามสัดส่วนของ" ที่ 정도로 ไม่มี — เช่น 노력한 만큼 결과가 나와요 "ผลลัพธ์จะออกมาตามสัดส่วนของความพยายามที่ทุ่มลงไป" ซึ่ง 정도로 จะใช้ไม่ได้ ระดับภาษาเป็นกลาง — ใช้ได้ทั้งในการพูดแบบกันเองและแบบสุภาพ ข้อผิดพลาดที่ผู้เรียนพบบ่อยที่สุดคือการตัด 로 ทิ้งแล้วเหลือ 정도 เปล่า ๆ (ซึ่งจะอ่านได้ว่า "ราว ๆ / โดยประมาณ") หรือนำไปต่อท้ายรากคำนามโดยตรงอย่างผิด ๆ ให้คงไว้กับคำกริยาหรือคำคุณศัพท์ ในการพูด 정도로 บางครั้งถูกย่อเหลือ 정도 แต่ความหมายแบบอนุประโยค-ผลลัพธ์ก็ยังต้องมีรากของคำกริยาหรือคำคุณศัพท์อยู่ข้างหน้า',
      'Menyatakan bahwa sesuatu mencapai derajat ekstrem — "sampai-sampai / begitu... sehingga...". Seluruh klausa menggambarkan betapa intensnya suatu tindakan atau keadaan dengan mematoknya pada tolok ukur yang sangat hidup. Bentuk: melekat pada akar kata kerja atau kata sifat. Akar berakhiran vokal atau ㄹ → -ㄹ 정도로 (아프다 → 아플 정도로 "sampai-sampai sakit", 울다 → 울 정도로 "sampai mau menangis"; ㄹ pada akar ㄹ tetap dipertahankan dan menyerap akhiran); akar berakhiran konsonan (받침) → -을 정도로 (먹다 → 먹을 정도로, 죽다 → 죽을 정도로 "sampai-sampai mati / sampai mati"). Dengan kata benda, kamu justru mengatakan N + 정도(로) ("sekitar / kira-kira", makna yang berbeda), jadi 정도로 dalam tata bahasa ini melekat pada kata kerja atau kata sifat. Contoh: 다리가 떨어질 정도로 많이 걸었어요 "Saya berjalan begitu banyak sampai kaki rasanya mau copot."\n\nTetangga dekat yang perlu diwaspadai: -(으)ㄹ 만큼. Dalam makna derajat murni, keduanya sering bisa saling dipertukarkan: 죽을 정도로 힘들었어요 dan 죽을 만큼 힘들었어요 sama-sama berarti "sulitnya sampai mau mati." Nuansa halusnya, -(으)ㄹ 정도로 membingkai klausa sebagai ambang yang dicapai suatu tindakan atau keadaan ("begitu... sehingga..."), sementara -(으)ㄹ 만큼 juga mencakup pemakaian proporsional "sebanyak / sebanding dengan" yang tidak dimiliki 정도로 — misalnya 노력한 만큼 결과가 나와요 "hasil yang kamu peroleh sebanding dengan seberapa keras kamu berusaha", di situ 정도로 tidak akan cocok. Ragamnya netral — pas dipakai baik dalam tutur santai maupun sopan. Kesalahan pemelajar yang paling umum adalah membuang 로 dan menyisakan 정도 polos (yang lalu terbaca "sekitar / kurang lebih"), atau keliru melekatkannya langsung pada akar kata benda; tetap pasang pada kata kerja atau kata sifat. Dalam tuturan, 정도로 kadang dipersingkat menjadi 정도, tetapi makna klausa-hasilnya tetap memerlukan akar kata kerja atau kata sifat di depannya.',
      'Diễn tả rằng điều gì đó đạt đến một mức độ cực điểm — "đến mức / ...đến nỗi...". Cả mệnh đề mô tả một hành động hay trạng thái mãnh liệt đến đâu bằng cách gắn nó vào một thước đo thật sống động. Cấu trúc: gắn vào gốc động từ hoặc tính từ. Gốc kết thúc bằng nguyên âm hoặc ㄹ → -ㄹ 정도로 (아프다 → 아플 정도로 "đến mức đau", 울다 → 울 정도로 "đến mức phát khóc"; chữ ㄹ của gốc ㄹ được giữ lại và hòa vào đuôi); gốc kết thúc bằng phụ âm (받침) → -을 정도로 (먹다 → 먹을 정도로, 죽다 → 죽을 정도로 "đến mức chết / đến chết"). Còn với danh từ thì bạn nói N + 정도(로) ("khoảng / xấp xỉ", một nghĩa khác), nên 정도로 trong ngữ pháp này phải đi với động từ hoặc tính từ. Ví dụ: 다리가 떨어질 정도로 많이 걸었어요 "Tôi đi bộ nhiều đến mức cảm tưởng chân muốn rụng ra."\n\nNgười hàng xóm gần cần để ý: -(으)ㄹ 만큼. Ở nghĩa mức độ thuần túy, hai cấu trúc thường thay thế được cho nhau: 죽을 정도로 힘들었어요 và 죽을 만큼 힘들었어요 đều có nghĩa "mệt đến mức muốn chết." Sắc thái khác biệt nhỏ là -(으)ㄹ 정도로 đóng khung mệnh đề như ngưỡng mà một hành động hay trạng thái đạt tới ("...đến nỗi..."), trong khi -(으)ㄹ 만큼 còn bao hàm cả cách dùng theo tỉ lệ "nhiều bằng / tương xứng với" mà 정도로 không có — ví dụ 노력한 만큼 결과가 나와요 "bạn gặt hái kết quả tương xứng với mức bạn nỗ lực", chỗ này 정도로 sẽ không hợp. Sắc thái trung tính — dùng được cả trong lời nói thân mật lẫn lịch sự. Lỗi phổ biến nhất của người học là bỏ mất 로 và để trơ 정도 (lúc đó lại hiểu thành "khoảng / xấp xỉ"), hoặc gắn nhầm nó trực tiếp vào gốc danh từ; hãy giữ nó trên động từ hoặc tính từ. Trong khẩu ngữ, 정도로 đôi khi được rút gọn thành 정도, nhưng nghĩa mệnh đề-kết quả vẫn cần gốc động từ hoặc tính từ đứng trước.',
      '何かが極端な程度に達することを表します — 「~するほど / ~するくらい…」。節全体が、ある動作や状態がどれほど激しいかを、生き生きとした目安に結びつけて描きます。形：動詞・形容詞の語幹に付きます。母音語幹・ㄹ語幹 → -ㄹ 정도로(아프다 → 아플 정도로「痛いほど」、울다 → 울 정도로「泣くくらい」。ㄹ語幹の ㄹ は残って語尾を吸収します）。子音語幹（받침） → -을 정도로(먹다 → 먹을 정도로、죽다 → 죽을 정도로「死ぬほど」）。名詞には代わりに N + 정도(로)（「~くらい／およそ」という別の意味）と言うので、この文法の 정도로 は動詞・形容詞に付きます。例：다리가 떨어질 정도로 많이 걸었어요「足が取れそうなほどたくさん歩きました」。\n\n注意したい近い仲間：-(으)ㄹ 만큼。純粋な程度の意味では、両者はしばしば置き換え可能です。죽을 정도로 힘들었어요 も 죽을 만큼 힘들었어요 も、どちらも「死ぬほどつらかった」という意味です。微妙なニュアンスとして、-(으)ㄹ 정도로 は節を、動作や状態が達する境目（「~するほど…」）として枠づけます。一方 -(으)ㄹ 만큼 は、정도로 にはない「~に応じて／~に比例して」という比例の用法もカバーします。例えば 노력한 만큼 결과가 나와요「努力した分だけ結果が出ます」では 정도로 は合いません。語調は中立で、くだけた話し方にも丁寧な話し方にも使えます。学習者に最も多い間違いは、로 を落として 정도 だけにしてしまう（すると「~くらい／およそ」と読まれます）こと、または名詞語幹に直接付けてしまうことです。動詞・形容詞に付けましょう。話し言葉では 정도로 が 정도 と短縮されることもありますが、結果節の意味を出すには前に動詞・形容詞の語幹が必要です。',
    ),
}
